HT.CDF["G08"] = {"bang":[{"i":0,"tieu_de_bang":"Liên Xô – Petrograd và Mátxcơva","tieu_de":"Hai lần cập bến xứ tuyết: Liên Xô trên hành trình tìm đường của Nguyễn Ái Quốc","sapo":"Mùa hè năm 1923, một con tàu từ Hamburg cập bến Petrograd, mang theo người thợ ảnh có tên Chen Vang. Mùa hè năm 1934, một tàu buôn từ Thượng Hải cập cảng Vlađivôxtốc, chở một vị khách đặc biệt mà thuyền trưởng được dặn phải đón. Cả hai lần, người khách ấy là Nguyễn Ái Quốc. Giữa hai lần cập bến là mười một năm, và cả một chặng đường cách mạng.","bia":{"src":"textures/bai/G08_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Hai lần cập bến","text":"Ngày 30/6/1923, con tàu mang tên nhà cách mạng Đức Karl Liebknecht cập Bến số 7 cảng Gutuev, thuộc cảng Petrograd bên vịnh Phần Lan. Trong số hành khách có một thanh niên châu Á mang giấy thông hành đứng tên Chen Vang, nghề thợ ảnh. Đó là Nguyễn Ái Quốc, vừa thoát khỏi vòng theo dõi của mật thám Pháp ở Paris sau mười bảy ngày đi đường bí mật (xem chuyên đề Chuyến đi bí mật từ Paris tới Petrograd).\n\nMười một năm sau, tháng 6/1934, ở đầu kia của đất nước Xô-viết, một tàu buôn Liên Xô từ Thượng Hải cập cảng Vlađivôxtốc bên bờ Thái Bình Dương. Thuyền trưởng đã được báo trước rằng trên tàu sẽ có một vị khách đặc biệt. Người khách ấy lại là Nguyễn Ái Quốc, lần này vừa trải qua những năm bị giam giữ ở Hồng Kông và sống bí mật ở Thượng Hải. Lần thứ nhất, Người đến từ phía tây, như một người học trò háo hức tìm tới quê hương của Cách mạng Tháng Mười. Lần thứ hai, Người đến từ phía đông, như một chiến sĩ đã dày dạn, cần một nơi để học tập, tổng kết và chờ thời cơ trở về. Gian trưng bày này kể về hai chặng sống ấy trên đất Liên Xô.","doc":1},{"loai":"doan","tieu_de":"Vì sao là nước Nga Xô-viết?","text":"Con đường tới Mátxcơva bắt đầu từ Paris. Tháng 7/1920, Nguyễn Ái Quốc đọc bản Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của Lênin trên báo L'Humanité. Về sau, Người kể rằng chính lòng yêu nước, chứ chưa phải lý tưởng cộng sản, đã đưa Người đến với Lênin và Quốc tế thứ ba. Tháng 12/1920, tại Đại hội Tua, Người bỏ phiếu tán thành gia nhập Quốc tế Cộng sản và trở thành một trong những người tham gia sáng lập Đảng Cộng sản Pháp.\n\nBa năm tiếp theo, Người cùng các bạn lập Hội Liên hiệp thuộc địa, làm chủ bút tờ Le Paria và viết rất nhiều bài báo tố cáo chế độ thực dân. Nhưng Paris có những giới hạn của nó. Sách báo không thay được việc học lý luận một cách có hệ thống, còn mật thám thì bám theo từng bước chân. Người muốn đến tận nơi đặt trụ sở Quốc tế Cộng sản, tận mắt xem một nhà nước mới được xây dựng ra sao. Cơ hội đến từ chính Mátxcơva. Manuinxki (Dmitry Manuilsky), Ủy viên Ban Chấp hành Quốc tế Cộng sản, đề nghị Ban Chấp hành Trung ương Đảng Cộng sản Pháp cử Nguyễn Ái Quốc sang Liên Xô. Lời mời ấy mở ra chuyến đi mùa hè năm 1923.","doc":2},{"loai":"anh","src":"textures/ht/ht_anh_nguyen_ai_quoc_in_the_soviet_union_in_1923.jpg","chu_thich":"Nguyễn Ái Quốc ở Liên Xô năm 1923, trong những tháng đầu của chặng thứ nhất.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Nước Nga năm 1923","text":"Đất nước Người đặt chân tới khi ấy vừa bước ra khỏi gần bảy năm chiến tranh liên miên: Chiến tranh thế giới thứ nhất, cách mạng, rồi nội chiến và can thiệp của nước ngoài. Nạn đói những năm 1921 – 1922 ở vùng sông Vônga còn để lại vết thương sâu. Từ năm 1921, chính quyền Xô-viết thực hiện Chính sách kinh tế mới, cho phép buôn bán nhỏ và thị trường hoạt động trở lại. Mátxcơva năm 1923 vì thế mang hai gương mặt: khẩu hiệu cách mạng trên tường, bên cạnh những cửa hàng tư nhân vừa mở cửa trở lại.\n\nLiên bang Cộng hòa xã hội chủ nghĩa Xô-viết mới được thành lập từ cuối năm 1922. Mátxcơva đã là thủ đô từ năm 1918 và là nơi đặt trụ sở Quốc tế Cộng sản, tổ chức chung của các đảng cộng sản trên thế giới (xem chuyên đề Quốc tế Cộng sản). Người sáng lập nhà nước mới là Lênin thì khi ấy đã lâm bệnh nặng. Sau cơn đột quỵ tháng 3/1923, Lênin mất khả năng nói và phải điều trị ở Goócki, ngoại ô Mátxcơva. Người thanh niên Việt Nam đã vượt nửa vòng trái đất để tìm đến quê hương của học thuyết Lênin, nhưng không kịp gặp Lênin (xem chuyên đề Bài báo Lênin và các dân tộc thuộc địa).","doc":3},{"loai":"anh","src":"textures/bang_w/G08_0_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Liên Xô – Petrograd và Mátxcơva”, nhìn từ xa."},{"loai":"doan","tieu_de":"Mười sáu tháng của người học trò","text":"Chặng thứ nhất kéo dài từ cuối tháng 6/1923 đến cuối tháng 10/1924, dày đặc như một khóa học cấp tốc. Người làm việc với Quốc tế Cộng sản, và ngày 14/4/1924 được nhận làm cán bộ Ban Phương Đông, bộ phận theo dõi phong trào cách mạng ở châu Á. Cuối năm 1923, Người theo học lớp ngắn hạn của Trường Đại học Cộng sản của những người lao động phương Đông, thường gọi tắt là Trường Đại học Phương Đông.\n\nTháng 10/1923, tại Hội nghị Quốc tế Nông dân lần thứ nhất họp ở Mátxcơva, Người phát biểu tại hai phiên họp, nói về tình cảnh của nhân dân Đông Dương. Từ Mátxcơva, Người tiếp tục gửi bài cho các báo L'Humanité, La Vie Ouvrière, Le Paria, và viết cho tạp chí Thư tín quốc tế của Quốc tế Cộng sản. Tháng 1/1924, Người có mặt trong những ngày cả nước Nga tiễn đưa Lênin (xem chuyên đề Lăng gỗ tạm của Lênin). Mùa hè năm ấy, Người dự Đại hội V Quốc tế Cộng sản với tư cách đại biểu tư vấn, kiên trì đặt vấn đề thuộc địa trước các đảng anh em (xem chuyên đề Thẻ đại biểu tư vấn Đại hội V, 1924). Cuối tháng 10/1924, Người rời Mátxcơva, và ngày 11/11/1924 tới Quảng Châu, bắt đầu hoạt động ở nơi gần quê hương hơn bao giờ hết.","doc":4},{"loai":"ban_co_biet","text":"Nguyễn Ái Quốc là học viên đầu tiên đến từ Đông Dương theo học Trường Đại học Cộng sản của những người lao động phương Đông ở Mátxcơva.","nguon_ten":"Chính trị và Phát triển – Nguyễn Ái Quốc và chuyến đi đầu tiên đến nước Nga Xô viết (chinhtrivaphattrien.vn)","doc":5},{"loai":"doan","tieu_de":"Mười năm ở phương Đông","text":"Mười năm giữa hai chặng là mười năm Người trực tiếp gây dựng phong trào. Ở Quảng Châu, tháng 6/1925, Người lập Hội Việt Nam Cách mạng Thanh niên và mở các lớp huấn luyện, mà bài giảng về sau được in thành cuốn Đường Kách mệnh. Sau chính biến tháng 4/1927 ở Trung Quốc, Người trở lại Mátxcơva một thời gian ngắn, rồi sang châu Âu, và năm 1928 có mặt giữa kiều bào ở vùng Đông Bắc Xiêm.\n\nTừ ngày 6/1 đến 7/2/1930, tại Cửu Long, Hương Cảng, Người chủ trì hội nghị hợp nhất các tổ chức cộng sản, thành lập Đảng Cộng sản Việt Nam. Ngày 6/6/1931, Người bị cảnh sát Anh bắt ở Hồng Kông. Nhờ luật sư Frank Loseby và những người bạn giúp đỡ, vụ án được đưa lên tới Hội đồng Cơ mật Hoàng gia ở London, và cuối cùng Người được trả tự do. Đầu năm 1933, Người rời Hồng Kông, rồi sống bí mật ở Thượng Hải. Cũng từ Thượng Hải, mùa hè năm 1934, Người bước lên con tàu buôn đưa mình trở lại Liên Xô. Hành trang lần này là kinh nghiệm của cả một thập niên hoạt động, cùng những câu hỏi lớn về con đường của cách mạng Đông Dương.","doc":6},{"loai":"anh","src":"textures/bang_w/G08_0_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Liên Xô – Petrograd và Mátxcơva”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Chặng thứ hai: đồng chí Lin","text":"Chặng thứ hai kéo dài hơn bốn năm, từ mùa hè năm 1934 đến mùa thu năm 1938, và mang một nhịp khác hẳn. Với tên gọi Lin, Người vào học Trường Quốc tế Lê-nin, nơi đào tạo cán bộ cho các đảng cộng sản trên thế giới. Tháng 3/1935, Đại hội lần thứ nhất của Đảng Cộng sản Đông Dương họp ở Ma Cao đã cử Người làm đại diện của Đảng bên cạnh Quốc tế Cộng sản. Mùa hè năm ấy, Người dự Đại hội VII Quốc tế Cộng sản, gặp lại những đồng chí trẻ từ trong nước sang như Lê Hồng Phong, Nguyễn Thị Minh Khai.\n\nTừ đầu năm 1937, Người là nghiên cứu sinh của Viện Nghiên cứu các vấn đề dân tộc và thuộc địa. Đó cũng là những năm Liên Xô trải qua các cuộc thanh trừng chính trị nặng nề, khiến nhiều cán bộ Quốc tế Cộng sản từ các nước bị liên lụy. Có tài liệu cho rằng có lúc Người không được giao nhiệm vụ quan trọng. Người vẫn kiên nhẫn học tập, nghiên cứu, và nhiều lần đề nghị được trở về phương Đông. Tháng 10/1938, đề nghị ấy được chấp thuận. Hành trình từ đây đưa Người về tới Pác Bó ngày 28/1/1941 (xem chuyên đề Đồng chí Lin ở Mátxcơva, 1934 – 1938).","doc":7},{"loai":"ban_co_biet","text":"Tại Hội nghị Quốc tế Nông dân lần thứ nhất ở Mátxcơva tháng 10/1923, Nguyễn Ái Quốc được bầu vào Đoàn Chủ tịch gồm 11 ủy viên, một người dân thuộc địa trong cơ quan lãnh đạo của một tổ chức quốc tế.","nguon_ten":"Chính trị và Phát triển – Nguyễn Ái Quốc và chuyến đi đầu tiên đến nước Nga Xô viết; Hồ Chí Minh – Biên niên tiểu sử, tập 1","doc":8},{"loai":"doan","tieu_de":"Ngôi trường của những Tổng Bí thư","text":"Nguyễn Ái Quốc không phải người Việt Nam duy nhất học tập ở Mátxcơva. Từ Quảng Châu, chính Người đã chọn gửi nhiều thanh niên ưu tú sang Liên Xô học tập. Trường Đại học Phương Đông về sau đào tạo ba người lần lượt đứng đầu Đảng Cộng sản Đông Dương trong những năm 1930. Trần Phú học ở đây, về nước năm 1930, khởi thảo Luận cương chính trị tháng 10/1930 và trở thành Tổng Bí thư đầu tiên. Ông hy sinh trong nhà tù thực dân năm 1931, khi mới hai mươi bảy tuổi.\n\nLê Hồng Phong, người dẫn đầu đoàn đại biểu Đảng tại Đại hội VII Quốc tế Cộng sản, giữ cương vị Tổng Bí thư từ năm 1935. Hà Huy Tập, cũng từng học Trường Phương Đông, là Tổng Bí thư những năm 1936 – 1938. Cùng học với Người ở Trường Quốc tế Lê-nin còn có Nguyễn Khánh Toàn, về sau là một nhà giáo dục và nhà khoa học xã hội lớn của Việt Nam. Mátxcơva vì thế là điểm hẹn của cả một thế hệ cán bộ đầu tiên của Đảng. Nhiều người trong số họ đã ngã xuống trước ngày cách mạng thành công, nhưng những gì học được ở đây đã theo họ về tới từng cơ sở trong nước.","doc":9},{"loai":"anh","src":"textures/ht/ht_anh_participants_in_the_5th_congress_of_the_communis.jpg","chu_thich":"Các đại biểu Đại hội V Quốc tế Cộng sản tại Điện Kremli, 1924. Nguyễn Ái Quốc dự đại hội với tư cách đại biểu tư vấn.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Một trường học lớn","text":"Nếu Paris là nơi Nguyễn Ái Quốc tìm thấy con đường, thì Mátxcơva là nơi Người học cách đi trên con đường ấy. Ở chặng đầu, Người học lý luận, học cách một đảng được tổ chức, cách các phong trào công nhân và nông dân nhiều nước tập hợp lực lượng. Những hiểu biết ấy theo Người sang Quảng Châu, trở thành nội dung các lớp huấn luyện cho thanh niên Việt Nam. Ở chặng sau, Người có thời gian nhìn lại cả một thập niên thực tiễn, đọc kỹ các văn kiện của phong trào, và nghiên cứu vấn đề ruộng đất ở các nước Đông Nam Á.\n\nHai chặng cũng cho Người một hiểu biết sâu về bộ máy của Quốc tế Cộng sản, về cách các đảng ở những hoàn cảnh rất khác nhau cùng làm việc trong một tổ chức chung. Khi trở về Pác Bó, tại Hội nghị Trung ương 8 tháng 5/1941, Người chủ trì việc đặt nhiệm vụ giải phóng dân tộc lên hàng đầu, phù hợp với hoàn cảnh riêng của Việt Nam. Những năm học tập và chờ đợi ở Mátxcơva là một phần của quá trình chuẩn bị lâu dài cho quyết định ấy.","doc":10},{"loai":"doan","tieu_de":"Gian trưng bày dựng lại điều gì?","text":"Gian trưng bày chọn dựng lại Quảng trường Đỏ trong mùa đông năm 1924, khoảnh khắc xúc động nhất của chặng thứ nhất. Tường gạch đỏ của Điện Kremli với những răng cưa hình đuôi én chạy dọc một cạnh quảng trường. Sát chân tường là lăng gỗ tạm của Lênin, khối gỗ mái bậc được dựng cấp tốc cho lễ an táng ngày 27/1/1924. Phía xa là tháp Spasskaya với chiếc đồng hồ bốn mặt, cổng chính của Kremli. Ở đầu phía nam, nhà thờ Thánh Basil nổi bật với những mái vòm củ hành nhiều màu. Cạnh phía đông là dãy nhà buôn bán lớn có mái kính của cửa hàng bách hóa GUM, còn gần nhà thờ là bục đá tròn cổ Lobnoye Mesto.\n\nMỗi công trình có một bảng riêng kể lịch sử của nó. Các bảng ảnh tư liệu giới thiệu những giấy tờ gốc: tờ thị thực năm 1923, tấm thẻ đại biểu năm 1924, bài báo trên tờ Pravda ngày tang lễ Lênin, bức ảnh các đại biểu Đại hội V trong Điện Kremli. Khách tham quan có thể đi từ bảng này sang bảng khác, như lần theo từng bước chân của Người trên đất Liên Xô.","doc":11},{"loai":"anh","src":"textures/bang_w/G08_0_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Liên Xô – Petrograd và Mátxcơva”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Hơn một thế kỷ đã qua, nhiều dấu tích của hai chặng ấy vẫn còn. Ở Mátxcơva, Quảng trường Đỏ và Điện Kremli vẫn đứng đó, cùng được UNESCO ghi danh là Di sản thế giới năm 1990. Lăng gỗ tạm của Lênin đã nhường chỗ cho lăng đá hoàn thành năm 1930. Kho lưu trữ của Quốc tế Cộng sản, nay thuộc Lưu trữ Nhà nước Nga về lịch sử chính trị – xã hội, vẫn lưu giữ những hồ sơ liên quan đến hai chặng sống của Người. Ở phía tây nam thủ đô Nga có quảng trường mang tên Hồ Chí Minh, nơi đặt tượng đài Người được khánh thành năm 1990, nhân kỷ niệm một trăm năm ngày sinh.\n\nỞ Sankt-Peterburg, tên gọi hiện nay của Petrograd, năm 2023 có thêm một tượng đài Chủ tịch Hồ Chí Minh, đúng một thế kỷ sau năm con tàu Karl Liebknecht cập bến. Năm 2025, một bức tượng Người được an vị trong khuôn viên Trường Đại học Quốc gia Sankt-Peterburg. Nhiều đoàn khách Việt Nam đến Nga hôm nay vẫn tìm tới những địa chỉ ấy, như tìm lại dấu chân của người thanh niên từng đến đây giữa tuyết lạnh gần một trăm năm trước.","doc":12}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 1 và tập 2, NXB Chính trị quốc gia","Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch – Nguyễn Ái Quốc trên đất nước của Lênin (1923 – 1924): https://nhasanbacho.vn/bai-viet/nguyen-ai-quoc-tren-dat-nuoc-cua-lenin-1923-1924-222/","Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch – Nguyễn Ái Quốc trên đất nước Liên Xô (1934 – 1938): https://nhasanbacho.vn/bai-viet/nguyen-ai-quoc-tren-dat-nuoc-lien-xo-1934-1938/","Chính trị và Phát triển – Nguyễn Ái Quốc và chuyến đi đầu tiên đến nước Nga Xô viết: https://chinhtrivaphattrien.vn/nguyen-ai-quoc-va-chuyen-di-dau-tien-den-nuoc-nga-xo-viet-a7870.html","Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia","Báo Nhân Dân, VnExpress – tin khánh thành tượng đài Chủ tịch Hồ Chí Minh tại Sankt-Peterburg (2023)"],"doc":[{"t":"Hai lần cập bến xứ tuyết: Liên Xô trên hành trình tìm đường của Nguyễn Ái Quốc. Mùa hè năm 1923, một con tàu từ Hamburg cập bến Petrograd, mang theo người thợ ảnh có tên Chen Vang. Mùa hè năm 1934, một tàu buôn từ Thượng Hải cập cảng Vlađivôxtốc, chở một vị khách đặc biệt mà thuyền trưởng được dặn phải đón. Cả hai lần, người khách ấy là Nguyễn Ái Quốc. Giữa hai lần cập bến là mười một năm, và cả một chặng đường cách mạng."},{"t":"Hai lần cập bến. Ngày 30/6/1923, con tàu mang tên nhà cách mạng Đức Karl Liebknecht cập Bến số 7 cảng Gutuev, thuộc cảng Petrograd bên vịnh Phần Lan. Trong số hành khách có một thanh niên châu Á mang giấy thông hành đứng tên Chen Vang, nghề thợ ảnh. Đó là Nguyễn Ái Quốc, vừa thoát khỏi vòng theo dõi của mật thám Pháp ở Paris sau mười bảy ngày đi đường bí mật (xem chuyên đề Chuyến đi bí mật từ Paris tới Petrograd). Mười một năm sau, tháng 6/1934, ở đầu kia của đất nước Xô-viết, một tàu buôn Liên Xô từ Thượng Hải cập cảng Vlađivôxtốc bên bờ Thái Bình Dương. Thuyền trưởng đã được báo trước rằng trên tàu sẽ có một vị khách đặc biệt. Người khách ấy lại là Nguyễn Ái Quốc, lần này vừa trải qua những năm bị giam giữ ở Hồng Kông và sống bí mật ở Thượng Hải. Lần thứ nhất, Người đến từ phía tây, như một người học trò háo hức tìm tới quê hương của Cách mạng Tháng Mười. Lần thứ hai, Người đến từ phía đông, như một chiến sĩ đã dày dạn, cần một nơi để học tập, tổng kết và chờ thời cơ trở về. Gian trưng bày này kể về hai chặng sống ấy trên đất Liên Xô."},{"t":"Vì sao là nước Nga Xô-viết?. Con đường tới Mátxcơva bắt đầu từ Paris. Tháng 7/1920, Nguyễn Ái Quốc đọc bản Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của Lênin trên báo L'Humanité. Về sau, Người kể rằng chính lòng yêu nước, chứ chưa phải lý tưởng cộng sản, đã đưa Người đến với Lênin và Quốc tế thứ ba. Tháng 12/1920, tại Đại hội Tua, Người bỏ phiếu tán thành gia nhập Quốc tế Cộng sản và trở thành một trong những người tham gia sáng lập Đảng Cộng sản Pháp. Ba năm tiếp theo, Người cùng các bạn lập Hội Liên hiệp thuộc địa, làm chủ bút tờ Le Paria và viết rất nhiều bài báo tố cáo chế độ thực dân. Nhưng Paris có những giới hạn của nó. Sách báo không thay được việc học lý luận một cách có hệ thống, còn mật thám thì bám theo từng bước chân. Người muốn đến tận nơi đặt trụ sở Quốc tế Cộng sản, tận mắt xem một nhà nước mới được xây dựng ra sao. Cơ hội đến từ chính Mátxcơva. Manuinxki (Dmitry Manuilsky), Ủy viên Ban Chấp hành Quốc tế Cộng sản, đề nghị Ban Chấp hành Trung ương Đảng Cộng sản Pháp cử Nguyễn Ái Quốc sang Liên Xô. Lời mời ấy mở ra chuyến đi mùa hè năm 1923."},{"t":"Nước Nga năm 1923. Đất nước Người đặt chân tới khi ấy vừa bước ra khỏi gần bảy năm chiến tranh liên miên: Chiến tranh thế giới thứ nhất, cách mạng, rồi nội chiến và can thiệp của nước ngoài. Nạn đói những năm 1921 – 1922 ở vùng sông Vônga còn để lại vết thương sâu. Từ năm 1921, chính quyền Xô-viết thực hiện Chính sách kinh tế mới, cho phép buôn bán nhỏ và thị trường hoạt động trở lại. Mátxcơva năm 1923 vì thế mang hai gương mặt: khẩu hiệu cách mạng trên tường, bên cạnh những cửa hàng tư nhân vừa mở cửa trở lại. Liên bang Cộng hòa xã hội chủ nghĩa Xô-viết mới được thành lập từ cuối năm 1922. Mátxcơva đã là thủ đô từ năm 1918 và là nơi đặt trụ sở Quốc tế Cộng sản, tổ chức chung của các đảng cộng sản trên thế giới (xem chuyên đề Quốc tế Cộng sản). Người sáng lập nhà nước mới là Lênin thì khi ấy đã lâm bệnh nặng. Sau cơn đột quỵ tháng 3/1923, Lênin mất khả năng nói và phải điều trị ở Goócki, ngoại ô Mátxcơva. Người thanh niên Việt Nam đã vượt nửa vòng trái đất để tìm đến quê hương của học thuyết Lênin, nhưng không kịp gặp Lênin (xem chuyên đề Bài báo Lênin và các dân tộc thuộc địa)."},{"t":"Mười sáu tháng của người học trò. Chặng thứ nhất kéo dài từ cuối tháng 6/1923 đến cuối tháng 10/1924, dày đặc như một khóa học cấp tốc. Người làm việc với Quốc tế Cộng sản, và ngày 14/4/1924 được nhận làm cán bộ Ban Phương Đông, bộ phận theo dõi phong trào cách mạng ở châu Á. Cuối năm 1923, Người theo học lớp ngắn hạn của Trường Đại học Cộng sản của những người lao động phương Đông, thường gọi tắt là Trường Đại học Phương Đông. Tháng 10/1923, tại Hội nghị Quốc tế Nông dân lần thứ nhất họp ở Mátxcơva, Người phát biểu tại hai phiên họp, nói về tình cảnh của nhân dân Đông Dương. Từ Mátxcơva, Người tiếp tục gửi bài cho các báo L'Humanité, La Vie Ouvrière, Le Paria, và viết cho tạp chí Thư tín quốc tế của Quốc tế Cộng sản. Tháng 1/1924, Người có mặt trong những ngày cả nước Nga tiễn đưa Lênin (xem chuyên đề Lăng gỗ tạm của Lênin). Mùa hè năm ấy, Người dự Đại hội V Quốc tế Cộng sản với tư cách đại biểu tư vấn, kiên trì đặt vấn đề thuộc địa trước các đảng anh em (xem chuyên đề Thẻ đại biểu tư vấn Đại hội V, 1924). Cuối tháng 10/1924, Người rời Mátxcơva, và ngày 11/11/1924 tới Quảng Châu, bắt đầu hoạt động ở nơi gần quê hương hơn bao giờ hết."},{"t":"Bạn có biết? Nguyễn Ái Quốc là học viên đầu tiên đến từ Đông Dương theo học Trường Đại học Cộng sản của những người lao động phương Đông ở Mátxcơva."},{"t":"Mười năm ở phương Đông. Mười năm giữa hai chặng là mười năm Người trực tiếp gây dựng phong trào. Ở Quảng Châu, tháng 6/1925, Người lập Hội Việt Nam Cách mạng Thanh niên và mở các lớp huấn luyện, mà bài giảng về sau được in thành cuốn Đường Kách mệnh. Sau chính biến tháng 4/1927 ở Trung Quốc, Người trở lại Mátxcơva một thời gian ngắn, rồi sang châu Âu, và năm 1928 có mặt giữa kiều bào ở vùng Đông Bắc Xiêm. Từ ngày 6/1 đến 7/2/1930, tại Cửu Long, Hương Cảng, Người chủ trì hội nghị hợp nhất các tổ chức cộng sản, thành lập Đảng Cộng sản Việt Nam. Ngày 6/6/1931, Người bị cảnh sát Anh bắt ở Hồng Kông. Nhờ luật sư Frank Loseby và những người bạn giúp đỡ, vụ án được đưa lên tới Hội đồng Cơ mật Hoàng gia ở London, và cuối cùng Người được trả tự do. Đầu năm 1933, Người rời Hồng Kông, rồi sống bí mật ở Thượng Hải. Cũng từ Thượng Hải, mùa hè năm 1934, Người bước lên con tàu buôn đưa mình trở lại Liên Xô. Hành trang lần này là kinh nghiệm của cả một thập niên hoạt động, cùng những câu hỏi lớn về con đường của cách mạng Đông Dương."},{"t":"Chặng thứ hai: đồng chí Lin. Chặng thứ hai kéo dài hơn bốn năm, từ mùa hè năm 1934 đến mùa thu năm 1938, và mang một nhịp khác hẳn. Với tên gọi Lin, Người vào học Trường Quốc tế Lê-nin, nơi đào tạo cán bộ cho các đảng cộng sản trên thế giới. Tháng 3/1935, Đại hội lần thứ nhất của Đảng Cộng sản Đông Dương họp ở Ma Cao đã cử Người làm đại diện của Đảng bên cạnh Quốc tế Cộng sản. Mùa hè năm ấy, Người dự Đại hội VII Quốc tế Cộng sản, gặp lại những đồng chí trẻ từ trong nước sang như Lê Hồng Phong, Nguyễn Thị Minh Khai. Từ đầu năm 1937, Người là nghiên cứu sinh của Viện Nghiên cứu các vấn đề dân tộc và thuộc địa. Đó cũng là những năm Liên Xô trải qua các cuộc thanh trừng chính trị nặng nề, khiến nhiều cán bộ Quốc tế Cộng sản từ các nước bị liên lụy. Có tài liệu cho rằng có lúc Người không được giao nhiệm vụ quan trọng. Người vẫn kiên nhẫn học tập, nghiên cứu, và nhiều lần đề nghị được trở về phương Đông. Tháng 10/1938, đề nghị ấy được chấp thuận. Hành trình từ đây đưa Người về tới Pác Bó ngày 28/1/1941 (xem chuyên đề Đồng chí Lin ở Mátxcơva, 1934 – 1938)."},{"t":"Bạn có biết? Tại Hội nghị Quốc tế Nông dân lần thứ nhất ở Mátxcơva tháng 10/1923, Nguyễn Ái Quốc được bầu vào Đoàn Chủ tịch gồm 11 ủy viên, một người dân thuộc địa trong cơ quan lãnh đạo của một tổ chức quốc tế."},{"t":"Ngôi trường của những Tổng Bí thư. Nguyễn Ái Quốc không phải người Việt Nam duy nhất học tập ở Mátxcơva. Từ Quảng Châu, chính Người đã chọn gửi nhiều thanh niên ưu tú sang Liên Xô học tập. Trường Đại học Phương Đông về sau đào tạo ba người lần lượt đứng đầu Đảng Cộng sản Đông Dương trong những năm 1930. Trần Phú học ở đây, về nước năm 1930, khởi thảo Luận cương chính trị tháng 10/1930 và trở thành Tổng Bí thư đầu tiên. Ông hy sinh trong nhà tù thực dân năm 1931, khi mới hai mươi bảy tuổi. Lê Hồng Phong, người dẫn đầu đoàn đại biểu Đảng tại Đại hội VII Quốc tế Cộng sản, giữ cương vị Tổng Bí thư từ năm 1935. Hà Huy Tập, cũng từng học Trường Phương Đông, là Tổng Bí thư những năm 1936 – 1938. Cùng học với Người ở Trường Quốc tế Lê-nin còn có Nguyễn Khánh Toàn, về sau là một nhà giáo dục và nhà khoa học xã hội lớn của Việt Nam. Mátxcơva vì thế là điểm hẹn của cả một thế hệ cán bộ đầu tiên của Đảng. Nhiều người trong số họ đã ngã xuống trước ngày cách mạng thành công, nhưng những gì học được ở đây đã theo họ về tới từng cơ sở trong nước."},{"t":"Một trường học lớn. Nếu Paris là nơi Nguyễn Ái Quốc tìm thấy con đường, thì Mátxcơva là nơi Người học cách đi trên con đường ấy. Ở chặng đầu, Người học lý luận, học cách một đảng được tổ chức, cách các phong trào công nhân và nông dân nhiều nước tập hợp lực lượng. Những hiểu biết ấy theo Người sang Quảng Châu, trở thành nội dung các lớp huấn luyện cho thanh niên Việt Nam. Ở chặng sau, Người có thời gian nhìn lại cả một thập niên thực tiễn, đọc kỹ các văn kiện của phong trào, và nghiên cứu vấn đề ruộng đất ở các nước Đông Nam Á. Hai chặng cũng cho Người một hiểu biết sâu về bộ máy của Quốc tế Cộng sản, về cách các đảng ở những hoàn cảnh rất khác nhau cùng làm việc trong một tổ chức chung. Khi trở về Pác Bó, tại Hội nghị Trung ương 8 tháng 5/1941, Người chủ trì việc đặt nhiệm vụ giải phóng dân tộc lên hàng đầu, phù hợp với hoàn cảnh riêng của Việt Nam. Những năm học tập và chờ đợi ở Mátxcơva là một phần của quá trình chuẩn bị lâu dài cho quyết định ấy."},{"t":"Gian trưng bày dựng lại điều gì?. Gian trưng bày chọn dựng lại Quảng trường Đỏ trong mùa đông năm 1924, khoảnh khắc xúc động nhất của chặng thứ nhất. Tường gạch đỏ của Điện Kremli với những răng cưa hình đuôi én chạy dọc một cạnh quảng trường. Sát chân tường là lăng gỗ tạm của Lênin, khối gỗ mái bậc được dựng cấp tốc cho lễ an táng ngày 27/1/1924. Phía xa là tháp Spasskaya với chiếc đồng hồ bốn mặt, cổng chính của Kremli. Ở đầu phía nam, nhà thờ Thánh Basil nổi bật với những mái vòm củ hành nhiều màu. Cạnh phía đông là dãy nhà buôn bán lớn có mái kính của cửa hàng bách hóa GUM, còn gần nhà thờ là bục đá tròn cổ Lobnoye Mesto. Mỗi công trình có một bảng riêng kể lịch sử của nó. Các bảng ảnh tư liệu giới thiệu những giấy tờ gốc: tờ thị thực năm 1923, tấm thẻ đại biểu năm 1924, bài báo trên tờ Pravda ngày tang lễ Lênin, bức ảnh các đại biểu Đại hội V trong Điện Kremli. Khách tham quan có thể đi từ bảng này sang bảng khác, như lần theo từng bước chân của Người trên đất Liên Xô."},{"t":"Dấu tích hôm nay. Hơn một thế kỷ đã qua, nhiều dấu tích của hai chặng ấy vẫn còn. Ở Mátxcơva, Quảng trường Đỏ và Điện Kremli vẫn đứng đó, cùng được UNESCO ghi danh là Di sản thế giới năm 1990. Lăng gỗ tạm của Lênin đã nhường chỗ cho lăng đá hoàn thành năm 1930. Kho lưu trữ của Quốc tế Cộng sản, nay thuộc Lưu trữ Nhà nước Nga về lịch sử chính trị – xã hội, vẫn lưu giữ những hồ sơ liên quan đến hai chặng sống của Người. Ở phía tây nam thủ đô Nga có quảng trường mang tên Hồ Chí Minh, nơi đặt tượng đài Người được khánh thành năm 1990, nhân kỷ niệm một trăm năm ngày sinh. Ở Sankt-Peterburg, tên gọi hiện nay của Petrograd, năm 2023 có thêm một tượng đài Chủ tịch Hồ Chí Minh, đúng một thế kỷ sau năm con tàu Karl Liebknecht cập bến. Năm 2025, một bức tượng Người được an vị trong khuôn viên Trường Đại học Quốc gia Sankt-Peterburg. Nhiều đoàn khách Việt Nam đến Nga hôm nay vẫn tìm tới những địa chỉ ấy, như tìm lại dấu chân của người thanh niên từng đến đây giữa tuyết lạnh gần một trăm năm trước."}],"so_chu":2341},{"i":1,"tieu_de_bang":"Chuyến đi bí mật từ Paris tới Petrograd","tieu_de":"Mười bảy ngày thoát khỏi vòng vây mật thám: từ Paris tới Petrograd, mùa hè 1923","sapo":"Tối 13/6/1923, một người thanh niên châu Á mua vé xem suất chiếu phim cuối cùng ở Paris, nhưng không bao giờ xem hết bộ phim ấy. Mười bảy ngày sau, người ấy bước xuống một bến tàu ở Petrograd, trong túi là giấy thông hành mang một cái tên xa lạ. Những kẻ theo dõi Người suốt mấy năm trời phải mất một thời gian mới hiểu chuyện gì đã xảy ra.","bia":{"src":"textures/ht/ht_anh_visa_for_entry_into_russia_no_1829_on_june_16_19.jpg","credit":"Ảnh: The representative of the Union of Sovie · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Suất chiếu cuối cùng","text":"Tối 13/6/1923, Nguyễn Ái Quốc mua vé xem buổi chiếu phim cuối cùng trong ngày ở một rạp chiếu bóng tại Paris. Với những kẻ bám đuôi, việc người thanh niên thuộc địa vào rạp xem phim không có gì đáng ngờ. Nhưng Người chỉ xem đến giữa chừng. Trong bóng tối của phòng chiếu, Người lặng lẽ rời rạp bằng lối cửa sau, nhanh chóng xuống tàu điện ngầm, tới ga xe lửa phía Bắc Paris.\n\nGa phía Bắc là nơi xuất phát của những chuyến tàu đi Bỉ và nước Đức. Từ đây, Người rời nước Pháp, nơi mình đã sống và hoạt động nhiều năm. Không có buổi chia tay, không có người tiễn đưa công khai. Bạn bè chỉ biết tin qua lá thư Người để lại, nói về quyết định dấn thân của mình (xem gian trưng bày về những năm Người ở Pháp). Cuộc ra đi được chuẩn bị kỹ lưỡng đến mức những người theo dõi Người sát sao nhất cũng không kịp nhận ra. Khi họ phát hiện căn phòng nhỏ ở Paris đã vắng chủ, người thanh niên ấy đã ở rất xa.","doc":1},{"loai":"doan","tieu_de":"Một người luôn có \"cái đuôi\"","text":"Đầu những năm 1920, Nguyễn Ái Quốc là cái tên khiến Bộ Thuộc địa Pháp đặc biệt lo ngại. Tháng 6/1919, bản Yêu sách của nhân dân An Nam gửi Hội nghị Véc-xây, ký tên Nguyễn Ái Quốc, đã làm xôn xao dư luận Paris. Từ năm 1922, tờ Le Paria do Người làm chủ bút liên tục vạch trần tội ác thực dân, và được bí mật đưa về tận các thuộc địa. Người sống trong một căn phòng nhỏ ở số 9 ngõ Compoint, quận 17, và mọi ngả đường Người đi đều có mật thám ghi chép.\n\nCác báo cáo theo dõi ghi lại giờ Người ra khỏi nhà, nơi Người ngồi đọc sách, những người Người gặp. Trong hoàn cảnh ấy, một chuyến đi công khai sang nước Nga Xô-viết là điều không thể. Nước Pháp khi ấy chưa công nhận nhà nước Xô-viết; phải đến ngày 28/10/1924 hai nước mới thiết lập quan hệ ngoại giao. Một người dân thuộc địa xin đi Nga chắc chắn sẽ bị ngăn cản, và dù có đi được, Người cũng khó lòng trở lại hoạt động ở Pháp. Muốn đi, Người phải đi trong bí mật tuyệt đối, và phải làm sao để những kẻ theo dõi không kịp báo động.","doc":2},{"loai":"anh","src":"textures/bang_w/G08_1_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Chuyến đi bí mật từ Paris tới Petrograd”, nhìn từ xa."},{"loai":"doan","tieu_de":"Lời mời từ Mátxcơva","text":"Chuyến đi không phải một cuộc phiêu lưu đơn độc. Manuinxki (Dmitry Manuilsky), Ủy viên Ban Chấp hành Quốc tế Cộng sản, đã đề nghị Ban Chấp hành Trung ương Đảng Cộng sản Pháp cử Nguyễn Ái Quốc sang Mátxcơva. Tư liệu còn lưu ghi rằng Người đến nước Nga theo lời mời của Manuinxki. Với Quốc tế Cộng sản, người thanh niên Đông Dương từng viết nhiều về nông dân và các dân tộc thuộc địa là một gương mặt cần có ở Mátxcơva.\n\nMátxcơva khi ấy đang chuẩn bị cho Hội nghị Quốc tế Nông dân lần thứ nhất, dự kiến họp vào tháng 10/1923, sẽ quy tụ 158 đại biểu từ 40 nước. Ban Phương Đông của Quốc tế Cộng sản cũng cần những người am hiểu tình hình châu Á từ bên trong. Còn với Nguyễn Ái Quốc, đó là cơ hội được học tập ở trung tâm của phong trào cộng sản quốc tế, được đứng trên diễn đàn quốc tế nói về Đông Dương. Nhưng giữa Paris và Mátxcơva là cả một hệ thống kiểm soát biên giới của châu Âu thời hậu chiến. Người phải mang giấy tờ đứng tên người khác, đi vòng qua một nước thứ ba, và giữ kín lộ trình đến phút chót.","doc":3},{"loai":"doan","tieu_de":"Qua nước Đức năm 1923","text":"Nước thứ ba ấy là nước Đức. Tại Berlin, đại diện toàn quyền của nhà nước Xô-viết cấp cho Người giấy thông hành số 1829, đứng tên người thợ ảnh Chen Vang (xem chuyên đề Thị thực số 1829 mang tên Chen Vang). Nghề ghi trên giấy không phải là chuyện bịa: ở Paris, Người từng kiếm sống bằng nghề sửa ảnh. Đức là một trong số ít nước lớn châu Âu đã có quan hệ ngoại giao với nước Nga Xô-viết, theo Hiệp ước Rapallo năm 1922, nên Berlin trở thành cửa ngõ của nhiều người muốn sang Nga.\n\nNước Đức mùa hè năm 1923 đang ở giữa một cơn khủng hoảng hiếm thấy. Đồng mác mất giá từng ngày, người dân phải mang những xấp tiền dày cộp để mua vài thứ nhu yếu phẩm. Từ tháng 1/1923, quân đội Pháp và Bỉ chiếm đóng vùng công nghiệp Ruhr vì Đức chậm trả bồi thường chiến tranh. Trớ trêu thay, đúng lúc ấy, một người dân thuộc địa mà mật thám Pháp đang tìm kiếm lại lặng lẽ đi qua đất Đức, ngoài tầm với của cảnh sát Paris. Theo các mốc ngày tháng còn lại, Người ở trên đất Đức hơn mười ngày, từ khi nhận giấy ở Berlin đến lúc xuống tàu ở Hamburg.","doc":4},{"loai":"anh","src":"textures/ht/ht_anh_visa_for_entry_into_russia_no_1829_on_june_16_19.jpg","chu_thich":"Giấy thông hành nhập cảnh Nga số 1829, cấp tại Berlin ngày 16/6/1923 cho Nguyễn Ái Quốc dưới tên Chen Vang.","credit":"Ảnh: The representative of the Union of Sovie · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Con tàu mang tên Karl Liebknecht","text":"Ngày 27/6/1923, Người rời cảng Hamburg trên con tàu mang tên Karl Liebknecht. Tên con tàu gợi lại một nhân vật mà những người cộng sản châu Âu thời ấy đều biết. Karl Liebknecht là nhà cách mạng Đức, người cùng Rosa Luxemburg sáng lập Đảng Cộng sản Đức, và bị sát hại ở Berlin tháng 1/1919. Đặt tên ông cho một con tàu là cách người ta tưởng nhớ một biểu tượng của phong trào công nhân Đức.\n\nHamburg là thành phố cảng lớn nhất nước Đức, nằm trên sông Elbe. Từ đây, con tàu xuôi ra biển rồi đi vào biển Baltic, hướng về phía đông bắc tới vịnh Phần Lan. Hành trình trên biển kéo dài ba ngày. Với Nguyễn Ái Quốc, biển cả không hề xa lạ. Mười hai năm trước, Người đã rời bến Nhà Rồng trên tàu Amiral Latouche-Tréville với công việc phụ bếp, rồi đi qua nhiều đại dương và hải cảng. Nhưng lần này, người thanh niên ấy không còn đi tìm hiểu thế giới một cách chung chung. Người đi tới một địa chỉ cụ thể, với một mục tiêu rõ ràng: học tập ở trung tâm của phong trào cách mạng thế giới để trở về giải phóng quê hương.","doc":5},{"loai":"ban_co_biet","text":"Karl Liebknecht, người được đặt tên cho con tàu đưa Nguyễn Ái Quốc tới Petrograd, từng là đại biểu duy nhất của Quốc hội Đức bỏ phiếu chống ngân sách chiến tranh vào tháng 12/1914.","nguon_ten":"Bách khoa toàn thư Britannica, mục Karl Liebknecht","doc":6},{"loai":"doan","tieu_de":"Bến số 7 cảng Gutuev","text":"Ngày 30/6/1923, con tàu cập Bến số 7 của cảng Gutuev, nay thuộc quận Kirov của thành phố Sankt-Peterburg. Đó là lần đầu tiên Nguyễn Ái Quốc đặt chân lên đất nước Xô-viết. Tại cảng, Người xuất trình giấy tờ mang tên Chen Vang để làm thủ tục nhập cảnh. Người trong ảnh chụp những năm ấy là một thanh niên ba mươi ba tuổi, đã mười hai năm xa quê (xem chuyên đề Nguyễn Ái Quốc ở Liên Xô, 1923).\n\nCuối tháng Sáu là mùa đêm trắng ở Petrograd. Ở vĩ độ này, mặt trời lặn rất muộn và bầu trời gần như không tối hẳn suốt đêm. Thành phố mà Người đặt chân tới là kinh đô của đế quốc Nga suốt hai thế kỷ, nơi nổ ra Cách mạng Tháng Hai và Cách mạng Tháng Mười năm 1917. Cũng từ đây, tháng 3/1918, chính phủ Xô-viết chuyển thủ đô về Mátxcơva. Người thanh niên từng đọc Luận cương của Lênin trong căn phòng nhỏ ở Paris giờ đã đứng trên mảnh đất nơi cuộc cách mạng ấy bắt đầu.","doc":7},{"loai":"anh","src":"textures/bang_w/G08_1_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Chuyến đi bí mật từ Paris tới Petrograd”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Petrograd sau những năm bão táp","text":"Petrograd năm 1923 là một thành phố vừa đi qua những năm tháng khắc nghiệt nhất trong lịch sử của nó. Nội chiến, phong tỏa và đói kém khiến dân số thành phố sụt giảm nghiêm trọng; đến năm 1920, số người ở lại chỉ còn khoảng một phần ba so với năm 1917. Nhiều nhà máy từng phải ngừng hoạt động vì thiếu nguyên liệu và nhiên liệu. Đến năm 1923, nhờ Chính sách kinh tế mới, đời sống bắt đầu hồi phục, các cửa hàng mở lại, xưởng máy dần có việc làm.\n\nNhững công trình gắn với cách mạng vẫn còn nguyên bên bờ sông Nêva. Đó là Cung điện Mùa Đông, nơi Chính phủ lâm thời bị lật đổ trong đêm Cách mạng Tháng Mười. Đó là Điện Smônưi, nơi Đại hội Xô-viết toàn Nga lần thứ hai tuyên bố chính quyền Xô-viết ra đời. Các tài liệu không ghi lại Nguyễn Ái Quốc đã dừng lại ở Petrograd bao lâu hay đến thăm những nơi nào. Điều được ghi lại là sau đó, Người lên xe lửa đi Mátxcơva, vượt chặng đường khoảng 650 cây số về thủ đô mới của nhà nước Xô-viết.","doc":8},{"loai":"ban_co_biet","text":"Chỉ bảy tháng sau khi Nguyễn Ái Quốc đặt chân tới, ngày 26/1/1924, năm ngày sau khi Lênin qua đời, Petrograd được đổi tên thành Leningrad. Đến năm 1991, thành phố lấy lại tên gốc Sankt-Peterburg.","nguon_ten":"Bách khoa toàn thư Britannica, mục Saint Petersburg","doc":9},{"loai":"doan","tieu_de":"Những tháng đầu ở Mátxcơva","text":"Ở Mátxcơva, Người bắt đầu làm việc với Quốc tế Cộng sản, tổ chức có trụ sở ngay tại thủ đô Xô-viết. Từ tháng 9/1923, Người gửi bài cho các báo L'Humanité, La Vie Ouvrière và Le Paria ở Paris, cùng tạp chí Thư tín quốc tế của Quốc tế Cộng sản. Những bài viết ấy tiếp tục vạch trần tội ác của thực dân Pháp ở Đông Dương, nhưng giờ đây được viết từ một nơi mà mật thám Pháp không thể với tới.\n\nTháng 10/1923, Người dự Hội nghị Quốc tế Nông dân lần thứ nhất, phát biểu tại hai phiên họp và được bầu vào Đoàn Chủ tịch. Cuối năm, Người theo học lớp ngắn hạn của Trường Đại học Cộng sản của những người lao động phương Đông. Cũng những tháng ấy, báo chí Xô-viết bắt đầu tìm đến người khách lạ đến từ Đông Dương; nhà thơ Ôxíp Manđenxtam gặp Người và viết một bài báo nổi tiếng (xem chuyên đề Nguyễn Ái Quốc ở Liên Xô, 1923). Rồi mùa đông nước Nga ập đến, khắc nghiệt hơn nhiều so với những mùa đông người con xứ Nghệ từng trải qua ở London hay Paris.","doc":10},{"loai":"doan","tieu_de":"Mười bảy ngày nhìn lại","text":"Đặt các mốc cạnh nhau, ta thấy rõ một hành trình được tính toán kỹ: rời Paris tối 13/6, nhận giấy thông hành ở Berlin ngày 16/6, xuống tàu ở Hamburg ngày 27/6, cập bến Petrograd ngày 30/6/1923. Mười bảy ngày, ba quốc gia, một tên gọi mới. Hành trình ấy để lại rất ít dấu vết, bởi chính người trong cuộc đã cố ý như vậy. Những gì còn lại đến hôm nay chủ yếu là vài tờ giấy có số hiệu, ngày tháng và con dấu.\n\nNhưng mười bảy ngày ấy khép lại cả một chặng đời. Người rời châu Âu, nơi mình đã từ một người lao động làm thuê trở thành một nhà hoạt động chính trị có tiếng nói. Người bước vào hơn một năm sống, học tập và làm việc ở Liên Xô, quãng thời gian biến người thanh niên yêu nước tự học ở Paris thành một cán bộ của phong trào cộng sản quốc tế. Mãi đến năm 1946, Người mới trở lại nước Pháp một cách công khai, lần này với tư cách Chủ tịch nước Việt Nam Dân chủ Cộng hòa.","doc":11},{"loai":"anh","src":"textures/bang_w/G08_1_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Chuyến đi bí mật từ Paris tới Petrograd”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Cảng Gutuev ngày nay vẫn là một phần của cảng biển Sankt-Peterburg, nơi tàu hàng ra vào tấp nập bên vịnh Phần Lan. Thành phố đã hai lần đổi tên kể từ ngày con tàu Karl Liebknecht cập bến, nhưng những công trình Người có thể đã nhìn thấy năm 1923 vẫn còn. Đó là Cung điện Mùa Đông, nay là một phần của Bảo tàng Hermitage, và Điện Smônưi bên bờ sông Nêva. Năm 2023, tròn một thế kỷ sau chuyến tàu ấy, thành phố có thêm một tượng đài Chủ tịch Hồ Chí Minh (xem chuyên đề Liên Xô – Petrograd và Mátxcơva).\n\nỞ Paris, ngõ Compoint nơi Người từng ở đã thay đổi nhiều, nhưng dấu tích những năm Người sống ở đây vẫn được người Việt Nam tìm đến. Còn tờ giấy thông hành số 1829 đứng tên Chen Vang, được giới thiệu trong gian trưng bày này, là chứng cứ hiếm hoi có ngày tháng rõ ràng về một chuyến đi mà người trong cuộc đã giữ kín đến mức tối đa. Nhìn tờ giấy nhỏ ấy, khách tham quan có thể hình dung buổi tối tháng Sáu năm 1923, khi người thanh niên rời rạp chiếu phim bằng cửa sau, bắt đầu một chặng đường mới.","doc":12}],"nguon":["Chính trị và Phát triển – Nguyễn Ái Quốc và chuyến đi đầu tiên đến nước Nga Xô viết: https://chinhtrivaphattrien.vn/nguyen-ai-quoc-va-chuyen-di-dau-tien-den-nuoc-nga-xo-viet-a7870.html","Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch – Nguyễn Ái Quốc trên đất nước của Lênin (1923 – 1924): https://nhasanbacho.vn/bai-viet/nguyen-ai-quoc-tren-dat-nuoc-cua-lenin-1923-1924-222/","Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","Bảo tàng Hồ Chí Minh","Bách khoa toàn thư Britannica, các mục Saint Petersburg và Karl Liebknecht"],"doc":[{"t":"Mười bảy ngày thoát khỏi vòng vây mật thám: từ Paris tới Petrograd, mùa hè 1923. Tối 13/6/1923, một người thanh niên châu Á mua vé xem suất chiếu phim cuối cùng ở Paris, nhưng không bao giờ xem hết bộ phim ấy. Mười bảy ngày sau, người ấy bước xuống một bến tàu ở Petrograd, trong túi là giấy thông hành mang một cái tên xa lạ. Những kẻ theo dõi Người suốt mấy năm trời phải mất một thời gian mới hiểu chuyện gì đã xảy ra."},{"t":"Suất chiếu cuối cùng. Tối 13/6/1923, Nguyễn Ái Quốc mua vé xem buổi chiếu phim cuối cùng trong ngày ở một rạp chiếu bóng tại Paris. Với những kẻ bám đuôi, việc người thanh niên thuộc địa vào rạp xem phim không có gì đáng ngờ. Nhưng Người chỉ xem đến giữa chừng. Trong bóng tối của phòng chiếu, Người lặng lẽ rời rạp bằng lối cửa sau, nhanh chóng xuống tàu điện ngầm, tới ga xe lửa phía Bắc Paris. Ga phía Bắc là nơi xuất phát của những chuyến tàu đi Bỉ và nước Đức. Từ đây, Người rời nước Pháp, nơi mình đã sống và hoạt động nhiều năm. Không có buổi chia tay, không có người tiễn đưa công khai. Bạn bè chỉ biết tin qua lá thư Người để lại, nói về quyết định dấn thân của mình (xem gian trưng bày về những năm Người ở Pháp). Cuộc ra đi được chuẩn bị kỹ lưỡng đến mức những người theo dõi Người sát sao nhất cũng không kịp nhận ra. Khi họ phát hiện căn phòng nhỏ ở Paris đã vắng chủ, người thanh niên ấy đã ở rất xa."},{"t":"Một người luôn có \"cái đuôi\". Đầu những năm 1920, Nguyễn Ái Quốc là cái tên khiến Bộ Thuộc địa Pháp đặc biệt lo ngại. Tháng 6/1919, bản Yêu sách của nhân dân An Nam gửi Hội nghị Véc-xây, ký tên Nguyễn Ái Quốc, đã làm xôn xao dư luận Paris. Từ năm 1922, tờ Le Paria do Người làm chủ bút liên tục vạch trần tội ác thực dân, và được bí mật đưa về tận các thuộc địa. Người sống trong một căn phòng nhỏ ở số 9 ngõ Compoint, quận 17, và mọi ngả đường Người đi đều có mật thám ghi chép. Các báo cáo theo dõi ghi lại giờ Người ra khỏi nhà, nơi Người ngồi đọc sách, những người Người gặp. Trong hoàn cảnh ấy, một chuyến đi công khai sang nước Nga Xô-viết là điều không thể. Nước Pháp khi ấy chưa công nhận nhà nước Xô-viết; phải đến ngày 28/10/1924 hai nước mới thiết lập quan hệ ngoại giao. Một người dân thuộc địa xin đi Nga chắc chắn sẽ bị ngăn cản, và dù có đi được, Người cũng khó lòng trở lại hoạt động ở Pháp. Muốn đi, Người phải đi trong bí mật tuyệt đối, và phải làm sao để những kẻ theo dõi không kịp báo động."},{"t":"Lời mời từ Mátxcơva. Chuyến đi không phải một cuộc phiêu lưu đơn độc. Manuinxki (Dmitry Manuilsky), Ủy viên Ban Chấp hành Quốc tế Cộng sản, đã đề nghị Ban Chấp hành Trung ương Đảng Cộng sản Pháp cử Nguyễn Ái Quốc sang Mátxcơva. Tư liệu còn lưu ghi rằng Người đến nước Nga theo lời mời của Manuinxki. Với Quốc tế Cộng sản, người thanh niên Đông Dương từng viết nhiều về nông dân và các dân tộc thuộc địa là một gương mặt cần có ở Mátxcơva. Mátxcơva khi ấy đang chuẩn bị cho Hội nghị Quốc tế Nông dân lần thứ nhất, dự kiến họp vào tháng 10/1923, sẽ quy tụ 158 đại biểu từ 40 nước. Ban Phương Đông của Quốc tế Cộng sản cũng cần những người am hiểu tình hình châu Á từ bên trong. Còn với Nguyễn Ái Quốc, đó là cơ hội được học tập ở trung tâm của phong trào cộng sản quốc tế, được đứng trên diễn đàn quốc tế nói về Đông Dương. Nhưng giữa Paris và Mátxcơva là cả một hệ thống kiểm soát biên giới của châu Âu thời hậu chiến. Người phải mang giấy tờ đứng tên người khác, đi vòng qua một nước thứ ba, và giữ kín lộ trình đến phút chót."},{"t":"Qua nước Đức năm 1923. Nước thứ ba ấy là nước Đức. Tại Berlin, đại diện toàn quyền của nhà nước Xô-viết cấp cho Người giấy thông hành số 1829, đứng tên người thợ ảnh Chen Vang (xem chuyên đề Thị thực số 1829 mang tên Chen Vang). Nghề ghi trên giấy không phải là chuyện bịa: ở Paris, Người từng kiếm sống bằng nghề sửa ảnh. Đức là một trong số ít nước lớn châu Âu đã có quan hệ ngoại giao với nước Nga Xô-viết, theo Hiệp ước Rapallo năm 1922, nên Berlin trở thành cửa ngõ của nhiều người muốn sang Nga. Nước Đức mùa hè năm 1923 đang ở giữa một cơn khủng hoảng hiếm thấy. Đồng mác mất giá từng ngày, người dân phải mang những xấp tiền dày cộp để mua vài thứ nhu yếu phẩm. Từ tháng 1/1923, quân đội Pháp và Bỉ chiếm đóng vùng công nghiệp Ruhr vì Đức chậm trả bồi thường chiến tranh. Trớ trêu thay, đúng lúc ấy, một người dân thuộc địa mà mật thám Pháp đang tìm kiếm lại lặng lẽ đi qua đất Đức, ngoài tầm với của cảnh sát Paris. Theo các mốc ngày tháng còn lại, Người ở trên đất Đức hơn mười ngày, từ khi nhận giấy ở Berlin đến lúc xuống tàu ở Hamburg."},{"t":"Con tàu mang tên Karl Liebknecht. Ngày 27/6/1923, Người rời cảng Hamburg trên con tàu mang tên Karl Liebknecht. Tên con tàu gợi lại một nhân vật mà những người cộng sản châu Âu thời ấy đều biết. Karl Liebknecht là nhà cách mạng Đức, người cùng Rosa Luxemburg sáng lập Đảng Cộng sản Đức, và bị sát hại ở Berlin tháng 1/1919. Đặt tên ông cho một con tàu là cách người ta tưởng nhớ một biểu tượng của phong trào công nhân Đức. Hamburg là thành phố cảng lớn nhất nước Đức, nằm trên sông Elbe. Từ đây, con tàu xuôi ra biển rồi đi vào biển Baltic, hướng về phía đông bắc tới vịnh Phần Lan. Hành trình trên biển kéo dài ba ngày. Với Nguyễn Ái Quốc, biển cả không hề xa lạ. Mười hai năm trước, Người đã rời bến Nhà Rồng trên tàu Amiral Latouche-Tréville với công việc phụ bếp, rồi đi qua nhiều đại dương và hải cảng. Nhưng lần này, người thanh niên ấy không còn đi tìm hiểu thế giới một cách chung chung. Người đi tới một địa chỉ cụ thể, với một mục tiêu rõ ràng: học tập ở trung tâm của phong trào cách mạng thế giới để trở về giải phóng quê hương."},{"t":"Bạn có biết? Karl Liebknecht, người được đặt tên cho con tàu đưa Nguyễn Ái Quốc tới Petrograd, từng là đại biểu duy nhất của Quốc hội Đức bỏ phiếu chống ngân sách chiến tranh vào tháng 12/1914."},{"t":"Bến số 7 cảng Gutuev. Ngày 30/6/1923, con tàu cập Bến số 7 của cảng Gutuev, nay thuộc quận Kirov của thành phố Sankt-Peterburg. Đó là lần đầu tiên Nguyễn Ái Quốc đặt chân lên đất nước Xô-viết. Tại cảng, Người xuất trình giấy tờ mang tên Chen Vang để làm thủ tục nhập cảnh. Người trong ảnh chụp những năm ấy là một thanh niên ba mươi ba tuổi, đã mười hai năm xa quê (xem chuyên đề Nguyễn Ái Quốc ở Liên Xô, 1923). Cuối tháng Sáu là mùa đêm trắng ở Petrograd. Ở vĩ độ này, mặt trời lặn rất muộn và bầu trời gần như không tối hẳn suốt đêm. Thành phố mà Người đặt chân tới là kinh đô của đế quốc Nga suốt hai thế kỷ, nơi nổ ra Cách mạng Tháng Hai và Cách mạng Tháng Mười năm 1917. Cũng từ đây, tháng 3/1918, chính phủ Xô-viết chuyển thủ đô về Mátxcơva. Người thanh niên từng đọc Luận cương của Lênin trong căn phòng nhỏ ở Paris giờ đã đứng trên mảnh đất nơi cuộc cách mạng ấy bắt đầu."},{"t":"Petrograd sau những năm bão táp. Petrograd năm 1923 là một thành phố vừa đi qua những năm tháng khắc nghiệt nhất trong lịch sử của nó. Nội chiến, phong tỏa và đói kém khiến dân số thành phố sụt giảm nghiêm trọng; đến năm 1920, số người ở lại chỉ còn khoảng một phần ba so với năm 1917. Nhiều nhà máy từng phải ngừng hoạt động vì thiếu nguyên liệu và nhiên liệu. Đến năm 1923, nhờ Chính sách kinh tế mới, đời sống bắt đầu hồi phục, các cửa hàng mở lại, xưởng máy dần có việc làm. Những công trình gắn với cách mạng vẫn còn nguyên bên bờ sông Nêva. Đó là Cung điện Mùa Đông, nơi Chính phủ lâm thời bị lật đổ trong đêm Cách mạng Tháng Mười. Đó là Điện Smônưi, nơi Đại hội Xô-viết toàn Nga lần thứ hai tuyên bố chính quyền Xô-viết ra đời. Các tài liệu không ghi lại Nguyễn Ái Quốc đã dừng lại ở Petrograd bao lâu hay đến thăm những nơi nào. Điều được ghi lại là sau đó, Người lên xe lửa đi Mátxcơva, vượt chặng đường khoảng 650 cây số về thủ đô mới của nhà nước Xô-viết."},{"t":"Bạn có biết? Chỉ bảy tháng sau khi Nguyễn Ái Quốc đặt chân tới, ngày 26/1/1924, năm ngày sau khi Lênin qua đời, Petrograd được đổi tên thành Leningrad. Đến năm 1991, thành phố lấy lại tên gốc Sankt-Peterburg."},{"t":"Những tháng đầu ở Mátxcơva. Ở Mátxcơva, Người bắt đầu làm việc với Quốc tế Cộng sản, tổ chức có trụ sở ngay tại thủ đô Xô-viết. Từ tháng 9/1923, Người gửi bài cho các báo L'Humanité, La Vie Ouvrière và Le Paria ở Paris, cùng tạp chí Thư tín quốc tế của Quốc tế Cộng sản. Những bài viết ấy tiếp tục vạch trần tội ác của thực dân Pháp ở Đông Dương, nhưng giờ đây được viết từ một nơi mà mật thám Pháp không thể với tới. Tháng 10/1923, Người dự Hội nghị Quốc tế Nông dân lần thứ nhất, phát biểu tại hai phiên họp và được bầu vào Đoàn Chủ tịch. Cuối năm, Người theo học lớp ngắn hạn của Trường Đại học Cộng sản của những người lao động phương Đông. Cũng những tháng ấy, báo chí Xô-viết bắt đầu tìm đến người khách lạ đến từ Đông Dương; nhà thơ Ôxíp Manđenxtam gặp Người và viết một bài báo nổi tiếng (xem chuyên đề Nguyễn Ái Quốc ở Liên Xô, 1923). Rồi mùa đông nước Nga ập đến, khắc nghiệt hơn nhiều so với những mùa đông người con xứ Nghệ từng trải qua ở London hay Paris."},{"t":"Mười bảy ngày nhìn lại. Đặt các mốc cạnh nhau, ta thấy rõ một hành trình được tính toán kỹ: rời Paris tối 13/6, nhận giấy thông hành ở Berlin ngày 16/6, xuống tàu ở Hamburg ngày 27/6, cập bến Petrograd ngày 30/6/1923. Mười bảy ngày, ba quốc gia, một tên gọi mới. Hành trình ấy để lại rất ít dấu vết, bởi chính người trong cuộc đã cố ý như vậy. Những gì còn lại đến hôm nay chủ yếu là vài tờ giấy có số hiệu, ngày tháng và con dấu. Nhưng mười bảy ngày ấy khép lại cả một chặng đời. Người rời châu Âu, nơi mình đã từ một người lao động làm thuê trở thành một nhà hoạt động chính trị có tiếng nói. Người bước vào hơn một năm sống, học tập và làm việc ở Liên Xô, quãng thời gian biến người thanh niên yêu nước tự học ở Paris thành một cán bộ của phong trào cộng sản quốc tế. Mãi đến năm 1946, Người mới trở lại nước Pháp một cách công khai, lần này với tư cách Chủ tịch nước Việt Nam Dân chủ Cộng hòa."},{"t":"Dấu tích hôm nay. Cảng Gutuev ngày nay vẫn là một phần của cảng biển Sankt-Peterburg, nơi tàu hàng ra vào tấp nập bên vịnh Phần Lan. Thành phố đã hai lần đổi tên kể từ ngày con tàu Karl Liebknecht cập bến, nhưng những công trình Người có thể đã nhìn thấy năm 1923 vẫn còn. Đó là Cung điện Mùa Đông, nay là một phần của Bảo tàng Hermitage, và Điện Smônưi bên bờ sông Nêva. Năm 2023, tròn một thế kỷ sau chuyến tàu ấy, thành phố có thêm một tượng đài Chủ tịch Hồ Chí Minh (xem chuyên đề Liên Xô – Petrograd và Mátxcơva). Ở Paris, ngõ Compoint nơi Người từng ở đã thay đổi nhiều, nhưng dấu tích những năm Người sống ở đây vẫn được người Việt Nam tìm đến. Còn tờ giấy thông hành số 1829 đứng tên Chen Vang, được giới thiệu trong gian trưng bày này, là chứng cứ hiếm hoi có ngày tháng rõ ràng về một chuyến đi mà người trong cuộc đã giữ kín đến mức tối đa. Nhìn tờ giấy nhỏ ấy, khách tham quan có thể hình dung buổi tối tháng Sáu năm 1923, khi người thanh niên rời rạp chiếu phim bằng cửa sau, bắt đầu một chặng đường mới."}],"so_chu":2175},{"i":2,"tieu_de_bang":"Đồng chí Lin ở Mátxcơva, 1934 – 1938","tieu_de":"Học viên số 375, nghiên cứu sinh số 19: bốn năm của đồng chí Lin ở Mátxcơva (1934 – 1938)","sapo":"Trong hồ sơ của Trường Quốc tế Lê-nin, người ấy là học viên số hiệu 375, tên Lin. Trong quyết định cho về nước năm 1938, người ấy là sinh viên số hiệu 19. Đằng sau những con số khô khan là bốn năm lặng lẽ học tập, giảng dạy, nghiên cứu và chờ đợi của Nguyễn Ái Quốc, giữa một Mátxcơva đầy biến động.","bia":{"src":"textures/bai/G08_v6.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Vị khách đặc biệt trên tàu buôn","text":"Mùa hè năm 1934, thuyền trưởng một tàu buôn Liên Xô ở Thượng Hải nhận được thông báo phải đón lên tàu một vị khách đặc biệt. Vị khách ấy là Nguyễn Ái Quốc. Tháng 6/1934, con tàu đưa Người tới cảng Vlađivôxtốc, rồi từ đó Người vượt hàng nghìn cây số về Mátxcơva. Chuyến đi khép lại ba năm đầy sóng gió.\n\nNgày 6/6/1931, Người bị cảnh sát Anh bắt ở Hồng Kông. Nhờ luật sư Frank Loseby và những người bạn giúp đỡ, vụ án được đưa lên tới Hội đồng Cơ mật Hoàng gia ở London; cuối cùng Người được trả tự do và đầu năm 1933 rời Hồng Kông. Ở Thượng Hải, Người sống bí mật, tìm cách nối lại liên lạc với Quốc tế Cộng sản. Nhà báo cộng sản Pháp Paul Vaillant-Couturier, người bạn cũ từ những năm ở Paris, đã giúp Người trên con đường trở lại Liên Xô. Lúc này Nguyễn Ái Quốc đã là một nhà cách mạng dày dạn. Người đã sáng lập Hội Việt Nam Cách mạng Thanh niên, đã chủ trì hợp nhất các tổ chức cộng sản thành Đảng Cộng sản Việt Nam đầu năm 1930. Vậy mà ở Mátxcơva, Người lại chọn ngồi vào ghế học trò.","doc":1},{"loai":"doan","tieu_de":"Tòa biệt thự trên phố Vôrốpxki","text":"Ngày 2/10/1934, theo Quyết định số 45, Người chính thức được nhận vào Trường Quốc tế Lê-nin. Trong hồ sơ, Người mang tên Lin, lúc đầu ghi là Linốp, học viên số hiệu 375 của khóa 1934 – 1935. Trường đặt trong một tòa biệt thự cũ của quý tộc Nga xây từ thế kỷ XIX, trên phố Vôrốpxki ở trung tâm Mátxcơva. Đây là nơi Quốc tế Cộng sản đào tạo cán bộ cho các đảng cộng sản trên thế giới; học viên đều mang bí danh và giữ kín tên thật.\n\nChương trình học rất nặng: lý luận Mác – Lênin, vấn đề dân tộc và thuộc địa, xây dựng đảng cộng sản, công tác mặt trận, phương pháp hoạt động bí mật. Học viên học theo các nhóm ngôn ngữ. Thời gian đầu, Lin sinh hoạt trong nhóm tiếng Trung Quốc, sau đó chuyển sang nhóm tiếng Pháp. Ở tuổi bốn mươi tư, sau hơn hai mươi năm bôn ba khắp các châu lục, Người lại ngồi vào bàn học cùng nhiều học viên trẻ hơn mình, nghe giảng, ghi chép, làm bài và dự thi. Với Người, đây là dịp hiếm hoi để hệ thống hóa những gì đã trải qua trong thực tiễn.","doc":2},{"loai":"anh","src":"textures/bang_w/G08_2_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Đồng chí Lin ở Mátxcơva, 1934 – 1938”, nhìn từ xa."},{"loai":"doan","tieu_de":"Những buổi tối với anh em Việt Nam","text":"Dù học ở nhóm tiếng Pháp, Người vẫn giữ liên hệ chặt chẽ với nhóm học viên Việt Nam trong trường. Một trong những người cùng học thời ấy là Nguyễn Khánh Toàn, bí danh Minin, về sau là nhà giáo dục và nhà khoa học xã hội hàng đầu của Việt Nam. Theo lời ông kể lại, buổi tối Người thường đến nói chuyện với anh em về kinh nghiệm đấu tranh. Người hỏi han việc học tập, sinh hoạt của từng người một cách nhẹ nhàng, tự nhiên, không định giờ để kiểm soát, nên không khí chẳng hề gò bó.\n\nNgười cũng lo cho những cán bộ ở xa. Tháng 1/1935, Người gửi thư cho Ban Phương Đông của Quốc tế Cộng sản, nêu tình trạng thiếu hiểu biết lý luận của cán bộ cách mạng ở Đông Dương, Trung Quốc, Xiêm và Inđônêxia. Người đề nghị tạo điều kiện để các đồng chí ấy tiếp thu được những kiến thức sơ đẳng nhất mà mỗi chiến sĩ đều phải có. Kèm theo thư là danh mục 30 tài liệu cần dịch và phổ biến, trong đó có Tuyên ngôn của Đảng Cộng sản, lịch sử Quốc tế Cộng sản và luận cương về vấn đề thuộc địa. Người học, nhưng luôn nghĩ tới việc đem cái học về cho phong trào.","doc":3},{"loai":"doan","tieu_de":"Người đại diện của Đảng","text":"Trong khi Người ngồi trên ghế nhà trường, Đảng Cộng sản Đông Dương trong nước đang dần hồi phục sau những đợt khủng bố trắng đầu thập niên. Tháng 3/1935, Đại hội đại biểu lần thứ nhất của Đảng họp ở Ma Cao. Đại hội cử Nguyễn Ái Quốc làm đại diện của Đảng bên cạnh Quốc tế Cộng sản. Từ đây, người học viên tên Lin đồng thời là tiếng nói chính thức của Đảng ở Mátxcơva.\n\nTrước đó, từ cuối năm 1934, một đoàn đại biểu của Đảng đã có mặt ở Mátxcơva để chuẩn bị dự Đại hội VII Quốc tế Cộng sản. Đoàn do Lê Hồng Phong dẫn đầu, cùng Hoàng Văn Nọn và Nguyễn Thị Minh Khai. Lê Hồng Phong từng là học trò của Người ở Quảng Châu giữa những năm 1920. Nguyễn Thị Minh Khai từng giúp việc Người ở Hồng Kông những năm 1930 – 1931, trước khi cả hai lần lượt bị bắt. Cuộc gặp lại ở Mátxcơva diễn ra sau bao năm mỗi người một ngả, người bị tù đày, người hoạt động bí mật. Với những cán bộ trẻ ấy, được làm việc bên cạnh người sáng lập Đảng là một dịp học hỏi quý giá.","doc":4},{"loai":"anh","src":"textures/bai/G08_v6.jpg","chu_thich":"Không gian 3D tái hiện Quảng trường Đỏ, Mátxcơva, trong gian trưng bày về những năm Nguyễn Ái Quốc ở Liên Xô.","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Mùa hè Đại hội VII","text":"Từ ngày 25/7 đến 20/8/1935, Đại hội lần thứ VII Quốc tế Cộng sản họp tại Mátxcơva, với 513 đại biểu của 65 đảng, trong đó 371 đại biểu có quyền biểu quyết. Nguyễn Ái Quốc dự đại hội với tư cách đại biểu tư vấn của Ban Phương Đông, thẻ đại biểu số 154. Trường Quốc tế Lê-nin cho Người nghỉ học một tháng để dịch và in các văn kiện đại hội ra tiếng Việt, để đưa về trong nước.\n\nĐoàn Đảng Cộng sản Đông Dương có ba bản tham luận. Ngày 28/7/1935, Lê Hồng Phong, bí danh Hải An, trình bày về phong trào cách mạng Đông Dương những năm 1930 – 1935. Ngày 11/8, tại phiên họp thứ 31, Hoàng Văn Nọn, bí danh Văn Tân, nói về đồng bào các dân tộc thiểu số và mặt trận nhân dân. Ngày 16/8, tại phiên họp thứ 40, Nguyễn Thị Minh Khai, bí danh Phan Lan, nói về vai trò của phụ nữ và cuộc đấu tranh chống chiến tranh. Đại hội đề ra chủ trương lập mặt trận nhân dân rộng rãi chống chủ nghĩa phát xít và nguy cơ chiến tranh. Đường lối ấy ảnh hưởng lớn tới cách mạng Đông Dương trong thời kỳ Mặt trận Dân chủ 1936 – 1939.","doc":5},{"loai":"ban_co_biet","text":"Đại hội VII năm 1935 là đại hội cuối cùng của Quốc tế Cộng sản. Tám năm sau, năm 1943, giữa Chiến tranh thế giới thứ hai, tổ chức này tuyên bố tự giải tán.","nguon_ten":"Bách khoa toàn thư Britannica, mục Comintern","doc":6},{"loai":"doan","tieu_de":"Người thầy của những học viên trẻ","text":"Sau Đại hội VII, Người tiếp tục học ở Trường Quốc tế Lê-nin, đồng thời phụ giảng cho nhóm học viên Việt Nam ở Trường Đại học Phương Đông, dạy lịch sử Đảng và nguyên lý tổ chức đảng. Người còn giúp bà Vera Vaxiliêva, trưởng phòng Đông Dương của Ban Phương Đông, trong công việc của bộ phận này, và giúp các thành viên đoàn đại biểu lần lượt tìm đường trở về Tổ quốc.\n\nTư liệu của Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch cho biết, trong thời gian này có một bức thư ngỏ bằng chữ quốc ngữ gửi Mặt trận Bình dân Pháp. Bức thư đòi thực thi sáu điều về quyền tự do dân chủ, và quyền được tồn tại công khai cho Đảng Cộng sản Đông Dương. Thư không đề tên người viết, nhưng hồ sơ của mật thám Pháp xác định đó là do Nguyễn Ái Quốc soạn thảo. Năm 1936, khi Mặt trận Bình dân lên cầm quyền ở Pháp, phong trào đòi dân sinh, dân chủ ở Đông Dương bùng lên mạnh mẽ. Người ở xa, nhưng tiếng nói của Người vẫn tìm được đường về với phong trào trong nước.","doc":7},{"loai":"anh","src":"textures/bang_w/G08_2_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Đồng chí Lin ở Mátxcơva, 1934 – 1938”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Nghiên cứu sinh số hiệu 19","text":"Cuối năm 1936, Người chuyển sang Viện Nghiên cứu các vấn đề dân tộc và thuộc địa, vừa là nghiên cứu sinh, vừa là giáo viên của phòng Đông Dương. Theo tư liệu lưu trữ, Người ở phòng 417, nhà 6A phố Bônsaia Brônnaia. Tháng 1/1937, Viện mở lớp nghiên cứu sinh nhằm đào tạo giảng viên trình độ cao cho các ngành kinh tế và lịch sử; Người là một trong 21 người được tuyển chọn. Kế hoạch cá nhân của nghiên cứu sinh Lin, từ ngày 1/1 đến 31/12/1937, gồm ngôn ngữ, lịch sử và triết học.\n\nNgười học rất chuyên cần: mùa hè năm 1937, Người là một trong hai nghiên cứu sinh không đi nghỉ hè. Đề tài luận án do Người tự chọn là Cách mạng ruộng đất ở Đông Nam Á. Vấn đề ruộng đất vốn là điều Người trăn trở từ những năm viết báo ở Paris và phát biểu tại Hội nghị Quốc tế Nông dân năm 1923. Ở Đông Dương, tuyệt đại đa số dân cư là nông dân, và câu hỏi làm sao cho người cày có ruộng gắn liền với con đường giải phóng dân tộc. Những năm ở Viện cho Người điều kiện đặt câu hỏi ấy trong bối cảnh rộng hơn của cả khu vực.","doc":8},{"loai":"ban_co_biet","text":"Trong kỳ thi học kỳ I năm học 1937 – 1938, nghiên cứu sinh Lin đạt điểm trung bình ở môn duy vật biện chứng và môn lịch sử cổ đại, trung đại, nhưng đạt điểm xuất sắc ở môn lịch sử hiện đại.","nguon_ten":"Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch – Nguyễn Ái Quốc trên đất nước Liên Xô (1934 – 1938)","doc":9},{"loai":"doan","tieu_de":"Những năm tháng thử thách","text":"Những năm Người ở Mátxcơva lần thứ hai trùng với thời kỳ Liên Xô trải qua các cuộc thanh trừng chính trị nặng nề. Nhiều cán bộ Quốc tế Cộng sản đến từ các nước bị bắt, bị kết án. Trường Đại học Phương Đông, nơi Người từng học năm 1923 và phụ giảng từ năm 1935, bị giải thể trong những năm 1937 – 1938; nhiều giảng viên và cựu học viên của trường trở thành nạn nhân của giai đoạn này.\n\nĐầu năm 1936, một cuộc thẩm tra được tiến hành về việc Nguyễn Ái Quốc ra khỏi nhà tù Hồng Kông. Kết luận là không có vấn đề gì, và hồ sơ thẩm tra được hủy bỏ. Các nhà nghiên cứu vẫn có những nhận định khác nhau về vị trí của Người trong mấy năm này. Có tài liệu cho rằng có lúc Người không được giao nhiệm vụ quan trọng, cũng có nghiên cứu cho rằng Người vẫn là thành viên được tin cậy của Quốc tế Cộng sản. Điều chắc chắn là Người giữ được sự điềm tĩnh, tiếp tục học tập, giảng dạy, nghiên cứu, và không ngừng đề nghị được trở về gần Tổ quốc.","doc":10},{"loai":"doan","tieu_de":"Lá thư tháng Sáu năm 1938","text":"Tháng 6/1938, đúng dịp tròn bảy năm ngày bị bắt ở Hồng Kông, Người viết một lá thư bằng tiếng Pháp gửi Quốc tế Cộng sản. Người nhắc rằng mình đã bước sang năm thứ tám không được trực tiếp hoạt động. Người đề nghị đừng để mình sống quá lâu trong tình trạng không hoạt động, giống như sống ở bên cạnh, ở bên ngoài Đảng. Ngày 8/6/1938, Phòng tổ chức cán bộ chuyển báo cáo về trường hợp của Người tới Tổng Bí thư Quốc tế Cộng sản Đimitơrốp.\n\nLá thư có kết quả. Ngày 19/8/1938, công văn số 4/797 của Quốc tế Cộng sản đề nghị giải quyết cho đồng chí Lin, người Đông Dương, tức Nguyễn Ái Quốc – Tống Văn Sơ, đến Trung Quốc qua Urumsi, thủ phủ Tân Cương. Kèm theo công văn là bản tóm tắt tiểu sử của Người. Tống Văn Sơ là tên Người mang trong vụ án ở Hồng Kông năm 1931. Sau hơn bốn năm lặng lẽ, cánh cửa về phương Đông cuối cùng đã mở ra.","doc":11},{"loai":"anh","src":"textures/bang_w/G08_2_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Đồng chí Lin ở Mátxcơva, 1934 – 1938”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Ga Iarôxláp, mùa thu 1938","text":"Ngày 30/9/1938, Phòng cán bộ của Viện Nghiên cứu các vấn đề dân tộc và thuộc địa ra Quyết định mật số 60. Quyết định ghi rằng sinh viên số hiệu 19, tên Lin, từ ngày 29/9/1938 đã rời khỏi biên chế của Viện để về nước. Tháng 10/1938, Người lên tàu ở ga Iarôxláp, nhà ga của Mátxcơva nơi xuất phát những chuyến tàu xuyên Xibia về phía đông.\n\nTừ đây, Người sang Trung Quốc, tới Diên An, rồi trong vai một chiến sĩ Bát lộ quân mang tên Hồ Quang, tìm đường xuống phía nam, ngày càng gần biên giới Việt – Trung. Ngày 28/1/1941, Người vượt cột mốc 108 về Pác Bó, sau ba mươi năm xa Tổ quốc. Những năm lặng lẽ ở Mátxcơva là quãng tích lũy cuối cùng trước khi Người trực tiếp lãnh đạo cách mạng trong nước. Ngày nay, phần lớn những gì ta biết về bốn năm ấy đến từ hồ sơ của Quốc tế Cộng sản còn lưu ở Mátxcơva, nay thuộc Lưu trữ Nhà nước Nga về lịch sử chính trị – xã hội, được các nhà nghiên cứu khai thác trong nhiều năm qua.","doc":12}],"nguon":["Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch – Nguyễn Ái Quốc trên đất nước Liên Xô (1934 – 1938): https://nhasanbacho.vn/bai-viet/nguyen-ai-quoc-tren-dat-nuoc-lien-xo-1934-1938/","Hồ Chí Minh – Biên niên tiểu sử, tập 2, NXB Chính trị quốc gia","Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia","Bảo tàng Hồ Chí Minh","Bách khoa toàn thư Britannica, mục Comintern"],"doc":[{"t":"Học viên số 375, nghiên cứu sinh số 19: bốn năm của đồng chí Lin ở Mátxcơva (1934 – 1938). Trong hồ sơ của Trường Quốc tế Lê-nin, người ấy là học viên số hiệu 375, tên Lin. Trong quyết định cho về nước năm 1938, người ấy là sinh viên số hiệu 19. Đằng sau những con số khô khan là bốn năm lặng lẽ học tập, giảng dạy, nghiên cứu và chờ đợi của Nguyễn Ái Quốc, giữa một Mátxcơva đầy biến động."},{"t":"Vị khách đặc biệt trên tàu buôn. Mùa hè năm 1934, thuyền trưởng một tàu buôn Liên Xô ở Thượng Hải nhận được thông báo phải đón lên tàu một vị khách đặc biệt. Vị khách ấy là Nguyễn Ái Quốc. Tháng 6/1934, con tàu đưa Người tới cảng Vlađivôxtốc, rồi từ đó Người vượt hàng nghìn cây số về Mátxcơva. Chuyến đi khép lại ba năm đầy sóng gió. Ngày 6/6/1931, Người bị cảnh sát Anh bắt ở Hồng Kông. Nhờ luật sư Frank Loseby và những người bạn giúp đỡ, vụ án được đưa lên tới Hội đồng Cơ mật Hoàng gia ở London; cuối cùng Người được trả tự do và đầu năm 1933 rời Hồng Kông. Ở Thượng Hải, Người sống bí mật, tìm cách nối lại liên lạc với Quốc tế Cộng sản. Nhà báo cộng sản Pháp Paul Vaillant-Couturier, người bạn cũ từ những năm ở Paris, đã giúp Người trên con đường trở lại Liên Xô. Lúc này Nguyễn Ái Quốc đã là một nhà cách mạng dày dạn. Người đã sáng lập Hội Việt Nam Cách mạng Thanh niên, đã chủ trì hợp nhất các tổ chức cộng sản thành Đảng Cộng sản Việt Nam đầu năm 1930. Vậy mà ở Mátxcơva, Người lại chọn ngồi vào ghế học trò."},{"t":"Tòa biệt thự trên phố Vôrốpxki. Ngày 2/10/1934, theo Quyết định số 45, Người chính thức được nhận vào Trường Quốc tế Lê-nin. Trong hồ sơ, Người mang tên Lin, lúc đầu ghi là Linốp, học viên số hiệu 375 của khóa 1934 – 1935. Trường đặt trong một tòa biệt thự cũ của quý tộc Nga xây từ thế kỷ XIX, trên phố Vôrốpxki ở trung tâm Mátxcơva. Đây là nơi Quốc tế Cộng sản đào tạo cán bộ cho các đảng cộng sản trên thế giới; học viên đều mang bí danh và giữ kín tên thật. Chương trình học rất nặng: lý luận Mác – Lênin, vấn đề dân tộc và thuộc địa, xây dựng đảng cộng sản, công tác mặt trận, phương pháp hoạt động bí mật. Học viên học theo các nhóm ngôn ngữ. Thời gian đầu, Lin sinh hoạt trong nhóm tiếng Trung Quốc, sau đó chuyển sang nhóm tiếng Pháp. Ở tuổi bốn mươi tư, sau hơn hai mươi năm bôn ba khắp các châu lục, Người lại ngồi vào bàn học cùng nhiều học viên trẻ hơn mình, nghe giảng, ghi chép, làm bài và dự thi. Với Người, đây là dịp hiếm hoi để hệ thống hóa những gì đã trải qua trong thực tiễn."},{"t":"Những buổi tối với anh em Việt Nam. Dù học ở nhóm tiếng Pháp, Người vẫn giữ liên hệ chặt chẽ với nhóm học viên Việt Nam trong trường. Một trong những người cùng học thời ấy là Nguyễn Khánh Toàn, bí danh Minin, về sau là nhà giáo dục và nhà khoa học xã hội hàng đầu của Việt Nam. Theo lời ông kể lại, buổi tối Người thường đến nói chuyện với anh em về kinh nghiệm đấu tranh. Người hỏi han việc học tập, sinh hoạt của từng người một cách nhẹ nhàng, tự nhiên, không định giờ để kiểm soát, nên không khí chẳng hề gò bó. Người cũng lo cho những cán bộ ở xa. Tháng 1/1935, Người gửi thư cho Ban Phương Đông của Quốc tế Cộng sản, nêu tình trạng thiếu hiểu biết lý luận của cán bộ cách mạng ở Đông Dương, Trung Quốc, Xiêm và Inđônêxia. Người đề nghị tạo điều kiện để các đồng chí ấy tiếp thu được những kiến thức sơ đẳng nhất mà mỗi chiến sĩ đều phải có. Kèm theo thư là danh mục 30 tài liệu cần dịch và phổ biến, trong đó có Tuyên ngôn của Đảng Cộng sản, lịch sử Quốc tế Cộng sản và luận cương về vấn đề thuộc địa. Người học, nhưng luôn nghĩ tới việc đem cái học về cho phong trào."},{"t":"Người đại diện của Đảng. Trong khi Người ngồi trên ghế nhà trường, Đảng Cộng sản Đông Dương trong nước đang dần hồi phục sau những đợt khủng bố trắng đầu thập niên. Tháng 3/1935, Đại hội đại biểu lần thứ nhất của Đảng họp ở Ma Cao. Đại hội cử Nguyễn Ái Quốc làm đại diện của Đảng bên cạnh Quốc tế Cộng sản. Từ đây, người học viên tên Lin đồng thời là tiếng nói chính thức của Đảng ở Mátxcơva. Trước đó, từ cuối năm 1934, một đoàn đại biểu của Đảng đã có mặt ở Mátxcơva để chuẩn bị dự Đại hội VII Quốc tế Cộng sản. Đoàn do Lê Hồng Phong dẫn đầu, cùng Hoàng Văn Nọn và Nguyễn Thị Minh Khai. Lê Hồng Phong từng là học trò của Người ở Quảng Châu giữa những năm 1920. Nguyễn Thị Minh Khai từng giúp việc Người ở Hồng Kông những năm 1930 – 1931, trước khi cả hai lần lượt bị bắt. Cuộc gặp lại ở Mátxcơva diễn ra sau bao năm mỗi người một ngả, người bị tù đày, người hoạt động bí mật. Với những cán bộ trẻ ấy, được làm việc bên cạnh người sáng lập Đảng là một dịp học hỏi quý giá."},{"t":"Mùa hè Đại hội VII. Từ ngày 25/7 đến 20/8/1935, Đại hội lần thứ VII Quốc tế Cộng sản họp tại Mátxcơva, với 513 đại biểu của 65 đảng, trong đó 371 đại biểu có quyền biểu quyết. Nguyễn Ái Quốc dự đại hội với tư cách đại biểu tư vấn của Ban Phương Đông, thẻ đại biểu số 154. Trường Quốc tế Lê-nin cho Người nghỉ học một tháng để dịch và in các văn kiện đại hội ra tiếng Việt, để đưa về trong nước. Đoàn Đảng Cộng sản Đông Dương có ba bản tham luận. Ngày 28/7/1935, Lê Hồng Phong, bí danh Hải An, trình bày về phong trào cách mạng Đông Dương những năm 1930 – 1935. Ngày 11/8, tại phiên họp thứ 31, Hoàng Văn Nọn, bí danh Văn Tân, nói về đồng bào các dân tộc thiểu số và mặt trận nhân dân. Ngày 16/8, tại phiên họp thứ 40, Nguyễn Thị Minh Khai, bí danh Phan Lan, nói về vai trò của phụ nữ và cuộc đấu tranh chống chiến tranh. Đại hội đề ra chủ trương lập mặt trận nhân dân rộng rãi chống chủ nghĩa phát xít và nguy cơ chiến tranh. Đường lối ấy ảnh hưởng lớn tới cách mạng Đông Dương trong thời kỳ Mặt trận Dân chủ 1936 – 1939."},{"t":"Bạn có biết? Đại hội VII năm 1935 là đại hội cuối cùng của Quốc tế Cộng sản. Tám năm sau, năm 1943, giữa Chiến tranh thế giới thứ hai, tổ chức này tuyên bố tự giải tán."},{"t":"Người thầy của những học viên trẻ. Sau Đại hội VII, Người tiếp tục học ở Trường Quốc tế Lê-nin, đồng thời phụ giảng cho nhóm học viên Việt Nam ở Trường Đại học Phương Đông, dạy lịch sử Đảng và nguyên lý tổ chức đảng. Người còn giúp bà Vera Vaxiliêva, trưởng phòng Đông Dương của Ban Phương Đông, trong công việc của bộ phận này, và giúp các thành viên đoàn đại biểu lần lượt tìm đường trở về Tổ quốc. Tư liệu của Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch cho biết, trong thời gian này có một bức thư ngỏ bằng chữ quốc ngữ gửi Mặt trận Bình dân Pháp. Bức thư đòi thực thi sáu điều về quyền tự do dân chủ, và quyền được tồn tại công khai cho Đảng Cộng sản Đông Dương. Thư không đề tên người viết, nhưng hồ sơ của mật thám Pháp xác định đó là do Nguyễn Ái Quốc soạn thảo. Năm 1936, khi Mặt trận Bình dân lên cầm quyền ở Pháp, phong trào đòi dân sinh, dân chủ ở Đông Dương bùng lên mạnh mẽ. Người ở xa, nhưng tiếng nói của Người vẫn tìm được đường về với phong trào trong nước."},{"t":"Nghiên cứu sinh số hiệu 19. Cuối năm 1936, Người chuyển sang Viện Nghiên cứu các vấn đề dân tộc và thuộc địa, vừa là nghiên cứu sinh, vừa là giáo viên của phòng Đông Dương. Theo tư liệu lưu trữ, Người ở phòng 417, nhà 6A phố Bônsaia Brônnaia. Tháng 1/1937, Viện mở lớp nghiên cứu sinh nhằm đào tạo giảng viên trình độ cao cho các ngành kinh tế và lịch sử; Người là một trong 21 người được tuyển chọn. Kế hoạch cá nhân của nghiên cứu sinh Lin, từ ngày 1/1 đến 31/12/1937, gồm ngôn ngữ, lịch sử và triết học. Người học rất chuyên cần: mùa hè năm 1937, Người là một trong hai nghiên cứu sinh không đi nghỉ hè. Đề tài luận án do Người tự chọn là Cách mạng ruộng đất ở Đông Nam Á. Vấn đề ruộng đất vốn là điều Người trăn trở từ những năm viết báo ở Paris và phát biểu tại Hội nghị Quốc tế Nông dân năm 1923. Ở Đông Dương, tuyệt đại đa số dân cư là nông dân, và câu hỏi làm sao cho người cày có ruộng gắn liền với con đường giải phóng dân tộc. Những năm ở Viện cho Người điều kiện đặt câu hỏi ấy trong bối cảnh rộng hơn của cả khu vực."},{"t":"Bạn có biết? Trong kỳ thi học kỳ I năm học 1937 – 1938, nghiên cứu sinh Lin đạt điểm trung bình ở môn duy vật biện chứng và môn lịch sử cổ đại, trung đại, nhưng đạt điểm xuất sắc ở môn lịch sử hiện đại."},{"t":"Những năm tháng thử thách. Những năm Người ở Mátxcơva lần thứ hai trùng với thời kỳ Liên Xô trải qua các cuộc thanh trừng chính trị nặng nề. Nhiều cán bộ Quốc tế Cộng sản đến từ các nước bị bắt, bị kết án. Trường Đại học Phương Đông, nơi Người từng học năm 1923 và phụ giảng từ năm 1935, bị giải thể trong những năm 1937 – 1938; nhiều giảng viên và cựu học viên của trường trở thành nạn nhân của giai đoạn này. Đầu năm 1936, một cuộc thẩm tra được tiến hành về việc Nguyễn Ái Quốc ra khỏi nhà tù Hồng Kông. Kết luận là không có vấn đề gì, và hồ sơ thẩm tra được hủy bỏ. Các nhà nghiên cứu vẫn có những nhận định khác nhau về vị trí của Người trong mấy năm này. Có tài liệu cho rằng có lúc Người không được giao nhiệm vụ quan trọng, cũng có nghiên cứu cho rằng Người vẫn là thành viên được tin cậy của Quốc tế Cộng sản. Điều chắc chắn là Người giữ được sự điềm tĩnh, tiếp tục học tập, giảng dạy, nghiên cứu, và không ngừng đề nghị được trở về gần Tổ quốc."},{"t":"Lá thư tháng Sáu năm 1938. Tháng 6/1938, đúng dịp tròn bảy năm ngày bị bắt ở Hồng Kông, Người viết một lá thư bằng tiếng Pháp gửi Quốc tế Cộng sản. Người nhắc rằng mình đã bước sang năm thứ tám không được trực tiếp hoạt động. Người đề nghị đừng để mình sống quá lâu trong tình trạng không hoạt động, giống như sống ở bên cạnh, ở bên ngoài Đảng. Ngày 8/6/1938, Phòng tổ chức cán bộ chuyển báo cáo về trường hợp của Người tới Tổng Bí thư Quốc tế Cộng sản Đimitơrốp. Lá thư có kết quả. Ngày 19/8/1938, công văn số 4/797 của Quốc tế Cộng sản đề nghị giải quyết cho đồng chí Lin, người Đông Dương, tức Nguyễn Ái Quốc – Tống Văn Sơ, đến Trung Quốc qua Urumsi, thủ phủ Tân Cương. Kèm theo công văn là bản tóm tắt tiểu sử của Người. Tống Văn Sơ là tên Người mang trong vụ án ở Hồng Kông năm 1931. Sau hơn bốn năm lặng lẽ, cánh cửa về phương Đông cuối cùng đã mở ra."},{"t":"Ga Iarôxláp, mùa thu 1938. Ngày 30/9/1938, Phòng cán bộ của Viện Nghiên cứu các vấn đề dân tộc và thuộc địa ra Quyết định mật số 60. Quyết định ghi rằng sinh viên số hiệu 19, tên Lin, từ ngày 29/9/1938 đã rời khỏi biên chế của Viện để về nước. Tháng 10/1938, Người lên tàu ở ga Iarôxláp, nhà ga của Mátxcơva nơi xuất phát những chuyến tàu xuyên Xibia về phía đông. Từ đây, Người sang Trung Quốc, tới Diên An, rồi trong vai một chiến sĩ Bát lộ quân mang tên Hồ Quang, tìm đường xuống phía nam, ngày càng gần biên giới Việt – Trung. Ngày 28/1/1941, Người vượt cột mốc 108 về Pác Bó, sau ba mươi năm xa Tổ quốc. Những năm lặng lẽ ở Mátxcơva là quãng tích lũy cuối cùng trước khi Người trực tiếp lãnh đạo cách mạng trong nước. Ngày nay, phần lớn những gì ta biết về bốn năm ấy đến từ hồ sơ của Quốc tế Cộng sản còn lưu ở Mátxcơva, nay thuộc Lưu trữ Nhà nước Nga về lịch sử chính trị – xã hội, được các nhà nghiên cứu khai thác trong nhiều năm qua."}],"so_chu":2212},{"i":3,"tieu_de_bang":"Mốc thời gian","tieu_de":"Từ Luận cương của Lênin đến cột mốc 108: dòng thời gian hai chặng ở Liên Xô (1920 – 1941)","sapo":"Có những năm dồn dập đến mức tháng nào cũng có một sự kiện, lại có những năm lặng lẽ tưởng như chẳng có gì xảy ra. Dòng thời gian dưới đây xếp cạnh nhau hơn ba mươi mốc, từ bài báo Người đọc ở Paris năm 1920 đến ngày Người vượt cột mốc 108 về nước năm 1941. Đọc kỹ khoảng cách giữa các mốc, ta hiểu vì sao Liên Xô có mặt ở hai khúc quanh lớn trong cuộc đời Nguyễn Ái Quốc.","bia":{"src":"textures/bai/G08_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Hai chặng, hai tâm thế","text":"Nguyễn Ái Quốc sống ở Liên Xô hai lần, cách nhau một thập niên. Chặng thứ nhất, từ cuối tháng 6/1923 đến cuối tháng 10/1924, kéo dài khoảng mười sáu tháng nhưng dày đặc sự kiện: học tập, dự các hội nghị quốc tế, viết báo, chứng kiến tang lễ Lênin, rồi được cử sang Quảng Châu. Chặng thứ hai, từ mùa hè năm 1934 đến mùa thu năm 1938, dài hơn bốn năm nhưng lặng lẽ hơn nhiều, dành cho học tập, nghiên cứu, giảng dạy và chờ đợi.\n\nGiữa hai chặng là mười năm hoạt động ở Trung Quốc, châu Âu, Xiêm và Hồng Kông, với dấu mốc lớn nhất là sự ra đời của Đảng Cộng sản Việt Nam đầu năm 1930. Dòng thời gian dưới đây mở rộng ra hai phía. Phía trước là những năm ở Paris dẫn Người tới Mátxcơva, phía sau là hành trình từ Mátxcơva về Pác Bó. Đặt trong khung ấy, hai chặng ở Liên Xô hiện ra như hai khúc quanh quyết định của cả con đường.","doc":1},{"loai":"anh","src":"textures/bang_w/G08_3_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn từ xa."},{"loai":"doan","tieu_de":"Trước khi lên đường (1920 – 1923)","text":"Những mốc đầu tiên của dòng thời gian không nằm ở Liên Xô mà ở Paris. Tháng 7/1920, bản luận cương của Lênin về vấn đề dân tộc và thuộc địa cho Nguyễn Ái Quốc thấy con đường giải phóng cho đồng bào mình. Tháng 12/1920, lá phiếu ở Đại hội Tua đưa Người vào hàng ngũ Quốc tế Cộng sản. Ba năm sau đó là những năm Người làm báo Le Paria, hoạt động trong Hội Liên hiệp thuộc địa, và bị mật thám theo dõi từng bước.\n\nKhi Manuinxki, Ủy viên Ban Chấp hành Quốc tế Cộng sản, đề nghị Đảng Cộng sản Pháp cử Người sang Mátxcơva, mọi thứ đã sẵn sàng. Bốn mốc của tháng 6/1923 cho thấy chuyến đi được tổ chức chặt chẽ ra sao: rời Paris ngày 13, nhận giấy tờ ở Berlin ngày 16, xuống tàu ở Hamburg ngày 27, cập bến Petrograd ngày 30. Mỗi mốc là một chặng của cuộc thoát ly khỏi vòng vây mật thám (xem chuyên đề Chuyến đi bí mật từ Paris tới Petrograd).","doc":2},{"loai":"moc","items":[["7/1920","Tại Paris, đọc bản Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của Lênin đăng trên báo L'Humanité"],["12/1920","Tại Đại hội Tua, bỏ phiếu tán thành gia nhập Quốc tế Cộng sản, trở thành một trong những người tham gia sáng lập Đảng Cộng sản Pháp"],["13/6/1923","Buổi tối, rời rạp chiếu phim bằng cửa sau, xuống tàu điện ngầm tới ga phía Bắc, bí mật rời Paris"],["16/6/1923","Tại Berlin, nhận giấy thông hành số 1829 của đại diện toàn quyền Xô-viết, đứng tên người thợ ảnh Chen Vang"],["27/6/1923","Rời cảng Hamburg trên con tàu mang tên nhà cách mạng Đức Karl Liebknecht"],["30/6/1923","Tàu cập Bến số 7 cảng Gutuev, Petrograd; ít lâu sau lên xe lửa đi Mátxcơva, làm việc với Quốc tế Cộng sản"],["10/1923","Dự Hội nghị Quốc tế Nông dân lần thứ nhất ở Mátxcơva, phát biểu tại hai phiên họp, được bầu vào Đoàn Chủ tịch gồm 11 ủy viên"],["Cuối 1923","Theo học lớp ngắn hạn của Trường Đại học Cộng sản của những người lao động phương Đông, là học viên đầu tiên đến từ Đông Dương"],["23/12/1923","Tạp chí Ogoniok số 39 đăng bài của nhà thơ Ôxíp Manđenxtam viết về cuộc gặp với Nguyễn Ái Quốc"],["27/1/1924","Lễ an táng Lênin, người từ trần ngày 21/1 tại Goócki; cùng ngày, báo Pravda đăng bài Lênin và các dân tộc thuộc địa của Nguyễn Ái Quốc"],["14/4/1924","Được nhận làm cán bộ Ban Phương Đông của Quốc tế Cộng sản, bộ phận theo dõi phong trào cách mạng ở châu Á"],["17/6 – 8/7/1924","Dự Đại hội V Quốc tế Cộng sản ở Mátxcơva với tư cách đại biểu tư vấn"],["23/6/1924","Phát biểu tại phiên họp thứ 8 của Đại hội V về vấn đề thuộc địa, phê bình các đảng ở chính quốc chưa quan tâm đúng mức tới thuộc địa"],["Cuối 10/1924","Rời Mátxcơva lên đường sang Trung Quốc theo sự phân công của Quốc tế Cộng sản"],["11/11/1924","Đến Quảng Châu, mở đầu chặng hoạt động sát cạnh quê hương"],["6/1925","Thành lập Hội Việt Nam Cách mạng Thanh niên ở Quảng Châu, mở các lớp huấn luyện cán bộ"],["1927","Sau chính biến tháng 4 ở Trung Quốc, trở lại Mátxcơva một thời gian ngắn rồi sang châu Âu"],["6/1 – 7/2/1930","Chủ trì hội nghị hợp nhất các tổ chức cộng sản tại Cửu Long, Hương Cảng, thành lập Đảng Cộng sản Việt Nam"],["6/6/1931","Bị cảnh sát Anh bắt ở Hồng Kông; vụ án về sau được đưa lên tới Hội đồng Cơ mật Hoàng gia ở London"],["Đầu 1933","Được trả tự do, rời Hồng Kông, sống bí mật ở Thượng Hải và tìm cách liên lạc lại với Quốc tế Cộng sản"],["6/1934","Từ Thượng Hải, đi trên một tàu buôn Liên Xô tới cảng Vlađivôxtốc, rồi về Mátxcơva"],["2/10/1934","Được nhận vào Trường Quốc tế Lê-nin theo Quyết định số 45, với tên Lin, học viên số hiệu 375"],["3/1935","Đại hội lần thứ nhất của Đảng Cộng sản Đông Dương họp ở Ma Cao, cử Người làm đại diện của Đảng bên cạnh Quốc tế Cộng sản"],["25/7 – 20/8/1935","Dự Đại hội VII Quốc tế Cộng sản với tư cách đại biểu tư vấn, thẻ số 154; đoàn Đảng Cộng sản Đông Dương do Lê Hồng Phong dẫn đầu"],["Cuối 1936","Chuyển sang Viện Nghiên cứu các vấn đề dân tộc và thuộc địa, vừa là nghiên cứu sinh vừa là giáo viên phòng Đông Dương"],["1/1937","Là một trong 21 người vào lớp nghiên cứu sinh của Viện; tự chọn đề tài Cách mạng ruộng đất ở Đông Nam Á"],["6/1938","Viết thư bằng tiếng Pháp đề nghị Quốc tế Cộng sản cho trở lại hoạt động; ngày 8/6, trường hợp của Người được báo cáo lên Tổng Bí thư Đimitơrốp"],["19/8/1938","Công văn số 4/797 của Quốc tế Cộng sản đề nghị cho đồng chí Lin đi Trung Quốc qua Urumsi, Tân Cương"],["29/9/1938","Rời biên chế Viện để về nước, theo Quyết định mật số 60 ký ngày 30/9/1938"],["10/1938","Lên tàu ở ga Iarôxláp, rời Mátxcơva về Trung Quốc, bắt đầu hành trình trở về Tổ quốc"],["28/1/1941","Vượt cột mốc 108 về Pác Bó, sau ba mươi năm xa Tổ quốc"]],"doc":3},{"loai":"doan","tieu_de":"Mười sáu tháng dày đặc","text":"Hãy để ý mật độ của các mốc từ tháng 7/1923 đến tháng 10/1924. Gần như tháng nào cũng có một sự kiện đáng nhớ. Trong quãng thời gian ấy, Người đóng nhiều vai cùng lúc: học viên của Trường Đại học Phương Đông, ủy viên Đoàn Chủ tịch Quốc tế Nông dân, cây bút của nhiều tờ báo, rồi cán bộ Ban Phương Đông của Quốc tế Cộng sản.\n\nHai sự kiện nổi bật nhất nằm trong bảy tháng đầu năm 1924. Tháng 1, Người đứng trong dòng người tiễn đưa Lênin giữa giá rét, và bài báo của Người xuất hiện trên tờ Pravda đúng ngày tang lễ. Tháng 6, Người đứng trước diễn đàn lớn nhất của phong trào cộng sản quốc tế để nói về các dân tộc thuộc địa. Từ một cây bút được biết đến trong giới người thuộc địa ở Paris, chỉ sau hơn một năm, Người đã là một cán bộ được Quốc tế Cộng sản tin cậy giao nhiệm vụ ở phương Đông. Chính sự tin cậy ấy mở đường cho những năm hoạt động ở Quảng Châu.","doc":4},{"loai":"anh","src":"textures/ht/ht_anh_advisory_delegate_card_issued_to_nguyen_ai_quoc_.jpg","chu_thich":"Thẻ đại biểu tư vấn của Nguyễn Ái Quốc dự Đại hội V Quốc tế Cộng sản, Mátxcơva, 1924.","credit":"Ảnh: 5th Congress of the Communist Internatio · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Mười năm giữa hai chặng","text":"Khoảng trống mười năm giữa hai chặng thật ra không hề trống. Đó là thập niên Người gây dựng những nền móng đầu tiên cho cách mạng Việt Nam: Hội Việt Nam Cách mạng Thanh niên năm 1925, những lớp huấn luyện ở Quảng Châu, những năm sống giữa kiều bào ở Xiêm, rồi hội nghị hợp nhất đầu năm 1930. Mátxcơva vẫn hiện diện trong thập niên ấy qua một lần trở lại ngắn ngày năm 1927, sau khi cách mạng Trung Quốc bị đàn áp.\n\nNhưng thập niên ấy cũng khép lại bằng những năm khó khăn nhất: bị bắt ở Hồng Kông năm 1931, rồi những tháng sống bí mật ở Thượng Hải. Khi con tàu buôn Liên Xô đưa Người tới Vlađivôxtốc tháng 6/1934, người khách ấy mang theo cả thành công lẫn những bài học đắt giá của mười năm thực tiễn. Chặng thứ hai ở Liên Xô vì thế không phải là sự lặp lại của chặng thứ nhất, mà là một cuộc tổng kết.","doc":5},{"loai":"ban_co_biet","text":"Nguyễn Ái Quốc đặt chân tới Petrograd ngày 30/6/1923 và tới Quảng Châu ngày 11/11/1924: chưa đầy mười bảy tháng, nhưng đó là một trong những giai đoạn dày đặc sự kiện nhất trong cuộc đời hoạt động của Người.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","doc":6},{"loai":"doan","tieu_de":"Chặng thứ hai: nhịp chậm của sự kiên nhẫn","text":"Từ mốc tháng 6/1934, dòng thời gian bỗng thưa hẳn. Có những quãng nửa năm, một năm chỉ có một mốc, như một quyết định nhập học hay một lớp nghiên cứu sinh mới mở. Đại hội VII Quốc tế Cộng sản mùa hè năm 1935 là sự kiện công khai lớn nhất, cũng là dịp Người gặp đoàn đại biểu Đảng Cộng sản Đông Dương do Lê Hồng Phong dẫn đầu. Còn lại là những ngày học ở Trường Quốc tế Lê-nin, dạy ở Trường Đại học Phương Đông, nghiên cứu ở Viện Nghiên cứu các vấn đề dân tộc và thuộc địa.\n\nSự thưa thớt ấy có lý do. Những năm 1936 – 1938, Liên Xô chìm trong các cuộc thanh trừng chính trị, và nhiều cán bộ Quốc tế Cộng sản bị liên lụy. Bốn mốc cuối cùng của năm 1938 là bốn bước của một cánh cửa hé mở: lá thư đề nghị tháng 6, công văn tháng 8, quyết định cho về nước tháng 9, và chuyến tàu rời ga Iarôxláp tháng 10 (xem chuyên đề Đồng chí Lin ở Mátxcơva, 1934 – 1938).","doc":7},{"loai":"anh","src":"textures/bang_w/G08_3_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Những tờ giấy làm nên dòng thời gian","text":"Nhiều mốc trong dòng thời gian này được xác lập nhờ những tờ giấy nhỏ còn lại tới hôm nay. Giấy thông hành số 1829 cho biết ngày 16/6/1923 Người có mặt ở Berlin. Tấm thẻ đại biểu tư vấn khẳng định tư cách của Người tại Đại hội V. Số tạp chí Ogoniok ngày 23/12/1923 và số báo Pravda ngày 27/1/1924 là những trang in có ngày tháng rõ ràng.\n\nVới chặng thứ hai, các quyết định nhập học, quyết định cho về nước, công văn và thư từ trong hồ sơ Quốc tế Cộng sản cho biết đến từng ngày, từng số hiệu học viên. Những hồ sơ ấy nay thuộc Lưu trữ Nhà nước Nga về lịch sử chính trị – xã hội ở Mátxcơva. Cùng với báo cáo của mật thám Pháp và lời kể của những người cùng thời, chúng là nguồn để các nhà nghiên cứu dựng lại hành trình của Người, như trong bộ Hồ Chí Minh – Biên niên tiểu sử. Mỗi ngày tháng trên dòng thời gian vì thế là kết quả của nhiều năm lần tìm và đối chiếu.","doc":8},{"loai":"ban_co_biet","text":"Bộ Hồ Chí Minh – Biên niên tiểu sử gồm 10 tập, ghi lại hoạt động của Người theo từng năm, từng tháng, có khi từng ngày; hai chặng ở Liên Xô nằm trong tập 1 và tập 2 của bộ sách.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","doc":9},{"loai":"anh","src":"textures/ht/ht_anh_article_lenin_and_the_colonial_peoples_by_nguyen.jpg","chu_thich":"Bài báo Lênin và các dân tộc thuộc địa của Nguyễn Ái Quốc trên báo Pravda ngày 27/1/1924, đúng ngày an táng Lênin.","credit":"Ảnh: Nguyen Ai Quoc (Ho Chi Minh) · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Đọc dòng thời gian thế nào?","text":"Có ba cách đọc dòng thời gian này. Cách thứ nhất là đọc theo khoảng cách: những mốc dồn dập năm 1923 – 1924 đối lập với những quãng lặng năm 1936 – 1938. Cách thứ hai là đọc theo tên gọi: Nguyễn Ái Quốc ở Paris, Chen Vang trên giấy thông hành, Lin trong hồ sơ Trường Quốc tế Lê-nin, Tống Văn Sơ trong công văn năm 1938, Hồ Quang trên đường về. Mỗi tên gọi ứng với một chặng và một nhiệm vụ.\n\nCách thứ ba là đọc theo hướng đi. Năm 1923, Người đi từ tây sang đông, từ Paris tới Mátxcơva. Năm 1924 và năm 1938, Người đều rời Mátxcơva để đi về phía Trung Quốc, lần sau gần Tổ quốc hơn lần trước. Mốc cuối cùng, ngày 28/1/1941, là đích đến của cả hành trình: Người vượt cột mốc 108 về Pác Bó. Gần mười tám năm sau buổi tối lặng lẽ rời Paris, người thanh niên năm nào đã trở về, mang theo tất cả những gì học được trên đường.","doc":10}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 1 và tập 2, NXB Chính trị quốc gia","Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch – Nguyễn Ái Quốc trên đất nước của Lênin (1923 – 1924): https://nhasanbacho.vn/bai-viet/nguyen-ai-quoc-tren-dat-nuoc-cua-lenin-1923-1924-222/","Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch – Nguyễn Ái Quốc trên đất nước Liên Xô (1934 – 1938): https://nhasanbacho.vn/bai-viet/nguyen-ai-quoc-tren-dat-nuoc-lien-xo-1934-1938/","Chính trị và Phát triển – Nguyễn Ái Quốc và chuyến đi đầu tiên đến nước Nga Xô viết: https://chinhtrivaphattrien.vn/nguyen-ai-quoc-va-chuyen-di-dau-tien-den-nuoc-nga-xo-viet-a7870.html","Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia"],"doc":[{"t":"Từ Luận cương của Lênin đến cột mốc 108: dòng thời gian hai chặng ở Liên Xô (1920 – 1941). Có những năm dồn dập đến mức tháng nào cũng có một sự kiện, lại có những năm lặng lẽ tưởng như chẳng có gì xảy ra. Dòng thời gian dưới đây xếp cạnh nhau hơn ba mươi mốc, từ bài báo Người đọc ở Paris năm 1920 đến ngày Người vượt cột mốc 108 về nước năm 1941. Đọc kỹ khoảng cách giữa các mốc, ta hiểu vì sao Liên Xô có mặt ở hai khúc quanh lớn trong cuộc đời Nguyễn Ái Quốc."},{"t":"Hai chặng, hai tâm thế. Nguyễn Ái Quốc sống ở Liên Xô hai lần, cách nhau một thập niên. Chặng thứ nhất, từ cuối tháng 6/1923 đến cuối tháng 10/1924, kéo dài khoảng mười sáu tháng nhưng dày đặc sự kiện: học tập, dự các hội nghị quốc tế, viết báo, chứng kiến tang lễ Lênin, rồi được cử sang Quảng Châu. Chặng thứ hai, từ mùa hè năm 1934 đến mùa thu năm 1938, dài hơn bốn năm nhưng lặng lẽ hơn nhiều, dành cho học tập, nghiên cứu, giảng dạy và chờ đợi. Giữa hai chặng là mười năm hoạt động ở Trung Quốc, châu Âu, Xiêm và Hồng Kông, với dấu mốc lớn nhất là sự ra đời của Đảng Cộng sản Việt Nam đầu năm 1930. Dòng thời gian dưới đây mở rộng ra hai phía. Phía trước là những năm ở Paris dẫn Người tới Mátxcơva, phía sau là hành trình từ Mátxcơva về Pác Bó. Đặt trong khung ấy, hai chặng ở Liên Xô hiện ra như hai khúc quanh quyết định của cả con đường."},{"t":"Trước khi lên đường (1920 – 1923). Những mốc đầu tiên của dòng thời gian không nằm ở Liên Xô mà ở Paris. Tháng 7/1920, bản luận cương của Lênin về vấn đề dân tộc và thuộc địa cho Nguyễn Ái Quốc thấy con đường giải phóng cho đồng bào mình. Tháng 12/1920, lá phiếu ở Đại hội Tua đưa Người vào hàng ngũ Quốc tế Cộng sản. Ba năm sau đó là những năm Người làm báo Le Paria, hoạt động trong Hội Liên hiệp thuộc địa, và bị mật thám theo dõi từng bước. Khi Manuinxki, Ủy viên Ban Chấp hành Quốc tế Cộng sản, đề nghị Đảng Cộng sản Pháp cử Người sang Mátxcơva, mọi thứ đã sẵn sàng. Bốn mốc của tháng 6/1923 cho thấy chuyến đi được tổ chức chặt chẽ ra sao: rời Paris ngày 13, nhận giấy tờ ở Berlin ngày 16, xuống tàu ở Hamburg ngày 27, cập bến Petrograd ngày 30. Mỗi mốc là một chặng của cuộc thoát ly khỏi vòng vây mật thám (xem chuyên đề Chuyến đi bí mật từ Paris tới Petrograd)."},{"t":"Các mốc thời gian. 7/1920: Tại Paris, đọc bản Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của Lênin đăng trên báo L'Humanité. 12/1920: Tại Đại hội Tua, bỏ phiếu tán thành gia nhập Quốc tế Cộng sản, trở thành một trong những người tham gia sáng lập Đảng Cộng sản Pháp. 13/6/1923: Buổi tối, rời rạp chiếu phim bằng cửa sau, xuống tàu điện ngầm tới ga phía Bắc, bí mật rời Paris. 16/6/1923: Tại Berlin, nhận giấy thông hành số 1829 của đại diện toàn quyền Xô-viết, đứng tên người thợ ảnh Chen Vang. 27/6/1923: Rời cảng Hamburg trên con tàu mang tên nhà cách mạng Đức Karl Liebknecht. 30/6/1923: Tàu cập Bến số 7 cảng Gutuev, Petrograd; ít lâu sau lên xe lửa đi Mátxcơva, làm việc với Quốc tế Cộng sản. 10/1923: Dự Hội nghị Quốc tế Nông dân lần thứ nhất ở Mátxcơva, phát biểu tại hai phiên họp, được bầu vào Đoàn Chủ tịch gồm 11 ủy viên. Cuối 1923: Theo học lớp ngắn hạn của Trường Đại học Cộng sản của những người lao động phương Đông, là học viên đầu tiên đến từ Đông Dương. 23/12/1923: Tạp chí Ogoniok số 39 đăng bài của nhà thơ Ôxíp Manđenxtam viết về cuộc gặp với Nguyễn Ái Quốc. 27/1/1924: Lễ an táng Lênin, người từ trần ngày 21/1 tại Goócki; cùng ngày, báo Pravda đăng bài Lênin và các dân tộc thuộc địa của Nguyễn Ái Quốc. 14/4/1924: Được nhận làm cán bộ Ban Phương Đông của Quốc tế Cộng sản, bộ phận theo dõi phong trào cách mạng ở châu Á. 17/6 – 8/7/1924: Dự Đại hội V Quốc tế Cộng sản ở Mátxcơva với tư cách đại biểu tư vấn. 23/6/1924: Phát biểu tại phiên họp thứ 8 của Đại hội V về vấn đề thuộc địa, phê bình các đảng ở chính quốc chưa quan tâm đúng mức tới thuộc địa. Cuối 10/1924: Rời Mátxcơva lên đường sang Trung Quốc theo sự phân công của Quốc tế Cộng sản. 11/11/1924: Đến Quảng Châu, mở đầu chặng hoạt động sát cạnh quê hương. 6/1925: Thành lập Hội Việt Nam Cách mạng Thanh niên ở Quảng Châu, mở các lớp huấn luyện cán bộ. 1927: Sau chính biến tháng 4 ở Trung Quốc, trở lại Mátxcơva một thời gian ngắn rồi sang châu Âu. 6/1 – 7/2/1930: Chủ trì hội nghị hợp nhất các tổ chức cộng sản tại Cửu Long, Hương Cảng, thành lập Đảng Cộng sản Việt Nam. 6/6/1931: Bị cảnh sát Anh bắt ở Hồng Kông; vụ án về sau được đưa lên tới Hội đồng Cơ mật Hoàng gia ở London. Đầu 1933: Được trả tự do, rời Hồng Kông, sống bí mật ở Thượng Hải và tìm cách liên lạc lại với Quốc tế Cộng sản. 6/1934: Từ Thượng Hải, đi trên một tàu buôn Liên Xô tới cảng Vlađivôxtốc, rồi về Mátxcơva. 2/10/1934: Được nhận vào Trường Quốc tế Lê-nin theo Quyết định số 45, với tên Lin, học viên số hiệu 375. 3/1935: Đại hội lần thứ nhất của Đảng Cộng sản Đông Dương họp ở Ma Cao, cử Người làm đại diện của Đảng bên cạnh Quốc tế Cộng sản. 25/7 – 20/8/1935: Dự Đại hội VII Quốc tế Cộng sản với tư cách đại biểu tư vấn, thẻ số 154; đoàn Đảng Cộng sản Đông Dương do Lê Hồng Phong dẫn đầu. Cuối 1936: Chuyển sang Viện Nghiên cứu các vấn đề dân tộc và thuộc địa, vừa là nghiên cứu sinh vừa là giáo viên phòng Đông Dương. 1/1937: Là một trong 21 người vào lớp nghiên cứu sinh của Viện; tự chọn đề tài Cách mạng ruộng đất ở Đông Nam Á. 6/1938: Viết thư bằng tiếng Pháp đề nghị Quốc tế Cộng sản cho trở lại hoạt động; ngày 8/6, trường hợp của Người được báo cáo lên Tổng Bí thư Đimitơrốp. 19/8/1938: Công văn số 4/797 của Quốc tế Cộng sản đề nghị cho đồng chí Lin đi Trung Quốc qua Urumsi, Tân Cương. 29/9/1938: Rời biên chế Viện để về nước, theo Quyết định mật số 60 ký ngày 30/9/1938. 10/1938: Lên tàu ở ga Iarôxláp, rời Mátxcơva về Trung Quốc, bắt đầu hành trình trở về Tổ quốc. 28/1/1941: Vượt cột mốc 108 về Pác Bó, sau ba mươi năm xa Tổ quốc."},{"t":"Mười sáu tháng dày đặc. Hãy để ý mật độ của các mốc từ tháng 7/1923 đến tháng 10/1924. Gần như tháng nào cũng có một sự kiện đáng nhớ. Trong quãng thời gian ấy, Người đóng nhiều vai cùng lúc: học viên của Trường Đại học Phương Đông, ủy viên Đoàn Chủ tịch Quốc tế Nông dân, cây bút của nhiều tờ báo, rồi cán bộ Ban Phương Đông của Quốc tế Cộng sản. Hai sự kiện nổi bật nhất nằm trong bảy tháng đầu năm 1924. Tháng 1, Người đứng trong dòng người tiễn đưa Lênin giữa giá rét, và bài báo của Người xuất hiện trên tờ Pravda đúng ngày tang lễ. Tháng 6, Người đứng trước diễn đàn lớn nhất của phong trào cộng sản quốc tế để nói về các dân tộc thuộc địa. Từ một cây bút được biết đến trong giới người thuộc địa ở Paris, chỉ sau hơn một năm, Người đã là một cán bộ được Quốc tế Cộng sản tin cậy giao nhiệm vụ ở phương Đông. Chính sự tin cậy ấy mở đường cho những năm hoạt động ở Quảng Châu."},{"t":"Mười năm giữa hai chặng. Khoảng trống mười năm giữa hai chặng thật ra không hề trống. Đó là thập niên Người gây dựng những nền móng đầu tiên cho cách mạng Việt Nam: Hội Việt Nam Cách mạng Thanh niên năm 1925, những lớp huấn luyện ở Quảng Châu, những năm sống giữa kiều bào ở Xiêm, rồi hội nghị hợp nhất đầu năm 1930. Mátxcơva vẫn hiện diện trong thập niên ấy qua một lần trở lại ngắn ngày năm 1927, sau khi cách mạng Trung Quốc bị đàn áp. Nhưng thập niên ấy cũng khép lại bằng những năm khó khăn nhất: bị bắt ở Hồng Kông năm 1931, rồi những tháng sống bí mật ở Thượng Hải. Khi con tàu buôn Liên Xô đưa Người tới Vlađivôxtốc tháng 6/1934, người khách ấy mang theo cả thành công lẫn những bài học đắt giá của mười năm thực tiễn. Chặng thứ hai ở Liên Xô vì thế không phải là sự lặp lại của chặng thứ nhất, mà là một cuộc tổng kết."},{"t":"Bạn có biết? Nguyễn Ái Quốc đặt chân tới Petrograd ngày 30/6/1923 và tới Quảng Châu ngày 11/11/1924: chưa đầy mười bảy tháng, nhưng đó là một trong những giai đoạn dày đặc sự kiện nhất trong cuộc đời hoạt động của Người."},{"t":"Chặng thứ hai: nhịp chậm của sự kiên nhẫn. Từ mốc tháng 6/1934, dòng thời gian bỗng thưa hẳn. Có những quãng nửa năm, một năm chỉ có một mốc, như một quyết định nhập học hay một lớp nghiên cứu sinh mới mở. Đại hội VII Quốc tế Cộng sản mùa hè năm 1935 là sự kiện công khai lớn nhất, cũng là dịp Người gặp đoàn đại biểu Đảng Cộng sản Đông Dương do Lê Hồng Phong dẫn đầu. Còn lại là những ngày học ở Trường Quốc tế Lê-nin, dạy ở Trường Đại học Phương Đông, nghiên cứu ở Viện Nghiên cứu các vấn đề dân tộc và thuộc địa. Sự thưa thớt ấy có lý do. Những năm 1936 – 1938, Liên Xô chìm trong các cuộc thanh trừng chính trị, và nhiều cán bộ Quốc tế Cộng sản bị liên lụy. Bốn mốc cuối cùng của năm 1938 là bốn bước của một cánh cửa hé mở: lá thư đề nghị tháng 6, công văn tháng 8, quyết định cho về nước tháng 9, và chuyến tàu rời ga Iarôxláp tháng 10 (xem chuyên đề Đồng chí Lin ở Mátxcơva, 1934 – 1938)."},{"t":"Những tờ giấy làm nên dòng thời gian. Nhiều mốc trong dòng thời gian này được xác lập nhờ những tờ giấy nhỏ còn lại tới hôm nay. Giấy thông hành số 1829 cho biết ngày 16/6/1923 Người có mặt ở Berlin. Tấm thẻ đại biểu tư vấn khẳng định tư cách của Người tại Đại hội V. Số tạp chí Ogoniok ngày 23/12/1923 và số báo Pravda ngày 27/1/1924 là những trang in có ngày tháng rõ ràng. Với chặng thứ hai, các quyết định nhập học, quyết định cho về nước, công văn và thư từ trong hồ sơ Quốc tế Cộng sản cho biết đến từng ngày, từng số hiệu học viên. Những hồ sơ ấy nay thuộc Lưu trữ Nhà nước Nga về lịch sử chính trị – xã hội ở Mátxcơva. Cùng với báo cáo của mật thám Pháp và lời kể của những người cùng thời, chúng là nguồn để các nhà nghiên cứu dựng lại hành trình của Người, như trong bộ Hồ Chí Minh – Biên niên tiểu sử. Mỗi ngày tháng trên dòng thời gian vì thế là kết quả của nhiều năm lần tìm và đối chiếu."},{"t":"Bạn có biết? Bộ Hồ Chí Minh – Biên niên tiểu sử gồm 10 tập, ghi lại hoạt động của Người theo từng năm, từng tháng, có khi từng ngày; hai chặng ở Liên Xô nằm trong tập 1 và tập 2 của bộ sách."},{"t":"Đọc dòng thời gian thế nào?. Có ba cách đọc dòng thời gian này. Cách thứ nhất là đọc theo khoảng cách: những mốc dồn dập năm 1923 – 1924 đối lập với những quãng lặng năm 1936 – 1938. Cách thứ hai là đọc theo tên gọi: Nguyễn Ái Quốc ở Paris, Chen Vang trên giấy thông hành, Lin trong hồ sơ Trường Quốc tế Lê-nin, Tống Văn Sơ trong công văn năm 1938, Hồ Quang trên đường về. Mỗi tên gọi ứng với một chặng và một nhiệm vụ. Cách thứ ba là đọc theo hướng đi. Năm 1923, Người đi từ tây sang đông, từ Paris tới Mátxcơva. Năm 1924 và năm 1938, Người đều rời Mátxcơva để đi về phía Trung Quốc, lần sau gần Tổ quốc hơn lần trước. Mốc cuối cùng, ngày 28/1/1941, là đích đến của cả hành trình: Người vượt cột mốc 108 về Pác Bó. Gần mười tám năm sau buổi tối lặng lẽ rời Paris, người thanh niên năm nào đã trở về, mang theo tất cả những gì học được trên đường."}],"so_chu":1435},{"i":4,"tieu_de_bang":"Nguyễn Ái Quốc ở Liên Xô, 1923","tieu_de":"Người thanh niên mặc áo len đan: Nguyễn Ái Quốc năm 1923 qua tấm ảnh và trang báo của Manđenxtam","sapo":"Một ngày cuối năm 1923 ở Mátxcơva, nhà thơ Nga Ôxíp Manđenxtam ngồi trước người mà ông gọi là người An Nam duy nhất của thành phố, và mở đầu bằng một câu hỏi về Gandhi. Cuộc trò chuyện ấy thành một bài báo mà gần một thế kỷ sau người Việt Nam vẫn còn trích dẫn. Tấm ảnh chụp cùng năm cho ta thấy gương mặt Nguyễn Ái Quốc; trang báo của nhà thơ cho ta nghe giọng nói của Người.","bia":{"src":"textures/ht/ht_anh_nguyen_ai_quoc_in_the_soviet_union_in_1923.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Một câu hỏi về Gandhi","text":"Bài báo mở đầu bằng một câu hỏi, không cần lời giới thiệu. Nhà thơ hỏi người đối diện: phong trào của Gandhi ở Ấn Độ có vọng tới Đông Dương không, có con sóng hay tiếng dội nào dạt tới đó chưa? Người thanh niên châu Á đáp là không. Theo lời Người, nông dân An Nam đang sống chìm trong một đêm tối dày đặc, không báo chí, không hề biết thế giới bên ngoài ra sao. Người nhắc lại: đêm, một đêm thật sự.\n\nNgười hỏi là Ôxíp Manđenxtam, sinh năm 1891, một gương mặt chính của phái thơ Acmê ở Nga, tác giả các tập thơ Đá và Tristia. Những năm ấy ông sống ở Mátxcơva, viết báo và dịch sách để kiếm sống. Cuộc trò chuyện được in trên tạp chí Ogoniok (Ngọn lửa nhỏ), số 39, ngày 23/12/1923. Ở Việt Nam, bài báo quen thuộc với nhan đề \"Thăm một chiến sĩ Quốc tế Cộng sản – Nguyễn Ái Quốc\". Đó là bức chân dung bằng chữ hiếm hoi về Người trong năm đầu ở nước Nga, do chính người ngồi trò chuyện với Người viết ra.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_nguyen_ai_quoc_in_the_soviet_union_in_1923.jpg","chu_thich":"Nguyễn Ái Quốc ở Liên Xô năm 1923, những tháng đầu của chặng thứ nhất ở nước Nga Xô-viết. Ảnh không rõ tác giả, thuộc phạm vi công cộng.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Người trong ảnh","text":"Tấm ảnh ở bảng này được chụp tại nước Nga Xô-viết năm 1923, không rõ người chụp. Người trong ảnh vừa bước sang tuổi ba mươi ba. Ngày 13/6/1923, Người lặng lẽ rời Paris; ngày 30/6, Người tới Petrograd rồi về Mátxcơva làm việc với Quốc tế Cộng sản (xem chuyên đề Chuyến đi bí mật từ Paris tới Petrograd). Sau lưng Người là mười hai năm bôn ba kể từ ngày rời bến Nhà Rồng năm 1911: làm phụ bếp trên tàu biển, rồi sống bằng nghề sửa ảnh ở Paris. Năm 1919, bản Yêu sách của nhân dân An Nam gửi Hội nghị Véc-xây mang chữ ký Nguyễn Ái Quốc; từ năm 1922, Người làm chủ bút tờ Le Paria (Người cùng khổ).\n\nMột tấm ảnh chỉ giữ lại gương mặt trong một khoảnh khắc. Nó không ghi được giọng nói, cách chọn chữ, hay lúc gương mặt bỗng sáng lên khi nói về quê hương. Những điều ấy, thật may, lại được nhà thơ chép lại ngay trong năm 1923.","doc":2},{"loai":"anh","src":"textures/bang_w/G08_4_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nguyễn Ái Quốc ở Liên Xô, 1923”, nhìn từ xa."},{"loai":"doan","tieu_de":"\"Gần như một cậu bé, mặc áo len đan\"","text":"Manđenxtam gọi người đối diện là người An Nam duy nhất ở Mátxcơva. Ông tả Người gần như còn là một cậu bé, gầy và mềm mại, mặc chiếc áo khoác len đan. Người nói bằng tiếng Pháp, thứ tiếng của những kẻ áp bức. Nhưng theo nhà thơ, những chữ Pháp ấy vang lên đục và trầm, như tiếng một quả chuông bị nén lại, quả chuông của tiếng mẹ đẻ.\n\nNhà thơ còn ghi rằng Người đã đi gần khắp thế giới thuộc địa, từng tới Bắc Phi và Trung Phi. Trong câu chuyện, Người hay nói hai chữ \"anh em\". Anh em, đó là những người da đen, người Ấn Độ, người Xyri, người Trung Quốc. Người kể đã viết thư cho nhà văn René Maran, tác giả tiểu thuyết Batouala đoạt giải Goncourt năm 1921, hỏi thẳng rằng ông có muốn góp sức giải phóng những người anh em thuộc địa hay không. Theo bài báo, Maran trả lời dè dặt và né tránh.","doc":3},{"loai":"ban_co_biet","text":"Manđenxtam tả Nguyễn Ái Quốc \"gần như còn là một cậu bé\", nhưng thật ra nhà thơ còn kém Người gần tám tháng tuổi: Nguyễn Ái Quốc sinh ngày 19/5/1890, còn Manđenxtam sinh ngày 15/1/1891. Khi gặp nhau cuối năm 1923, cả hai đều đã ngoài ba mươi.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia; Bách khoa toàn thư Britannica, mục Osip Mandelstam","doc":4},{"loai":"doan","tieu_de":"Ba chữ Pháp năm mười ba tuổi","text":"Khi ấy, Người mới sống ở nước Nga chưa đầy sáu tháng, nhưng phần dài nhất của bài báo là lời Người tự kể về quê hương. Người nói mình xuất thân từ một gia đình An Nam thuộc tầng lớp trên, nơi các chàng trai theo học đạo Khổng. Người giải thích cho nhà thơ Nga rằng đạo Khổng không hẳn là một tôn giáo, mà đúng hơn là môn học về kinh nghiệm đạo đức và phép ứng xử, đặt nền trên sự hòa thuận trong xã hội. Lời kể ấy khớp với những gì sử liệu cho biết: thân phụ Người, cụ Nguyễn Sinh Sắc, là một nhà nho đỗ Phó bảng năm 1901, và tuổi thơ của Người gắn với sách thánh hiền ở làng Sen và ở Huế. Rồi Người kể về khoảnh khắc đã đổi hướng cả cuộc đời mình, bằng những câu về sau được dịch ra tiếng Việt và trích dẫn rất nhiều lần.","doc":5},{"loai":"trich","text":"Vào trạc tuổi mười ba, lần đầu tiên tôi được nghe ba chữ Pháp: Tự do, Bình đẳng, Bác ái. Đối với chúng tôi, người da trắng nào cũng là người Pháp. Thế là tôi muốn làm quen với nền văn minh Pháp, muốn tìm xem những gì ẩn đằng sau những chữ ấy.","nguoi":"Nguyễn Ái Quốc, trả lời nhà thơ Ôxíp Manđenxtam","nguon_ten":"Tạp chí Ogoniok, số 39, 23/12/1923 (bản dịch tiếng Việt)","doc":6},{"loai":"doan","tieu_de":"Rời quê năm mười chín tuổi?","text":"Người kể tiếp: ở các trường dành cho người bản xứ, người Pháp chỉ đào tạo ra những con vẹt. Sách báo bị giấu kỹ; không chỉ các nhà văn mới mà cả Rútxô và Môngtétxkiơ cũng bị cấm. Vậy phải làm gì? Người quyết định ra đi. Người An Nam bị trói buộc như nông nô, không được đi xa, đến đi lại trong nước cũng bị ngăn trở. Người tìm đường ra bờ biển và rời đất nước.\n\nTheo bài báo, khi ấy Người mười chín tuổi. Con số này không khớp với tư liệu gốc: Người sinh năm 1890 và rời bến Nhà Rồng ngày 5/6/1911, tức đã hai mươi mốt tuổi. Sai lệch nhỏ như vậy thường gặp trong một bài phỏng vấn, nên các nhà nghiên cứu luôn đối chiếu nhiều nguồn. Khi Người nhắc tới cảnh bầu cử ở Pháp, các chính khách tư sản bôi nhọ lẫn nhau, Manđenxtam thấy một cái rùng mình ghê sợ lướt qua gương mặt Người, và giọng nói trầm đục bỗng bừng sáng.","doc":7},{"loai":"anh","src":"textures/bang_w/G08_4_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nguyễn Ái Quốc ở Liên Xô, 1923”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Rượu ép và hai chữ \"bônsêvích\"","text":"Từ chuyện đời mình, Người chuyển sang nỗi khổ của quê hương. Người kể: người An Nam lấy gạo ngon nấu rượu ngon, để dùng khi bạn bè tới chơi hay trong ngày giỗ tổ tiên. Người Pháp lấy gạo xấu, rẻ tiền, nấu rượu hàng thùng mà chẳng ai muốn mua. Thế là các quan cai trị được lệnh bổ rượu theo số dân, bắt dân phải mua. Hai năm sau, trong tác phẩm Bản án chế độ thực dân Pháp in ở Paris năm 1925, Người còn dành hẳn một chương tố cáo việc đầu độc người bản xứ bằng rượu và thuốc phiện.\n\nNgười còn kể một nghịch lý: chính quyền Pháp đã dạy nông dân An Nam biết hai chữ bônsêvích và Lênin. Họ truy lùng những người cộng sản khi ở An Nam chưa hề có ai, và thế là vô tình làm tuyên truyền.","doc":8},{"loai":"doan","tieu_de":"Một nền văn hóa tương lai","text":"Nghe những câu chuyện ấy, Manđenxtam hình dung cảnh người ta chuốc rượu cho một dân tộc hiền hòa, ưa sự tế nhị và chừng mực, ghét mọi thứ thái quá. Ông viết rằng toàn bộ dáng vẻ của Nguyễn Ái Quốc toát lên sự tế nhị và lịch thiệp bẩm sinh. Rồi ông đặt hai hình ảnh cạnh nhau. Một bên là thứ văn minh châu Âu mà ông thấy đang vận hành bằng lưỡi lê và rượu, giấu chúng dưới áo chùng của giáo sĩ. Bên kia là con người đang ngồi trước mặt ông. Nhà thơ không viết về một chính khách, mà về một phong thái, bằng cái nhìn tinh ý với từng cử chỉ, từng âm sắc. Từ sự đối lập ấy ra đời câu văn nổi tiếng nhất của bài báo. Câu văn được viết bởi một người không thể biết người đối diện rồi sẽ trở thành ai, nên nó mang giá trị của một lời chứng khách quan.","doc":9},{"loai":"trich","text":"Từ Nguyễn Ái Quốc đã toả ra một thứ văn hoá, không phải văn hoá châu Âu, mà có lẽ là một nền văn hoá tương lai.","nguoi":"Ôxíp Manđenxtam","nguon_ten":"\"Thăm một chiến sĩ Quốc tế Cộng sản – Nguyễn Ái Quốc\", tạp chí Ogoniok, số 39, 23/12/1923 (bản dịch tiếng Việt)","doc":10},{"loai":"doan","tieu_de":"\"Hãy nói cả về ông ấy nữa\"","text":"Cuối bài, câu chuyện quay về công việc hằng ngày. Người kể về tờ Le Paria ở Paris: năm, sáu đồng chí từ các thuộc địa của Pháp cùng làm một tờ báo nhỏ, mỗi người tự bỏ tiền túi góp in báo thay vì nhận nhuận bút. Ông viết rằng trong phong thái cao quý và giọng nói trầm đục của Nguyễn Ái Quốc, người ta như nghe thấy ngày mai, nghe thấy sự tĩnh lặng mênh mông như đại dương của tình anh em toàn thế giới.\n\nTrên bàn của Người có một bản thảo, một bản báo cáo điềm tĩnh, viết theo lối điện tín của phóng viên. Người còn nhờ nhà thơ nhắc tới một cuộc nổi dậy khác do vua Duy Tân đứng đầu, chống việc bắt nông dân An Nam sang làm bia đỡ đạn cho Pháp. Người dặn: hãy nói cả về ông ấy nữa. Bài báo ghi rằng nhà vua đã trốn thoát, sống lưu vong. Thực ra, sau khi cuộc khởi nghĩa năm 1916 thất bại, vua Duy Tân bị bắt và bị đày sang đảo Rêuyniông.","doc":11},{"loai":"anh","src":"textures/bang_w/G08_4_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nguyễn Ái Quốc ở Liên Xô, 1923”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Số phận người viết","text":"Số phận người viết về sau rất bi thương. Tháng 11/1933, ông viết một bài thơ châm biếm Xtalin. Tháng 5/1934, ông bị bắt và bị đày tới Tréchđưn, rồi Vôrônegiơ. Tháng 5/1938, ông bị bắt lần thứ hai và mất ngày 27/12/1938 tại một trại trung chuyển gần Vlađivốtxtốc. Cũng năm ấy, Nguyễn Ái Quốc rời Mátxcơva sau bốn năm học tập giữa bầu không khí nặng nề của những cuộc thanh trừng (xem chuyên đề Đồng chí Lin ở Mátxcơva, 1934 – 1938).\n\nNhiều bài thơ của Manđenxtam còn lại được là nhờ người vợ, bà Nađêgiđa Manđenxtam, học thuộc lòng và gìn giữ suốt nhiều năm. Ông được phục hồi danh dự sau khi mất, năm 1956 và năm 1987, và nay được coi là một trong những nhà thơ lớn nhất của văn học Nga thế kỷ XX. Những dòng ông viết năm 1923 vì thế càng đáng quý: đó là lời chứng của một ngòi bút tinh tế.","doc":12},{"loai":"ban_co_biet","text":"Năm 1987, Đại hội đồng UNESCO khóa 24 thông qua nghị quyết kỷ niệm 100 năm ngày sinh Chủ tịch Hồ Chí Minh. Nghị quyết ghi nhận Người là Anh hùng giải phóng dân tộc và nhà văn hóa kiệt xuất của Việt Nam, sáu mươi tư năm sau lời tiên cảm của Manđenxtam.","nguon_ten":"Nghị quyết 24C/18.65 của Đại hội đồng UNESCO, khóa 24, năm 1987","doc":13},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Hôm nay, tấm ảnh Nguyễn Ái Quốc năm 1923 thuộc phạm vi công cộng và được giới thiệu trong nhiều ấn phẩm về những năm Người ở Liên Xô. Nguyên văn tiếng Nga của bài phỏng vấn được in lại trong các tuyển tập văn xuôi của Manđenxtam. Ở Việt Nam, cụm từ \"một nền văn hóa tương lai\" đã trở thành nhan đề của không ít bài báo và bài nghiên cứu.\n\nTrong gian trưng bày này, tấm ảnh được đặt cạnh không gian phục dựng Quảng trường Đỏ mùa đông năm 1924. Người xem có thể nhìn gương mặt người thanh niên ba mươi ba tuổi, rồi đọc lại những dòng Manđenxtam viết về giọng nói trầm đục, về hai chữ \"anh em\" Người hay nhắc. Một của ống kính, một của ngòi bút, tấm ảnh và trang báo cùng giữ lại cho chúng ta năm 1923 ấy.","doc":14}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","O. Manđenxtam, \"Thăm một chiến sĩ Quốc tế Cộng sản – Nguyễn Ái Quốc\", tạp chí Ogoniok, số 39, 23/12/1923; nguyên văn tiếng Nga: https://mandelshtam.lit-info.ru/mandelshtam/public/nyuen-aj-kak.htm","Nghị quyết 24C/18.65 của Đại hội đồng UNESCO, khóa 24, năm 1987","Bách khoa toàn thư Britannica, mục Osip Mandelstam","Bảo tàng Hồ Chí Minh"],"doc":[{"t":"Người thanh niên mặc áo len đan: Nguyễn Ái Quốc năm 1923 qua tấm ảnh và trang báo của Manđenxtam. Một ngày cuối năm 1923 ở Mátxcơva, nhà thơ Nga Ôxíp Manđenxtam ngồi trước người mà ông gọi là người An Nam duy nhất của thành phố, và mở đầu bằng một câu hỏi về Gandhi. Cuộc trò chuyện ấy thành một bài báo mà gần một thế kỷ sau người Việt Nam vẫn còn trích dẫn. Tấm ảnh chụp cùng năm cho ta thấy gương mặt Nguyễn Ái Quốc; trang báo của nhà thơ cho ta nghe giọng nói của Người."},{"t":"Một câu hỏi về Gandhi. Bài báo mở đầu bằng một câu hỏi, không cần lời giới thiệu. Nhà thơ hỏi người đối diện: phong trào của Gandhi ở Ấn Độ có vọng tới Đông Dương không, có con sóng hay tiếng dội nào dạt tới đó chưa? Người thanh niên châu Á đáp là không. Theo lời Người, nông dân An Nam đang sống chìm trong một đêm tối dày đặc, không báo chí, không hề biết thế giới bên ngoài ra sao. Người nhắc lại: đêm, một đêm thật sự. Người hỏi là Ôxíp Manđenxtam, sinh năm 1891, một gương mặt chính của phái thơ Acmê ở Nga, tác giả các tập thơ Đá và Tristia. Những năm ấy ông sống ở Mátxcơva, viết báo và dịch sách để kiếm sống. Cuộc trò chuyện được in trên tạp chí Ogoniok (Ngọn lửa nhỏ), số 39, ngày 23/12/1923. Ở Việt Nam, bài báo quen thuộc với nhan đề \"Thăm một chiến sĩ Quốc tế Cộng sản – Nguyễn Ái Quốc\". Đó là bức chân dung bằng chữ hiếm hoi về Người trong năm đầu ở nước Nga, do chính người ngồi trò chuyện với Người viết ra."},{"t":"Người trong ảnh. Tấm ảnh ở bảng này được chụp tại nước Nga Xô-viết năm 1923, không rõ người chụp. Người trong ảnh vừa bước sang tuổi ba mươi ba. Ngày 13/6/1923, Người lặng lẽ rời Paris; ngày 30/6, Người tới Petrograd rồi về Mátxcơva làm việc với Quốc tế Cộng sản (xem chuyên đề Chuyến đi bí mật từ Paris tới Petrograd). Sau lưng Người là mười hai năm bôn ba kể từ ngày rời bến Nhà Rồng năm 1911: làm phụ bếp trên tàu biển, rồi sống bằng nghề sửa ảnh ở Paris. Năm 1919, bản Yêu sách của nhân dân An Nam gửi Hội nghị Véc-xây mang chữ ký Nguyễn Ái Quốc; từ năm 1922, Người làm chủ bút tờ Le Paria (Người cùng khổ). Một tấm ảnh chỉ giữ lại gương mặt trong một khoảnh khắc. Nó không ghi được giọng nói, cách chọn chữ, hay lúc gương mặt bỗng sáng lên khi nói về quê hương. Những điều ấy, thật may, lại được nhà thơ chép lại ngay trong năm 1923."},{"t":"\"Gần như một cậu bé, mặc áo len đan\". Manđenxtam gọi người đối diện là người An Nam duy nhất ở Mátxcơva. Ông tả Người gần như còn là một cậu bé, gầy và mềm mại, mặc chiếc áo khoác len đan. Người nói bằng tiếng Pháp, thứ tiếng của những kẻ áp bức. Nhưng theo nhà thơ, những chữ Pháp ấy vang lên đục và trầm, như tiếng một quả chuông bị nén lại, quả chuông của tiếng mẹ đẻ. Nhà thơ còn ghi rằng Người đã đi gần khắp thế giới thuộc địa, từng tới Bắc Phi và Trung Phi. Trong câu chuyện, Người hay nói hai chữ \"anh em\". Anh em, đó là những người da đen, người Ấn Độ, người Xyri, người Trung Quốc. Người kể đã viết thư cho nhà văn René Maran, tác giả tiểu thuyết Batouala đoạt giải Goncourt năm 1921, hỏi thẳng rằng ông có muốn góp sức giải phóng những người anh em thuộc địa hay không. Theo bài báo, Maran trả lời dè dặt và né tránh."},{"t":"Bạn có biết? Manđenxtam tả Nguyễn Ái Quốc \"gần như còn là một cậu bé\", nhưng thật ra nhà thơ còn kém Người gần tám tháng tuổi: Nguyễn Ái Quốc sinh ngày 19/5/1890, còn Manđenxtam sinh ngày 15/1/1891. Khi gặp nhau cuối năm 1923, cả hai đều đã ngoài ba mươi."},{"t":"Ba chữ Pháp năm mười ba tuổi. Khi ấy, Người mới sống ở nước Nga chưa đầy sáu tháng, nhưng phần dài nhất của bài báo là lời Người tự kể về quê hương. Người nói mình xuất thân từ một gia đình An Nam thuộc tầng lớp trên, nơi các chàng trai theo học đạo Khổng. Người giải thích cho nhà thơ Nga rằng đạo Khổng không hẳn là một tôn giáo, mà đúng hơn là môn học về kinh nghiệm đạo đức và phép ứng xử, đặt nền trên sự hòa thuận trong xã hội. Lời kể ấy khớp với những gì sử liệu cho biết: thân phụ Người, cụ Nguyễn Sinh Sắc, là một nhà nho đỗ Phó bảng năm 1901, và tuổi thơ của Người gắn với sách thánh hiền ở làng Sen và ở Huế. Rồi Người kể về khoảnh khắc đã đổi hướng cả cuộc đời mình, bằng những câu về sau được dịch ra tiếng Việt và trích dẫn rất nhiều lần."},{"t":"Vào trạc tuổi mười ba, lần đầu tiên tôi được nghe ba chữ Pháp: Tự do, Bình đẳng, Bác ái. Đối với chúng tôi, người da trắng nào cũng là người Pháp. Thế là tôi muốn làm quen với nền văn minh Pháp, muốn tìm xem những gì ẩn đằng sau những chữ ấy. — Nguyễn Ái Quốc, trả lời nhà thơ Ôxíp Manđenxtam"},{"t":"Rời quê năm mười chín tuổi?. Người kể tiếp: ở các trường dành cho người bản xứ, người Pháp chỉ đào tạo ra những con vẹt. Sách báo bị giấu kỹ; không chỉ các nhà văn mới mà cả Rútxô và Môngtétxkiơ cũng bị cấm. Vậy phải làm gì? Người quyết định ra đi. Người An Nam bị trói buộc như nông nô, không được đi xa, đến đi lại trong nước cũng bị ngăn trở. Người tìm đường ra bờ biển và rời đất nước. Theo bài báo, khi ấy Người mười chín tuổi. Con số này không khớp với tư liệu gốc: Người sinh năm 1890 và rời bến Nhà Rồng ngày 5/6/1911, tức đã hai mươi mốt tuổi. Sai lệch nhỏ như vậy thường gặp trong một bài phỏng vấn, nên các nhà nghiên cứu luôn đối chiếu nhiều nguồn. Khi Người nhắc tới cảnh bầu cử ở Pháp, các chính khách tư sản bôi nhọ lẫn nhau, Manđenxtam thấy một cái rùng mình ghê sợ lướt qua gương mặt Người, và giọng nói trầm đục bỗng bừng sáng."},{"t":"Rượu ép và hai chữ \"bônsêvích\". Từ chuyện đời mình, Người chuyển sang nỗi khổ của quê hương. Người kể: người An Nam lấy gạo ngon nấu rượu ngon, để dùng khi bạn bè tới chơi hay trong ngày giỗ tổ tiên. Người Pháp lấy gạo xấu, rẻ tiền, nấu rượu hàng thùng mà chẳng ai muốn mua. Thế là các quan cai trị được lệnh bổ rượu theo số dân, bắt dân phải mua. Hai năm sau, trong tác phẩm Bản án chế độ thực dân Pháp in ở Paris năm 1925, Người còn dành hẳn một chương tố cáo việc đầu độc người bản xứ bằng rượu và thuốc phiện. Người còn kể một nghịch lý: chính quyền Pháp đã dạy nông dân An Nam biết hai chữ bônsêvích và Lênin. Họ truy lùng những người cộng sản khi ở An Nam chưa hề có ai, và thế là vô tình làm tuyên truyền."},{"t":"Một nền văn hóa tương lai. Nghe những câu chuyện ấy, Manđenxtam hình dung cảnh người ta chuốc rượu cho một dân tộc hiền hòa, ưa sự tế nhị và chừng mực, ghét mọi thứ thái quá. Ông viết rằng toàn bộ dáng vẻ của Nguyễn Ái Quốc toát lên sự tế nhị và lịch thiệp bẩm sinh. Rồi ông đặt hai hình ảnh cạnh nhau. Một bên là thứ văn minh châu Âu mà ông thấy đang vận hành bằng lưỡi lê và rượu, giấu chúng dưới áo chùng của giáo sĩ. Bên kia là con người đang ngồi trước mặt ông. Nhà thơ không viết về một chính khách, mà về một phong thái, bằng cái nhìn tinh ý với từng cử chỉ, từng âm sắc. Từ sự đối lập ấy ra đời câu văn nổi tiếng nhất của bài báo. Câu văn được viết bởi một người không thể biết người đối diện rồi sẽ trở thành ai, nên nó mang giá trị của một lời chứng khách quan."},{"t":"Từ Nguyễn Ái Quốc đã toả ra một thứ văn hoá, không phải văn hoá châu Âu, mà có lẽ là một nền văn hoá tương lai. — Ôxíp Manđenxtam"},{"t":"\"Hãy nói cả về ông ấy nữa\". Cuối bài, câu chuyện quay về công việc hằng ngày. Người kể về tờ Le Paria ở Paris: năm, sáu đồng chí từ các thuộc địa của Pháp cùng làm một tờ báo nhỏ, mỗi người tự bỏ tiền túi góp in báo thay vì nhận nhuận bút. Ông viết rằng trong phong thái cao quý và giọng nói trầm đục của Nguyễn Ái Quốc, người ta như nghe thấy ngày mai, nghe thấy sự tĩnh lặng mênh mông như đại dương của tình anh em toàn thế giới. Trên bàn của Người có một bản thảo, một bản báo cáo điềm tĩnh, viết theo lối điện tín của phóng viên. Người còn nhờ nhà thơ nhắc tới một cuộc nổi dậy khác do vua Duy Tân đứng đầu, chống việc bắt nông dân An Nam sang làm bia đỡ đạn cho Pháp. Người dặn: hãy nói cả về ông ấy nữa. Bài báo ghi rằng nhà vua đã trốn thoát, sống lưu vong. Thực ra, sau khi cuộc khởi nghĩa năm 1916 thất bại, vua Duy Tân bị bắt và bị đày sang đảo Rêuyniông."},{"t":"Số phận người viết. Số phận người viết về sau rất bi thương. Tháng 11/1933, ông viết một bài thơ châm biếm Xtalin. Tháng 5/1934, ông bị bắt và bị đày tới Tréchđưn, rồi Vôrônegiơ. Tháng 5/1938, ông bị bắt lần thứ hai và mất ngày 27/12/1938 tại một trại trung chuyển gần Vlađivốtxtốc. Cũng năm ấy, Nguyễn Ái Quốc rời Mátxcơva sau bốn năm học tập giữa bầu không khí nặng nề của những cuộc thanh trừng (xem chuyên đề Đồng chí Lin ở Mátxcơva, 1934 – 1938). Nhiều bài thơ của Manđenxtam còn lại được là nhờ người vợ, bà Nađêgiđa Manđenxtam, học thuộc lòng và gìn giữ suốt nhiều năm. Ông được phục hồi danh dự sau khi mất, năm 1956 và năm 1987, và nay được coi là một trong những nhà thơ lớn nhất của văn học Nga thế kỷ XX. Những dòng ông viết năm 1923 vì thế càng đáng quý: đó là lời chứng của một ngòi bút tinh tế."},{"t":"Bạn có biết? Năm 1987, Đại hội đồng UNESCO khóa 24 thông qua nghị quyết kỷ niệm 100 năm ngày sinh Chủ tịch Hồ Chí Minh. Nghị quyết ghi nhận Người là Anh hùng giải phóng dân tộc và nhà văn hóa kiệt xuất của Việt Nam, sáu mươi tư năm sau lời tiên cảm của Manđenxtam."},{"t":"Dấu tích hôm nay. Hôm nay, tấm ảnh Nguyễn Ái Quốc năm 1923 thuộc phạm vi công cộng và được giới thiệu trong nhiều ấn phẩm về những năm Người ở Liên Xô. Nguyên văn tiếng Nga của bài phỏng vấn được in lại trong các tuyển tập văn xuôi của Manđenxtam. Ở Việt Nam, cụm từ \"một nền văn hóa tương lai\" đã trở thành nhan đề của không ít bài báo và bài nghiên cứu. Trong gian trưng bày này, tấm ảnh được đặt cạnh không gian phục dựng Quảng trường Đỏ mùa đông năm 1924. Người xem có thể nhìn gương mặt người thanh niên ba mươi ba tuổi, rồi đọc lại những dòng Manđenxtam viết về giọng nói trầm đục, về hai chữ \"anh em\" Người hay nhắc. Một của ống kính, một của ngòi bút, tấm ảnh và trang báo cùng giữ lại cho chúng ta năm 1923 ấy."}],"so_chu":1952},{"i":5,"tieu_de_bang":"Thị thực số 1829 mang tên Chen Vang","tieu_de":"Tờ thị thực số 1829: cánh cửa sang nước Nga mở ra cho một cái tên giả","sapo":"Một tờ giấy đề ngày 16/6/1923 tại Berlin cho phép một người tên Chen Vang nhập cảnh nước Nga. Chẳng ai để ý tới cái tên xa lạ ấy. Người cầm tờ giấy chính là Nguyễn Ái Quốc, ba ngày trước còn ở Paris dưới con mắt theo dõi của mật thám Pháp. Vì sao lại là Berlin, và vì sao lại là một cái tên nghe như tên người Hoa?","bia":{"src":"textures/ht/ht_anh_visa_for_entry_into_russia_no_1829_on_june_16_19.jpg","credit":"Ảnh: The representative of the Union of Sovie · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Một văn bản rất ngắn","text":"Trong kho tư liệu về những năm Nguyễn Ái Quốc ở Liên Xô có một văn bản hành chính rất ngắn: thị thực nhập cảnh Nga số 1829, do cơ quan đại diện của Liên Xô tại Berlin cấp ngày 16/6/1923. Người được phép nhập cảnh mang tên Chen Vang. Với một nhân viên cửa khẩu năm ấy, đó chỉ là một cái tên châu Á giữa rất nhiều giấy tờ đi lại. Nhưng với lịch sử, tờ giấy này là một mắt xích quý. Nó ghi lại, bằng số hiệu và ngày tháng cụ thể, một chuyến đi mà người trong cuộc đã cố ý để lại ít dấu vết nhất.\n\nChỉ ba ngày trước đó, ngày 13/6/1923, Nguyễn Ái Quốc còn ở Paris. Theo Biên niên tiểu sử, Người đã cố ý giữ một nếp sinh hoạt đều đặn để đánh lạc hướng những kẻ theo dõi, rồi bí mật lên xe lửa sang Đức (xem chuyên đề Chuyến đi bí mật từ Paris tới Petrograd). Tờ thị thực đề ngày 16/6 cho thấy chỉ trong ba ngày ấy, Người đã tới Berlin và có trong tay giấy tờ để đi tiếp về phương Đông.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_visa_for_entry_into_russia_no_1829_on_june_16_19.jpg","chu_thich":"Thị thực nhập cảnh Nga số 1829 ngày 16/6/1923, cấp cho Nguyễn Ái Quốc dưới tên Chen Vang.","credit":"Ảnh: The representative of the Union of Sovie · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Vì sao là Berlin mà không phải Paris?","text":"Câu hỏi đầu tiên mà tờ giấy gợi ra là: vì sao nơi cấp lại là Berlin? Câu trả lời nằm ở quan hệ quốc tế của nhà nước Xô-viết lúc bấy giờ. Năm 1923, nước Pháp chưa công nhận chính quyền Xô-viết. Ở Paris không có một sứ quán hay cơ quan đại diện chính thức nào của Liên Xô để xin thị thực. Nước Đức thì khác. Ngày 16/4/1922, tại Rapallo, một thị trấn ven biển nước Ý, Đức và nước Nga Xô-viết ký hiệp ước lập lại quan hệ ngoại giao, cùng từ bỏ các đòi hỏi bồi thường chiến tranh của nhau. Đức trở thành cường quốc châu Âu đầu tiên chính thức công nhận nhà nước Xô-viết.\n\nTừ đó, Berlin là một ngả đường thuận tiện để từ Tây Âu sang nước Nga. Cơ quan đại diện toàn quyền của Liên Xô đặt trên đại lộ Unter den Linden, giữa trung tâm thủ đô nước Đức. Rời Paris sang Berlin, Nguyễn Ái Quốc vừa ra khỏi lãnh thổ nơi mật thám Pháp có nhiều quyền lực nhất, vừa tìm tới đúng nơi có thể cấp cho Người tấm giấy thông hành sang nước Nga.","doc":2},{"loai":"ban_co_biet","text":"Pháp chỉ chính thức công nhận Liên Xô vào ngày 28/10/1924, dưới chính phủ của Thủ tướng Édouard Herriot. Khi ấy, Nguyễn Ái Quốc đã sống ở Mátxcơva hơn một năm và sắp lên đường đi Quảng Châu.","nguon_ten":"Bách khoa toàn thư Britannica, mục Édouard Herriot; Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","doc":3},{"loai":"doan","tieu_de":"Nước Đức mùa hè năm 1923","text":"Nước Đức mà Nguyễn Ái Quốc đi qua đang ở giữa một năm đầy biến động. Từ tháng 1/1923, quân đội Pháp và Bỉ chiếm đóng vùng công nghiệp Ruhr vì Đức chậm trả tiền bồi thường chiến tranh. Chính phủ Đức kêu gọi dân chúng kháng cự thụ động, và đồng mác rơi vào một cơn siêu lạm phát hiếm thấy trong lịch sử. Giá cả thay đổi từng ngày. Đến tháng 11/1923, một đô-la Mỹ đổi được khoảng 4.200 tỉ mác, người ta phải mang cả chồng tiền giấy đi mua bánh mì.\n\nThật trớ trêu, người thanh niên thuộc địa đang lánh khỏi sự theo dõi của mật thám Pháp lại đi ngang một đất nước mà quân đội Pháp đang chiếm đóng một phần lãnh thổ. Trong khung cảnh ấy, việc làm giấy tờ của Người diễn ra nhanh gọn. Theo Biên niên tiểu sử, sau tờ thị thực số 1829, ngày 18/6/1923 Người được cảnh sát Đức cho phép quá cảnh, và ngày 25/6 Người được cấp thêm một thị thực nữa. Cuối tháng 6, mọi thủ tục đã xong, Người rời Berlin ra biển.","doc":4},{"loai":"anh","src":"textures/bang_w/G08_5_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Thị thực số 1829 mang tên Chen Vang”, nhìn từ xa."},{"loai":"doan","tieu_de":"Chen Vang: một cái tên để tạm biến mất","text":"Cái tên trên tờ giấy là chi tiết đáng chú ý nhất. Chen là cách viết theo chữ Latinh của một họ rất phổ biến ở Trung Quốc, tức họ Trần. Ở châu Âu sau Chiến tranh thế giới thứ nhất, người Hoa không hiếm. Hàng chục nghìn lao động Trung Quốc từng được tuyển sang Pháp làm việc phía sau mặt trận, và nhiều thanh niên Trung Quốc sang Pháp theo phong trào vừa làm vừa học. Một người châu Á mang tên Hoa đi qua các cửa khẩu vì thế ít gây chú ý.\n\nNgược lại, cái tên Nguyễn Ái Quốc khi ấy đã quá quen thuộc với chính quyền Pháp. Từ bản Yêu sách của nhân dân An Nam gửi Hội nghị Véc-xây năm 1919, cái tên ấy xuất hiện trên báo chí Paris, trong các báo cáo của mật thám và trên bàn làm việc của Bộ Thuộc địa. Chỉ cần tên thật hiện ra trên một hồ sơ đi lại, chuyến đi rất dễ bị lộ và bị ngăn cản. Chen Vang vì thế là cách để Người tạm biến mất, không phải để trốn chạy, mà để đến được nơi Người muốn học và muốn cất lên tiếng nói của các dân tộc thuộc địa.","doc":5},{"loai":"doan","tieu_de":"Người của nhiều cái tên","text":"Chen Vang chỉ là một trong rất nhiều tên gọi của Người. Sinh ra với tên Nguyễn Sinh Cung, lớn lên mang tên Nguyễn Tất Thành, ngày 5/6/1911 Người rời bến Nhà Rồng trên tàu Amiral Latouche-Tréville với tên Văn Ba. Năm 1919, bản Yêu sách gửi Hội nghị Véc-xây ký tên Nguyễn Ái Quấc, rồi cái tên Nguyễn Ái Quốc trở thành nỗi ám ảnh của mật thám Pháp. Sau chặng Liên Xô lần thứ nhất, ở Quảng Châu Người là Lý Thụy. Ở Xiêm, bà con Việt kiều gọi Người là Thầu Chín. Bị bắt ở Hồng Kông năm 1931, Người mang tên Tống Văn Sơ.\n\nTrở lại Mátxcơva những năm 1934 – 1938, Người là đồng chí Lin. Lên đường về Trung Quốc, Người khoác áo Bát lộ quân với tên Hồ Quang. Từ tháng 8/1942, cái tên Hồ Chí Minh xuất hiện và gắn bó với Người đến trọn đời. Các nhà nghiên cứu đã thống kê được hơn một trăm tên gọi, bí danh và bút danh của Người. Mỗi cái tên gắn với một chặng đường, một nhiệm vụ, một lớp vỏ cần thiết để đi qua vòng vây của mật thám nhiều nước. Tờ thị thực số 1829 là văn bản đã giữ lại cái tên Chen Vang cho lịch sử.","doc":6},{"loai":"ban_co_biet","text":"Nhà nước Liên bang Cộng hòa xã hội chủ nghĩa Xô-viết chính thức thành lập ngày 30/12/1922. Tờ thị thực cấp cho Nguyễn Ái Quốc ra đời khi Liên Xô mới tồn tại chưa đầy sáu tháng.","nguon_ten":"Bách khoa toàn thư Britannica, mục Soviet Union","doc":7},{"loai":"doan","tieu_de":"Con tàu mang tên một người cộng sản Đức","text":"Theo Biên niên tiểu sử, cuối tháng 6/1923, Người xuống tàu Các Líp-nếch ở cảng Hamburg để sang Petrograd. Con tàu mang tên Karl Liebknecht, nhà cách mạng Đức sinh năm 1871. Tháng 12/1914, khi Chiến tranh thế giới thứ nhất đang lan rộng, ông là nghị sĩ duy nhất trong Quốc hội Đức bỏ phiếu chống ngân sách chiến tranh. Cùng với Rosa Luxemburg, ông lãnh đạo nhóm Spartacus và tham gia thành lập Đảng Cộng sản Đức. Ngày 15/1/1919, cả hai bị sát hại ở Berlin, trong những ngày cuộc khởi nghĩa tháng Giêng bị đàn áp.\n\nHơn bốn năm sau, một người thanh niên phương Đông mang tên giả rời nước Đức trên con tàu mang tên ông, vượt biển Baltic. Ngày 30/6/1923, con tàu cập Petrograd, thành phố của Cách mạng Tháng Mười. Ít ngày sau, Người lên xe lửa đi Mátxcơva. Đến đây, những tờ giấy mang tên Chen Vang đã làm xong nhiệm vụ của chúng. Ở Mátxcơva, Người hoạt động với cái tên Nguyễn Ái Quốc: ký tên dưới các bài báo, phát biểu tại các hội nghị và đại hội quốc tế.","doc":8},{"loai":"anh","src":"textures/bang_w/G08_5_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Thị thực số 1829 mang tên Chen Vang”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Mười bảy ngày trên giấy tờ","text":"Với người nghiên cứu, giá trị của tờ thị thực nằm ở chỗ nó ghép được với các tư liệu khác thành một lộ trình có ngày tháng rõ ràng. Ngày 13/6 rời Paris. Ngày 16/6 nhận thị thực số 1829 ở Berlin. Ngày 18/6 được phép quá cảnh nước Đức. Ngày 25/6 có thêm một thị thực. Cuối tháng 6 xuống tàu ở Hamburg. Ngày 30/6 tới Petrograd. Chỉ trong mười bảy ngày, người thanh niên bị theo dõi gắt gao ở Paris đã đi hết chặng đường từ Tây Âu tới nước Nga Xô-viết.\n\nTờ giấy cũng cho thấy chuyến đi được chuẩn bị chu đáo. Có tên giả, có giấy tờ hợp lệ của phía Xô-viết và phía Đức, Người đi qua các trạm kiểm soát mà không để lộ danh tính. Đó là kinh nghiệm hoạt động bí mật mà về sau Người còn dùng nhiều lần: khi sang Quảng Châu cuối năm 1924 với tên Lý Thụy, khi đi lại giữa Xiêm, Trung Quốc và châu Âu cuối những năm 1920, và khi tìm đường về nước, vượt cột mốc 108 ngày 28/1/1941.","doc":9},{"loai":"anh","src":"textures/bang_w/G08_5_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Thị thực số 1829 mang tên Chen Vang”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngày nay, hình chụp tờ thị thực số 1829 được công bố rộng rãi trong các ấn phẩm về những năm Nguyễn Ái Quốc ở Liên Xô. Tư liệu này cũng được đưa vào kho tư liệu mở Wikimedia Commons như một văn bản thuộc phạm vi công cộng. Tại Bảo tàng Hành trình 3D, tờ giấy được đặt trong không gian Petrograd và Mátxcơva, ngay trước những chặng đường mà nó đã mở ra: Quốc tế Cộng sản, Trường Đại học Phương Đông, mùa đông năm 1924 bên Quảng trường Đỏ.\n\nỞ Mátxcơva hôm nay, cái tên thật của người từng đi qua cửa khẩu dưới tên Chen Vang đã được khắc vào lòng thành phố. Năm 1990, nhân kỷ niệm 100 năm ngày sinh Chủ tịch Hồ Chí Minh, một tượng đài Người được khánh thành trên quảng trường mang tên Hồ Chí Minh ở thủ đô nước Nga. Từ một tờ giấy mang tên giả năm 1923 đến một quảng trường mang tên thật, đó là quãng đường gần bảy mươi năm. Tờ thị thực nhỏ bé vì thế không chỉ là thủ tục hành chính, mà là trang mở đầu của cả một câu chuyện gắn bó giữa Người với đất nước này.","doc":10}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 1 (1890 – 1929), NXB Chính trị quốc gia – các mục tháng 6/1923","Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch – Nguyễn Ái Quốc trên đất nước của Lênin (1923 – 1924): https://nhasanbacho.vn/bai-viet/nguyen-ai-quoc-tren-dat-nuoc-cua-lenin-1923-1924-222/","Bách khoa toàn thư Britannica – các mục Treaty of Rapallo (1922), Soviet Union, Karl Liebknecht, Édouard Herriot","Bảo tàng Hồ Chí Minh – tư liệu về thời kỳ Nguyễn Ái Quốc hoạt động ở Liên Xô"],"doc":[{"t":"Tờ thị thực số 1829: cánh cửa sang nước Nga mở ra cho một cái tên giả. Một tờ giấy đề ngày 16/6/1923 tại Berlin cho phép một người tên Chen Vang nhập cảnh nước Nga. Chẳng ai để ý tới cái tên xa lạ ấy. Người cầm tờ giấy chính là Nguyễn Ái Quốc, ba ngày trước còn ở Paris dưới con mắt theo dõi của mật thám Pháp. Vì sao lại là Berlin, và vì sao lại là một cái tên nghe như tên người Hoa?"},{"t":"Một văn bản rất ngắn. Trong kho tư liệu về những năm Nguyễn Ái Quốc ở Liên Xô có một văn bản hành chính rất ngắn: thị thực nhập cảnh Nga số 1829, do cơ quan đại diện của Liên Xô tại Berlin cấp ngày 16/6/1923. Người được phép nhập cảnh mang tên Chen Vang. Với một nhân viên cửa khẩu năm ấy, đó chỉ là một cái tên châu Á giữa rất nhiều giấy tờ đi lại. Nhưng với lịch sử, tờ giấy này là một mắt xích quý. Nó ghi lại, bằng số hiệu và ngày tháng cụ thể, một chuyến đi mà người trong cuộc đã cố ý để lại ít dấu vết nhất. Chỉ ba ngày trước đó, ngày 13/6/1923, Nguyễn Ái Quốc còn ở Paris. Theo Biên niên tiểu sử, Người đã cố ý giữ một nếp sinh hoạt đều đặn để đánh lạc hướng những kẻ theo dõi, rồi bí mật lên xe lửa sang Đức (xem chuyên đề Chuyến đi bí mật từ Paris tới Petrograd). Tờ thị thực đề ngày 16/6 cho thấy chỉ trong ba ngày ấy, Người đã tới Berlin và có trong tay giấy tờ để đi tiếp về phương Đông."},{"t":"Vì sao là Berlin mà không phải Paris?. Câu hỏi đầu tiên mà tờ giấy gợi ra là: vì sao nơi cấp lại là Berlin? Câu trả lời nằm ở quan hệ quốc tế của nhà nước Xô-viết lúc bấy giờ. Năm 1923, nước Pháp chưa công nhận chính quyền Xô-viết. Ở Paris không có một sứ quán hay cơ quan đại diện chính thức nào của Liên Xô để xin thị thực. Nước Đức thì khác. Ngày 16/4/1922, tại Rapallo, một thị trấn ven biển nước Ý, Đức và nước Nga Xô-viết ký hiệp ước lập lại quan hệ ngoại giao, cùng từ bỏ các đòi hỏi bồi thường chiến tranh của nhau. Đức trở thành cường quốc châu Âu đầu tiên chính thức công nhận nhà nước Xô-viết. Từ đó, Berlin là một ngả đường thuận tiện để từ Tây Âu sang nước Nga. Cơ quan đại diện toàn quyền của Liên Xô đặt trên đại lộ Unter den Linden, giữa trung tâm thủ đô nước Đức. Rời Paris sang Berlin, Nguyễn Ái Quốc vừa ra khỏi lãnh thổ nơi mật thám Pháp có nhiều quyền lực nhất, vừa tìm tới đúng nơi có thể cấp cho Người tấm giấy thông hành sang nước Nga."},{"t":"Bạn có biết? Pháp chỉ chính thức công nhận Liên Xô vào ngày 28/10/1924, dưới chính phủ của Thủ tướng Édouard Herriot. Khi ấy, Nguyễn Ái Quốc đã sống ở Mátxcơva hơn một năm và sắp lên đường đi Quảng Châu."},{"t":"Nước Đức mùa hè năm 1923. Nước Đức mà Nguyễn Ái Quốc đi qua đang ở giữa một năm đầy biến động. Từ tháng 1/1923, quân đội Pháp và Bỉ chiếm đóng vùng công nghiệp Ruhr vì Đức chậm trả tiền bồi thường chiến tranh. Chính phủ Đức kêu gọi dân chúng kháng cự thụ động, và đồng mác rơi vào một cơn siêu lạm phát hiếm thấy trong lịch sử. Giá cả thay đổi từng ngày. Đến tháng 11/1923, một đô-la Mỹ đổi được khoảng 4.200 tỉ mác, người ta phải mang cả chồng tiền giấy đi mua bánh mì. Thật trớ trêu, người thanh niên thuộc địa đang lánh khỏi sự theo dõi của mật thám Pháp lại đi ngang một đất nước mà quân đội Pháp đang chiếm đóng một phần lãnh thổ. Trong khung cảnh ấy, việc làm giấy tờ của Người diễn ra nhanh gọn. Theo Biên niên tiểu sử, sau tờ thị thực số 1829, ngày 18/6/1923 Người được cảnh sát Đức cho phép quá cảnh, và ngày 25/6 Người được cấp thêm một thị thực nữa. Cuối tháng 6, mọi thủ tục đã xong, Người rời Berlin ra biển."},{"t":"Chen Vang: một cái tên để tạm biến mất. Cái tên trên tờ giấy là chi tiết đáng chú ý nhất. Chen là cách viết theo chữ Latinh của một họ rất phổ biến ở Trung Quốc, tức họ Trần. Ở châu Âu sau Chiến tranh thế giới thứ nhất, người Hoa không hiếm. Hàng chục nghìn lao động Trung Quốc từng được tuyển sang Pháp làm việc phía sau mặt trận, và nhiều thanh niên Trung Quốc sang Pháp theo phong trào vừa làm vừa học. Một người châu Á mang tên Hoa đi qua các cửa khẩu vì thế ít gây chú ý. Ngược lại, cái tên Nguyễn Ái Quốc khi ấy đã quá quen thuộc với chính quyền Pháp. Từ bản Yêu sách của nhân dân An Nam gửi Hội nghị Véc-xây năm 1919, cái tên ấy xuất hiện trên báo chí Paris, trong các báo cáo của mật thám và trên bàn làm việc của Bộ Thuộc địa. Chỉ cần tên thật hiện ra trên một hồ sơ đi lại, chuyến đi rất dễ bị lộ và bị ngăn cản. Chen Vang vì thế là cách để Người tạm biến mất, không phải để trốn chạy, mà để đến được nơi Người muốn học và muốn cất lên tiếng nói của các dân tộc thuộc địa."},{"t":"Người của nhiều cái tên. Chen Vang chỉ là một trong rất nhiều tên gọi của Người. Sinh ra với tên Nguyễn Sinh Cung, lớn lên mang tên Nguyễn Tất Thành, ngày 5/6/1911 Người rời bến Nhà Rồng trên tàu Amiral Latouche-Tréville với tên Văn Ba. Năm 1919, bản Yêu sách gửi Hội nghị Véc-xây ký tên Nguyễn Ái Quấc, rồi cái tên Nguyễn Ái Quốc trở thành nỗi ám ảnh của mật thám Pháp. Sau chặng Liên Xô lần thứ nhất, ở Quảng Châu Người là Lý Thụy. Ở Xiêm, bà con Việt kiều gọi Người là Thầu Chín. Bị bắt ở Hồng Kông năm 1931, Người mang tên Tống Văn Sơ. Trở lại Mátxcơva những năm 1934 – 1938, Người là đồng chí Lin. Lên đường về Trung Quốc, Người khoác áo Bát lộ quân với tên Hồ Quang. Từ tháng 8/1942, cái tên Hồ Chí Minh xuất hiện và gắn bó với Người đến trọn đời. Các nhà nghiên cứu đã thống kê được hơn một trăm tên gọi, bí danh và bút danh của Người. Mỗi cái tên gắn với một chặng đường, một nhiệm vụ, một lớp vỏ cần thiết để đi qua vòng vây của mật thám nhiều nước. Tờ thị thực số 1829 là văn bản đã giữ lại cái tên Chen Vang cho lịch sử."},{"t":"Bạn có biết? Nhà nước Liên bang Cộng hòa xã hội chủ nghĩa Xô-viết chính thức thành lập ngày 30/12/1922. Tờ thị thực cấp cho Nguyễn Ái Quốc ra đời khi Liên Xô mới tồn tại chưa đầy sáu tháng."},{"t":"Con tàu mang tên một người cộng sản Đức. Theo Biên niên tiểu sử, cuối tháng 6/1923, Người xuống tàu Các Líp-nếch ở cảng Hamburg để sang Petrograd. Con tàu mang tên Karl Liebknecht, nhà cách mạng Đức sinh năm 1871. Tháng 12/1914, khi Chiến tranh thế giới thứ nhất đang lan rộng, ông là nghị sĩ duy nhất trong Quốc hội Đức bỏ phiếu chống ngân sách chiến tranh. Cùng với Rosa Luxemburg, ông lãnh đạo nhóm Spartacus và tham gia thành lập Đảng Cộng sản Đức. Ngày 15/1/1919, cả hai bị sát hại ở Berlin, trong những ngày cuộc khởi nghĩa tháng Giêng bị đàn áp. Hơn bốn năm sau, một người thanh niên phương Đông mang tên giả rời nước Đức trên con tàu mang tên ông, vượt biển Baltic. Ngày 30/6/1923, con tàu cập Petrograd, thành phố của Cách mạng Tháng Mười. Ít ngày sau, Người lên xe lửa đi Mátxcơva. Đến đây, những tờ giấy mang tên Chen Vang đã làm xong nhiệm vụ của chúng. Ở Mátxcơva, Người hoạt động với cái tên Nguyễn Ái Quốc: ký tên dưới các bài báo, phát biểu tại các hội nghị và đại hội quốc tế."},{"t":"Mười bảy ngày trên giấy tờ. Với người nghiên cứu, giá trị của tờ thị thực nằm ở chỗ nó ghép được với các tư liệu khác thành một lộ trình có ngày tháng rõ ràng. Ngày 13/6 rời Paris. Ngày 16/6 nhận thị thực số 1829 ở Berlin. Ngày 18/6 được phép quá cảnh nước Đức. Ngày 25/6 có thêm một thị thực. Cuối tháng 6 xuống tàu ở Hamburg. Ngày 30/6 tới Petrograd. Chỉ trong mười bảy ngày, người thanh niên bị theo dõi gắt gao ở Paris đã đi hết chặng đường từ Tây Âu tới nước Nga Xô-viết. Tờ giấy cũng cho thấy chuyến đi được chuẩn bị chu đáo. Có tên giả, có giấy tờ hợp lệ của phía Xô-viết và phía Đức, Người đi qua các trạm kiểm soát mà không để lộ danh tính. Đó là kinh nghiệm hoạt động bí mật mà về sau Người còn dùng nhiều lần: khi sang Quảng Châu cuối năm 1924 với tên Lý Thụy, khi đi lại giữa Xiêm, Trung Quốc và châu Âu cuối những năm 1920, và khi tìm đường về nước, vượt cột mốc 108 ngày 28/1/1941."},{"t":"Dấu tích hôm nay. Ngày nay, hình chụp tờ thị thực số 1829 được công bố rộng rãi trong các ấn phẩm về những năm Nguyễn Ái Quốc ở Liên Xô. Tư liệu này cũng được đưa vào kho tư liệu mở Wikimedia Commons như một văn bản thuộc phạm vi công cộng. Tại Bảo tàng Hành trình 3D, tờ giấy được đặt trong không gian Petrograd và Mátxcơva, ngay trước những chặng đường mà nó đã mở ra: Quốc tế Cộng sản, Trường Đại học Phương Đông, mùa đông năm 1924 bên Quảng trường Đỏ. Ở Mátxcơva hôm nay, cái tên thật của người từng đi qua cửa khẩu dưới tên Chen Vang đã được khắc vào lòng thành phố. Năm 1990, nhân kỷ niệm 100 năm ngày sinh Chủ tịch Hồ Chí Minh, một tượng đài Người được khánh thành trên quảng trường mang tên Hồ Chí Minh ở thủ đô nước Nga. Từ một tờ giấy mang tên giả năm 1923 đến một quảng trường mang tên thật, đó là quãng đường gần bảy mươi năm. Tờ thị thực nhỏ bé vì thế không chỉ là thủ tục hành chính, mà là trang mở đầu của cả một câu chuyện gắn bó giữa Người với đất nước này."}],"so_chu":1746},{"i":6,"tieu_de_bang":"Thẻ đại biểu tư vấn Đại hội V, 1924","tieu_de":"Tấm thẻ không có quyền biểu quyết: tiếng nói của các dân tộc thuộc địa ở Đại hội V","sapo":"Bốn ngày trước khi Đại hội V Quốc tế Cộng sản khai mạc, Nguyễn Ái Quốc viết thư xin một tấm thẻ dự đại hội. Tấm thẻ Người nhận được mang tư cách đại biểu tư vấn: được nói, nhưng không được bỏ phiếu. Người đã dùng trọn quyền được nói ấy, từ phiên khai mạc đến những phiên họp cuối, để kéo sự chú ý của cả đại hội về phía các thuộc địa.","bia":{"src":"textures/ht/ht_anh_advisory_delegate_card_issued_to_nguyen_ai_quoc_.jpg","credit":"Ảnh: 5th Congress of the Communist Internatio · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Lá thư ngày 13/6/1924","text":"Ngày 13/6/1924, từ Mátxcơva, Nguyễn Ái Quốc gửi thư cho Pêtơrốp, Chủ tịch Ban Phương Đông của Quốc tế Cộng sản, đề nghị được cấp thẻ dự Đại hội lần thứ V. Chỉ còn bốn ngày nữa là đại hội khai mạc. Lá thư ngắn ấy, được ghi lại trong Biên niên tiểu sử, cho thấy tấm thẻ trong ảnh không tự nhiên đến tay Người. Đó là một chỗ ngồi mà Người chủ động tìm kiếm, vì hiểu diễn đàn này quan trọng thế nào với các dân tộc thuộc địa.\n\nKhi ấy, Người đã sống ở Mátxcơva gần một năm. Ngày 14/4/1924, Người nhận quyết định làm cán bộ ngoài biên chế của Ban Phương Đông, với mức lương 60 rúp mỗi tháng. Đời sống chẳng dễ dàng gì. Trong một lá thư gửi Pêtơrốp hồi tháng 3, Người phàn nàn rằng phòng ở lúc nào cũng có bốn, năm người ở chung, ban đêm thì bị rệp cắn. Nhưng điều khiến Người bận lòng hơn cả là vấn đề thuộc địa vẫn chưa được quan tâm đúng mức trong phong trào cộng sản quốc tế.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_advisory_delegate_card_issued_to_nguyen_ai_quoc_.jpg","chu_thich":"Thẻ đại biểu tư vấn cấp cho Nguyễn Ái Quốc dự Đại hội V Quốc tế Cộng sản, 1924.","credit":"Ảnh: 5th Congress of the Communist Internatio · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Những lá thư trước đại hội","text":"Tấm thẻ đại biểu là kết quả của nhiều tháng kiên trì. Ngày 15/3/1924, Người viết thư cho Dinôviép, Chủ tịch Quốc tế Cộng sản, nhắc lại đề nghị được gặp để thảo luận về vấn đề thuộc địa của Pháp. Ngày 20/5, trong thư gửi Pêtơrốp, Người đề nghị lập một nhóm về châu Á, tổ chức trao đổi kinh nghiệm giữa những người hoạt động ở các nước phương Đông, và thành lập một Tiểu ban Phương Đông.\n\nNhững lá thư ấy cho thấy một người không ngồi chờ được giao việc. Người đọc, viết, đề xuất, rồi lại đề xuất. Trong mắt Người, Quốc tế Cộng sản là nơi có thể đem sức mạnh của phong trào thế giới đến với các dân tộc bị áp bức. Nhưng muốn vậy, trước hết phải làm cho những người lãnh đạo phong trào hiểu rằng thuộc địa không phải là chuyện bên lề. Đại hội V, nơi hội tụ đông đủ đại biểu các đảng cộng sản trên thế giới, chính là dịp tốt nhất để nói điều đó thành tiếng.","doc":2},{"loai":"doan","tieu_de":"“Đại biểu tư vấn” nghĩa là gì?","text":"Đại hội lần thứ V Quốc tế Cộng sản họp tại Mátxcơva từ ngày 17/6 đến 8/7/1924. Đại biểu dự đại hội chia làm hai loại. Đại biểu chính thức của các đảng thành viên có quyền biểu quyết, tức là được bỏ phiếu thông qua các nghị quyết. Đại biểu tư vấn được dự họp, được phát biểu, được góp ý kiến, nhưng không bỏ phiếu. Tấm thẻ cấp cho Nguyễn Ái Quốc thuộc loại thứ hai.\n\nLý do không khó hiểu. Năm 1924, Đông Dương chưa có đảng cộng sản. Phải sáu năm nữa, qua hội nghị hợp nhất họp từ ngày 6/1 đến 7/2/1930 tại Cửu Long, Hương Cảng, Đảng Cộng sản Việt Nam mới ra đời. Không có một đảng ở quê hương đứng sau lưng, người thanh niên Việt Nam chỉ có thể dự đại hội với tiếng nói tư vấn. Nhưng chính từ vị trí khiêm tốn ấy, Người vẫn có thể nói thẳng điều mình thấy về thân phận các dân tộc bị áp bức, trước những người đứng đầu phong trào cộng sản thế giới.","doc":3},{"loai":"ban_co_biet","text":"Tập san Inprekorr, tờ thông tin báo chí quốc tế của Quốc tế Cộng sản, ra bằng nhiều thứ tiếng. Bản tiếng Pháp mang tên La Correspondance internationale. Trong năm 1924, nhiều bài viết về Đông Dương của Nguyễn Ái Quốc được in trên bản tiếng Pháp này.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia; Hồ Chí Minh Toàn tập, tập 1, NXB Chính trị quốc gia","doc":4},{"loai":"anh","src":"textures/bang_w/G08_6_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Thẻ đại biểu tư vấn Đại hội V, 1924”, nhìn từ xa."},{"loai":"doan","tieu_de":"Câu hỏi trong phiên khai mạc","text":"Đại hội khai mạc vào buổi tối ngày 17/6/1924, trong Điện Kremli. Theo Biên niên tiểu sử, ngay tại phiên khai mạc, Nguyễn Ái Quốc đã lên tiếng. Người hỏi đại hội có gửi một lời kêu gọi đặc biệt tới các nước thuộc địa hay không, và đề nghị bổ sung vào lời kêu gọi của đại hội đối tượng “các dân tộc các nước thuộc địa”. Đề nghị ấy được chấp nhận.\n\nĐó là một chi tiết nhỏ, nhưng rất tiêu biểu cho cách làm việc của Người. Trong văn kiện của phong trào cộng sản thời ấy, người ta thường nói nhiều về giai cấp vô sản châu Âu, về công nhân các nước công nghiệp. Hàng trăm triệu con người ở châu Á, châu Phi, những người mà tờ Le Paria của Người gọi là “người cùng khổ”, rất dễ bị bỏ quên. Người muốn ngay từ buổi đầu, trong lời kêu gọi của đại hội, các dân tộc thuộc địa phải được gọi đích danh. Và Người đã làm được điều đó chỉ bằng một câu hỏi và một đề nghị ngắn gọn.","doc":5},{"loai":"doan","tieu_de":"Phiên họp thứ 8: con rắn và cái đuôi","text":"Ngày 23/6/1924, tại phiên họp thứ 8, Nguyễn Ái Quốc có bài phát biểu được nhắc tới nhiều nhất của mình ở đại hội. Người thẳng thắn phê bình các đảng cộng sản ở những nước có thuộc địa, trong đó có Đảng Cộng sản Pháp, là chưa quan tâm đúng mức tới phong trào giải phóng ở thuộc địa. Người nói rằng nghe các đồng chí ở chính quốc phát biểu, Người có cảm tưởng họ muốn đánh chết rắn đằng đuôi.\n\nHình ảnh ấy giản dị mà sắc sảo. Chủ nghĩa đế quốc được ví như một con rắn độc. Nếu nọc độc và sức sống của nó tập trung ở thuộc địa, thì chỉ đánh ở chính quốc chẳng khác nào đánh vào đuôi rắn: con rắn vẫn sống. Muốn đánh bại chủ nghĩa tư bản, phải tước đi thuộc địa của nó. Trong những lời phát biểu tại đại hội, Người khẳng định vận mệnh của giai cấp vô sản thế giới gắn chặt với vận mệnh của các dân tộc bị áp bức ở thuộc địa. Với một đại biểu chỉ có tiếng nói tư vấn, đó là những lời phê bình rất thẳng thắn.","doc":6},{"loai":"trich","text":"Tất cả các đồng chí đều biết rằng, hiện nay nọc độc và sức sống của con rắn độc tư bản chủ nghĩa đang tập trung ở các thuộc địa hơn là ở chính quốc.","nguoi":"Nguyễn Ái Quốc","nguon_ten":"Phát biểu tại phiên họp thứ 8 Đại hội V Quốc tế Cộng sản, 23/6/1924 – Hồ Chí Minh Toàn tập, tập 1, NXB Chính trị quốc gia","doc":7},{"loai":"doan","tieu_de":"Phiên thứ 22 và 25: từ phê bình đến đề nghị","text":"Một tuần sau, ngày 1/7/1924, tại phiên họp thứ 22, Người lại phát biểu. Lần này, Người phê bình các đảng cộng sản Pháp, Anh, Hà Lan là chưa có một chính sách tích cực về vấn đề thuộc địa. Đó là ba nước nắm trong tay những đế quốc thuộc địa rộng lớn bậc nhất thế giới. Nước Anh có Ấn Độ. Hà Lan có quần đảo Đông Ấn, nay là Inđônêxia. Pháp có Đông Dương cùng những vùng đất mênh mông ở Bắc Phi và Tây Phi. Theo Người, chính các đảng ở những nước ấy phải đi đầu trong việc ủng hộ phong trào giải phóng thuộc địa.\n\nHai ngày sau, ngày 3/7, tại phiên họp thứ 25, Người phát biểu về vấn đề ruộng đất và nạn đói ở các thuộc địa của Pháp. Người chỉ ra rằng nông dân bản xứ đông đảo và khốn khổ, nhưng thiếu tổ chức, thiếu người lãnh đạo, nên rất cần sự giúp đỡ của Quốc tế Cộng sản. Từ phê bình, Người đi tới đề nghị: Quốc tế Cộng sản cần có những biện pháp cụ thể để giúp đỡ phong trào ở các thuộc địa.","doc":8},{"loai":"anh","src":"textures/bang_w/G08_6_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Thẻ đại biểu tư vấn Đại hội V, 1924”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Lời nói được in thành chữ","text":"Những lời phát biểu của Nguyễn Ái Quốc không dừng lại trong hội trường. Ngày 4/7/1924, khi đại hội còn đang họp, tập san Inprekorr số 41 đăng lời phát biểu của Người. Nhờ đó, ý kiến của một đại biểu tư vấn đến từ Đông Dương đến được với những người cộng sản ở nhiều nước. Biên bản đại hội cũng ghi lại các bài phát biểu. Về sau, chúng được dịch ra tiếng Việt và in trong Hồ Chí Minh Toàn tập, tập 1.\n\nĐây cũng là quãng thời gian Người viết rất nhiều. Chỉ trong nửa đầu năm 1924, tập san Inprekorr đã đăng nhiều bài của Người về Đông Dương và chủ nghĩa thực dân Pháp: “Đông Dương và Thái Bình Dương” tháng 3, “Chủ nghĩa đế quốc Pháp dám làm những gì?” tháng 4, “Sự phá sản của chế độ thực dân Pháp” tháng 5. Bài “Những cái tốt đẹp của nền văn minh Pháp” ra đúng ngày đại hội khai mạc, 17/6/1924. Trên mặt báo cũng như ở diễn đàn, Người theo đuổi cùng một mục tiêu: để thế giới biết các dân tộc thuộc địa đang phải chịu đựng những gì.","doc":9},{"loai":"doan","tieu_de":"Từ Mátxcơva về phương Đông","text":"Đại hội bế mạc ngày 8/7/1924. Suốt mùa hè năm ấy, Người còn dự nhiều đại hội quốc tế khác ở Mátxcơva (xem chuyên đề Các đại biểu Đại hội V Quốc tế Cộng sản, 1924). Nhưng mong muốn lớn nhất của Người là trở về gần Tổ quốc. Ngay từ ngày 11/4/1924, Người đã gửi Ban Chấp hành Quốc tế Cộng sản kế hoạch đi Trung Quốc qua ngả Viễn Đông. Trả lời phỏng vấn Giôvanni Giécmanéttô cho báo L'Unità của Ý hồi tháng 3, khi được hỏi sẽ làm gì sau khi học xong, Người nói sẽ trở về Tổ quốc để đấu tranh.\n\nCuối năm 1924, đề nghị ấy được chấp thuận. Người rời Mátxcơva, và ngày 11/11/1924 tới Quảng Châu. Ở đó, Người tập hợp những thanh niên Việt Nam yêu nước đầu tiên, mở lớp huấn luyện, và tháng 6/1925 lập Hội Việt Nam Cách mạng Thanh niên. Những điều Người nói ở Đại hội V, rằng nông dân thuộc địa thiếu tổ chức và thiếu người lãnh đạo, giờ được chính Người bắt tay giải quyết, ngay sát biên giới quê hương.","doc":10},{"loai":"ban_co_biet","text":"Báo L'Unità, nơi đăng cuộc phỏng vấn Nguyễn Ái Quốc, ra số đầu tiên ngày 12/2/1924 do nhà lý luận cộng sản Ý Antonio Gramsci sáng lập. Khi phỏng vấn Người, tờ báo mới ra đời được khoảng một tháng.","nguon_ten":"Bách khoa toàn thư Britannica, mục Antonio Gramsci; Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia","doc":11},{"loai":"anh","src":"textures/bang_w/G08_6_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Thẻ đại biểu tư vấn Đại hội V, 1924”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Hình chụp tấm thẻ đại biểu tư vấn của Nguyễn Ái Quốc ngày nay được công bố rộng rãi như một tư liệu thuộc phạm vi công cộng, cùng với bức ảnh các đại biểu Đại hội V tại Điện Kremli. Các bài phát biểu của Người tại đại hội được in trong Hồ Chí Minh Toàn tập, tập 1, do Nhà xuất bản Chính trị quốc gia ấn hành. Nhờ vậy, bạn đọc hôm nay có thể đọc lại những gì người thanh niên ba mươi tư tuổi đã nói trước đại hội năm 1924.\n\nTrong gian Liên Xô của Bảo tàng Hành trình 3D, tấm thẻ được giới thiệu cùng bức ảnh các đại biểu và bài báo trên Pravda. Ba tư liệu ấy nối thành một mạch: từ lời tiễn biệt Lênin tháng 1, đến diễn đàn quốc tế lớn nhất mà Người đứng lên phát biểu tháng 6 và tháng 7 năm 1924. Khách tham quan có thể dừng lại trước tấm thẻ nhỏ này để nhớ rằng có những tiếng nói không cần lá phiếu vẫn vang xa. Mười một năm sau, tại Đại hội VII năm 1935, Người lại dự với tư cách đại biểu tư vấn, nhưng khi ấy Đông Dương đã có đoàn đại biểu chính thức của mình.","doc":12}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 1 (1890 – 1929), NXB Chính trị quốc gia – các mục tháng 3 đến tháng 11/1924","Hồ Chí Minh Toàn tập, tập 1, NXB Chính trị quốc gia – Sự thật, 2011 – các bài phát biểu tại Đại hội V Quốc tế Cộng sản","Hồ Chí Minh – Biên niên tiểu sử, tập 2, NXB Chính trị quốc gia – mục Đại hội VII Quốc tế Cộng sản (1935)","Bách khoa toàn thư Britannica – các mục Comintern, Antonio Gramsci"],"doc":[{"t":"Tấm thẻ không có quyền biểu quyết: tiếng nói của các dân tộc thuộc địa ở Đại hội V. Bốn ngày trước khi Đại hội V Quốc tế Cộng sản khai mạc, Nguyễn Ái Quốc viết thư xin một tấm thẻ dự đại hội. Tấm thẻ Người nhận được mang tư cách đại biểu tư vấn: được nói, nhưng không được bỏ phiếu. Người đã dùng trọn quyền được nói ấy, từ phiên khai mạc đến những phiên họp cuối, để kéo sự chú ý của cả đại hội về phía các thuộc địa."},{"t":"Lá thư ngày 13/6/1924. Ngày 13/6/1924, từ Mátxcơva, Nguyễn Ái Quốc gửi thư cho Pêtơrốp, Chủ tịch Ban Phương Đông của Quốc tế Cộng sản, đề nghị được cấp thẻ dự Đại hội lần thứ V. Chỉ còn bốn ngày nữa là đại hội khai mạc. Lá thư ngắn ấy, được ghi lại trong Biên niên tiểu sử, cho thấy tấm thẻ trong ảnh không tự nhiên đến tay Người. Đó là một chỗ ngồi mà Người chủ động tìm kiếm, vì hiểu diễn đàn này quan trọng thế nào với các dân tộc thuộc địa. Khi ấy, Người đã sống ở Mátxcơva gần một năm. Ngày 14/4/1924, Người nhận quyết định làm cán bộ ngoài biên chế của Ban Phương Đông, với mức lương 60 rúp mỗi tháng. Đời sống chẳng dễ dàng gì. Trong một lá thư gửi Pêtơrốp hồi tháng 3, Người phàn nàn rằng phòng ở lúc nào cũng có bốn, năm người ở chung, ban đêm thì bị rệp cắn. Nhưng điều khiến Người bận lòng hơn cả là vấn đề thuộc địa vẫn chưa được quan tâm đúng mức trong phong trào cộng sản quốc tế."},{"t":"Những lá thư trước đại hội. Tấm thẻ đại biểu là kết quả của nhiều tháng kiên trì. Ngày 15/3/1924, Người viết thư cho Dinôviép, Chủ tịch Quốc tế Cộng sản, nhắc lại đề nghị được gặp để thảo luận về vấn đề thuộc địa của Pháp. Ngày 20/5, trong thư gửi Pêtơrốp, Người đề nghị lập một nhóm về châu Á, tổ chức trao đổi kinh nghiệm giữa những người hoạt động ở các nước phương Đông, và thành lập một Tiểu ban Phương Đông. Những lá thư ấy cho thấy một người không ngồi chờ được giao việc. Người đọc, viết, đề xuất, rồi lại đề xuất. Trong mắt Người, Quốc tế Cộng sản là nơi có thể đem sức mạnh của phong trào thế giới đến với các dân tộc bị áp bức. Nhưng muốn vậy, trước hết phải làm cho những người lãnh đạo phong trào hiểu rằng thuộc địa không phải là chuyện bên lề. Đại hội V, nơi hội tụ đông đủ đại biểu các đảng cộng sản trên thế giới, chính là dịp tốt nhất để nói điều đó thành tiếng."},{"t":"“Đại biểu tư vấn” nghĩa là gì?. Đại hội lần thứ V Quốc tế Cộng sản họp tại Mátxcơva từ ngày 17/6 đến 8/7/1924. Đại biểu dự đại hội chia làm hai loại. Đại biểu chính thức của các đảng thành viên có quyền biểu quyết, tức là được bỏ phiếu thông qua các nghị quyết. Đại biểu tư vấn được dự họp, được phát biểu, được góp ý kiến, nhưng không bỏ phiếu. Tấm thẻ cấp cho Nguyễn Ái Quốc thuộc loại thứ hai. Lý do không khó hiểu. Năm 1924, Đông Dương chưa có đảng cộng sản. Phải sáu năm nữa, qua hội nghị hợp nhất họp từ ngày 6/1 đến 7/2/1930 tại Cửu Long, Hương Cảng, Đảng Cộng sản Việt Nam mới ra đời. Không có một đảng ở quê hương đứng sau lưng, người thanh niên Việt Nam chỉ có thể dự đại hội với tiếng nói tư vấn. Nhưng chính từ vị trí khiêm tốn ấy, Người vẫn có thể nói thẳng điều mình thấy về thân phận các dân tộc bị áp bức, trước những người đứng đầu phong trào cộng sản thế giới."},{"t":"Bạn có biết? Tập san Inprekorr, tờ thông tin báo chí quốc tế của Quốc tế Cộng sản, ra bằng nhiều thứ tiếng. Bản tiếng Pháp mang tên La Correspondance internationale. Trong năm 1924, nhiều bài viết về Đông Dương của Nguyễn Ái Quốc được in trên bản tiếng Pháp này."},{"t":"Câu hỏi trong phiên khai mạc. Đại hội khai mạc vào buổi tối ngày 17/6/1924, trong Điện Kremli. Theo Biên niên tiểu sử, ngay tại phiên khai mạc, Nguyễn Ái Quốc đã lên tiếng. Người hỏi đại hội có gửi một lời kêu gọi đặc biệt tới các nước thuộc địa hay không, và đề nghị bổ sung vào lời kêu gọi của đại hội đối tượng “các dân tộc các nước thuộc địa”. Đề nghị ấy được chấp nhận. Đó là một chi tiết nhỏ, nhưng rất tiêu biểu cho cách làm việc của Người. Trong văn kiện của phong trào cộng sản thời ấy, người ta thường nói nhiều về giai cấp vô sản châu Âu, về công nhân các nước công nghiệp. Hàng trăm triệu con người ở châu Á, châu Phi, những người mà tờ Le Paria của Người gọi là “người cùng khổ”, rất dễ bị bỏ quên. Người muốn ngay từ buổi đầu, trong lời kêu gọi của đại hội, các dân tộc thuộc địa phải được gọi đích danh. Và Người đã làm được điều đó chỉ bằng một câu hỏi và một đề nghị ngắn gọn."},{"t":"Phiên họp thứ 8: con rắn và cái đuôi. Ngày 23/6/1924, tại phiên họp thứ 8, Nguyễn Ái Quốc có bài phát biểu được nhắc tới nhiều nhất của mình ở đại hội. Người thẳng thắn phê bình các đảng cộng sản ở những nước có thuộc địa, trong đó có Đảng Cộng sản Pháp, là chưa quan tâm đúng mức tới phong trào giải phóng ở thuộc địa. Người nói rằng nghe các đồng chí ở chính quốc phát biểu, Người có cảm tưởng họ muốn đánh chết rắn đằng đuôi. Hình ảnh ấy giản dị mà sắc sảo. Chủ nghĩa đế quốc được ví như một con rắn độc. Nếu nọc độc và sức sống của nó tập trung ở thuộc địa, thì chỉ đánh ở chính quốc chẳng khác nào đánh vào đuôi rắn: con rắn vẫn sống. Muốn đánh bại chủ nghĩa tư bản, phải tước đi thuộc địa của nó. Trong những lời phát biểu tại đại hội, Người khẳng định vận mệnh của giai cấp vô sản thế giới gắn chặt với vận mệnh của các dân tộc bị áp bức ở thuộc địa. Với một đại biểu chỉ có tiếng nói tư vấn, đó là những lời phê bình rất thẳng thắn."},{"t":"Tất cả các đồng chí đều biết rằng, hiện nay nọc độc và sức sống của con rắn độc tư bản chủ nghĩa đang tập trung ở các thuộc địa hơn là ở chính quốc. — Nguyễn Ái Quốc"},{"t":"Phiên thứ 22 và 25: từ phê bình đến đề nghị. Một tuần sau, ngày 1/7/1924, tại phiên họp thứ 22, Người lại phát biểu. Lần này, Người phê bình các đảng cộng sản Pháp, Anh, Hà Lan là chưa có một chính sách tích cực về vấn đề thuộc địa. Đó là ba nước nắm trong tay những đế quốc thuộc địa rộng lớn bậc nhất thế giới. Nước Anh có Ấn Độ. Hà Lan có quần đảo Đông Ấn, nay là Inđônêxia. Pháp có Đông Dương cùng những vùng đất mênh mông ở Bắc Phi và Tây Phi. Theo Người, chính các đảng ở những nước ấy phải đi đầu trong việc ủng hộ phong trào giải phóng thuộc địa. Hai ngày sau, ngày 3/7, tại phiên họp thứ 25, Người phát biểu về vấn đề ruộng đất và nạn đói ở các thuộc địa của Pháp. Người chỉ ra rằng nông dân bản xứ đông đảo và khốn khổ, nhưng thiếu tổ chức, thiếu người lãnh đạo, nên rất cần sự giúp đỡ của Quốc tế Cộng sản. Từ phê bình, Người đi tới đề nghị: Quốc tế Cộng sản cần có những biện pháp cụ thể để giúp đỡ phong trào ở các thuộc địa."},{"t":"Lời nói được in thành chữ. Những lời phát biểu của Nguyễn Ái Quốc không dừng lại trong hội trường. Ngày 4/7/1924, khi đại hội còn đang họp, tập san Inprekorr số 41 đăng lời phát biểu của Người. Nhờ đó, ý kiến của một đại biểu tư vấn đến từ Đông Dương đến được với những người cộng sản ở nhiều nước. Biên bản đại hội cũng ghi lại các bài phát biểu. Về sau, chúng được dịch ra tiếng Việt và in trong Hồ Chí Minh Toàn tập, tập 1. Đây cũng là quãng thời gian Người viết rất nhiều. Chỉ trong nửa đầu năm 1924, tập san Inprekorr đã đăng nhiều bài của Người về Đông Dương và chủ nghĩa thực dân Pháp: “Đông Dương và Thái Bình Dương” tháng 3, “Chủ nghĩa đế quốc Pháp dám làm những gì?” tháng 4, “Sự phá sản của chế độ thực dân Pháp” tháng 5. Bài “Những cái tốt đẹp của nền văn minh Pháp” ra đúng ngày đại hội khai mạc, 17/6/1924. Trên mặt báo cũng như ở diễn đàn, Người theo đuổi cùng một mục tiêu: để thế giới biết các dân tộc thuộc địa đang phải chịu đựng những gì."},{"t":"Từ Mátxcơva về phương Đông. Đại hội bế mạc ngày 8/7/1924. Suốt mùa hè năm ấy, Người còn dự nhiều đại hội quốc tế khác ở Mátxcơva (xem chuyên đề Các đại biểu Đại hội V Quốc tế Cộng sản, 1924). Nhưng mong muốn lớn nhất của Người là trở về gần Tổ quốc. Ngay từ ngày 11/4/1924, Người đã gửi Ban Chấp hành Quốc tế Cộng sản kế hoạch đi Trung Quốc qua ngả Viễn Đông. Trả lời phỏng vấn Giôvanni Giécmanéttô cho báo L'Unità của Ý hồi tháng 3, khi được hỏi sẽ làm gì sau khi học xong, Người nói sẽ trở về Tổ quốc để đấu tranh. Cuối năm 1924, đề nghị ấy được chấp thuận. Người rời Mátxcơva, và ngày 11/11/1924 tới Quảng Châu. Ở đó, Người tập hợp những thanh niên Việt Nam yêu nước đầu tiên, mở lớp huấn luyện, và tháng 6/1925 lập Hội Việt Nam Cách mạng Thanh niên. Những điều Người nói ở Đại hội V, rằng nông dân thuộc địa thiếu tổ chức và thiếu người lãnh đạo, giờ được chính Người bắt tay giải quyết, ngay sát biên giới quê hương."},{"t":"Bạn có biết? Báo L'Unità, nơi đăng cuộc phỏng vấn Nguyễn Ái Quốc, ra số đầu tiên ngày 12/2/1924 do nhà lý luận cộng sản Ý Antonio Gramsci sáng lập. Khi phỏng vấn Người, tờ báo mới ra đời được khoảng một tháng."},{"t":"Dấu tích hôm nay. Hình chụp tấm thẻ đại biểu tư vấn của Nguyễn Ái Quốc ngày nay được công bố rộng rãi như một tư liệu thuộc phạm vi công cộng, cùng với bức ảnh các đại biểu Đại hội V tại Điện Kremli. Các bài phát biểu của Người tại đại hội được in trong Hồ Chí Minh Toàn tập, tập 1, do Nhà xuất bản Chính trị quốc gia ấn hành. Nhờ vậy, bạn đọc hôm nay có thể đọc lại những gì người thanh niên ba mươi tư tuổi đã nói trước đại hội năm 1924. Trong gian Liên Xô của Bảo tàng Hành trình 3D, tấm thẻ được giới thiệu cùng bức ảnh các đại biểu và bài báo trên Pravda. Ba tư liệu ấy nối thành một mạch: từ lời tiễn biệt Lênin tháng 1, đến diễn đàn quốc tế lớn nhất mà Người đứng lên phát biểu tháng 6 và tháng 7 năm 1924. Khách tham quan có thể dừng lại trước tấm thẻ nhỏ này để nhớ rằng có những tiếng nói không cần lá phiếu vẫn vang xa. Mười một năm sau, tại Đại hội VII năm 1935, Người lại dự với tư cách đại biểu tư vấn, nhưng khi ấy Đông Dương đã có đoàn đại biểu chính thức của mình."}],"so_chu":1940},{"i":7,"tieu_de_bang":"Các đại biểu Đại hội V Quốc tế Cộng sản, 1924","tieu_de":"Mùa hè 1924 ở Điện Kremli: đại hội đầu tiên vắng bóng Lênin","sapo":"Bức ảnh tập thể ghi lại các đại biểu dự Đại hội V Quốc tế Cộng sản tại Điện Kremli, mùa hè năm 1924. Đó là đại hội đầu tiên của Quốc tế Cộng sản vắng bóng Lênin, người đã ra đi chưa đầy năm tháng trước. Giữa hơn năm trăm đại biểu về Mátxcơva năm ấy có một thanh niên Việt Nam ba mươi tư tuổi, mang tấm thẻ đại biểu tư vấn và một câu hỏi lớn về các dân tộc thuộc địa.","bia":{"src":"textures/ht/ht_anh_participants_in_the_5th_congress_of_the_communis.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Mátxcơva, tháng 6/1924","text":"Tối 17/6/1924, Đại hội lần thứ V Quốc tế Cộng sản khai mạc trong Điện Kremli. Theo Biên niên tiểu sử, đại hội có 504 đại biểu của 49 đảng, đến từ nhiều châu lục. Các phiên họp diễn ra ở cung Anđrâyépxki, tức phòng Thánh Anđrây trong Cung điện Kremli Lớn, kéo dài ba tuần, đến ngày 8/7 mới bế mạc. Bức ảnh tư liệu này ghi lại các đại biểu tại Điện Kremli trong những ngày ấy, khi Mátxcơva đã vào hè, sau một mùa đông tang tóc.\n\nChưa đầy năm tháng trước, ngày 21/1/1924, Lênin từ trần. Bên ngoài tường thành Kremli, trên Quảng trường Đỏ, là lăng gỗ nơi đặt thi hài Người. Những người về dự đại hội năm ấy mang theo một câu hỏi chung: phong trào sẽ đi tiếp ra sao khi người sáng lập Quốc tế Cộng sản không còn nữa? Trong số họ có một thanh niên Việt Nam ba mươi tư tuổi, cầm tấm thẻ đại biểu tư vấn. Người mang theo một câu hỏi khác: phong trào ấy có thật sự nhìn thấy các dân tộc thuộc địa hay không?","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_participants_in_the_5th_congress_of_the_communis.jpg","chu_thich":"Các đại biểu Đại hội V Quốc tế Cộng sản tại Điện Kremli, 1924.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Phòng ngai vàng cũ của Sa hoàng","text":"Cung điện Kremli Lớn được xây trong những năm 1838 – 1849 theo thiết kế của kiến trúc sư Konstantin Thon, làm nơi ở và nơi cử hành nghi lễ của hoàng gia Nga mỗi khi về Mátxcơva. Phòng Thánh Anđrây là phòng ngai vàng của cung điện. Tên phòng lấy từ huân chương Thánh Anđrây, huân chương cao quý nhất của đế quốc Nga, do Pie Đại đế lập ra cuối thế kỷ XVII. Đây là một trong những gian phòng lộng lẫy nhất của cả quần thể Kremli.\n\nSau Cách mạng Tháng Mười, chính quyền Xô-viết chuyển về Mátxcơva. Những gian phòng từng dành cho nghi lễ hoàng gia trở thành nơi hội họp của nhà nước mới và của các đại hội quốc tế. Có thể hình dung sự tương phản của mùa hè năm 1924: người thanh niên từng làm phụ bếp trên tàu biển, từng sống giữa những người lao động nghèo ở London và Paris, nay có mặt trong phòng ngai vàng cũ của Sa hoàng để nói về số phận người nông dân An Nam. Sự tương phản ấy là hình ảnh của một thời đại mà những người cùng khổ bắt đầu bước lên diễn đàn thế giới.","doc":2},{"loai":"ban_co_biet","text":"Tháng 3/1918, chính phủ Xô-viết chuyển thủ đô từ Petrograd về Mátxcơva, và Điện Kremli trở thành nơi làm việc của Lênin cùng các cơ quan lãnh đạo cao nhất. Từ đó, Kremli gắn với hầu hết các sự kiện lớn của nhà nước Xô-viết, kể cả các đại hội của Quốc tế Cộng sản.","nguon_ten":"Bách khoa toàn thư Britannica, các mục Moscow và Kremlin","doc":3},{"loai":"anh","src":"textures/bang_w/G08_7_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Các đại biểu Đại hội V Quốc tế Cộng sản, 1924”, nhìn từ xa."},{"loai":"doan","tieu_de":"Đại hội đầu tiên vắng bóng Lênin","text":"Bốn đại hội trước của Quốc tế Cộng sản, họp các năm 1919, 1920, 1921 và 1922, đều có Lênin tham dự. Chính tại Đại hội II năm 1920, bản luận cương về vấn đề dân tộc và thuộc địa của Lênin được thảo luận và thông qua. Bản sơ thảo luận cương ấy đã đến với Nguyễn Ái Quốc qua báo L'Humanité ở Paris tháng 7/1920. Từ cơn bệnh tháng 5/1922, sức khỏe Lênin suy sụp dần. Cơn bệnh tháng 3/1923 khiến Người mất khả năng nói, và đầu năm 1924 thì Người qua đời.\n\nĐại hội V vì thế diễn ra trong một không khí khác hẳn. Chủ tịch Ban Chấp hành Quốc tế Cộng sản khi ấy là Dinôviép. Đại hội bàn về tình hình thế giới, về việc củng cố các đảng cộng sản, về vấn đề ruộng đất và vấn đề dân tộc, thuộc địa. Kế tục di sản của Lênin là câu hỏi lớn của cả đại hội. Nguyễn Ái Quốc, người tìm thấy con đường cứu nước từ chính bản luận cương năm 1920, đến đại hội với mong muốn những tư tưởng của Lênin về thuộc địa được biến thành việc làm cụ thể.","doc":4},{"loai":"ban_co_biet","text":"Lần cuối Lênin phát biểu trước một đại hội Quốc tế Cộng sản là ngày 13/11/1922, tại Đại hội IV. Dù sức khỏe đã suy yếu, Người vẫn tự trình bày bản báo cáo “Năm năm cách mạng Nga và những triển vọng của cách mạng thế giới” bằng tiếng Đức.","nguon_ten":"V.I. Lênin, Toàn tập, tập 45, NXB Tiến bộ, Mátxcơva; Bách khoa toàn thư Britannica, mục Comintern","doc":5},{"loai":"doan","tieu_de":"Người thanh niên thuộc địa giữa hội trường","text":"Đến đại hội, Nguyễn Ái Quốc mang theo vốn sống của mười ba năm bôn ba kể từ ngày rời bến Nhà Rồng. Người từng làm thuê trên tàu biển, sống giữa những người lao động ở London và Paris. Năm 1921, Người cùng những người bạn từ các thuộc địa Pháp lập Hội Liên hiệp thuộc địa. Năm 1922, Người sáng lập báo Le Paria. Người hiểu rằng tiếng nói của người dân thuộc địa ít khi được lắng nghe, ngay cả trong phong trào công nhân châu Âu. Bởi thế, Người tận dụng mọi dịp để lên tiếng: nêu đề nghị ngay trong phiên khai mạc, rồi phát biểu tại các phiên họp thứ 8, 22 và 25 (xem chuyên đề Thẻ đại biểu tư vấn Đại hội V, 1924).\n\nBức ảnh tập thể không ghi lại được những lời nói ấy. Nhưng nó giúp ta hình dung khung cảnh trong đó chúng được cất lên: một hội trường đông đảo đại biểu các nước, phần lớn đến từ châu Âu, nơi phong trào công nhân đã có lịch sử hàng chục năm. Giữa khung cảnh ấy, một người Việt Nam đứng lên nhắc tới những người nông dân mất ruộng, những xứ thuộc địa bị nạn đói hoành hành. Đó là phần câu chuyện mà bức ảnh lặng lẽ gợi ra.","doc":6},{"loai":"doan","tieu_de":"Những gương mặt của một mùa hè","text":"Mùa hè năm ấy, Nguyễn Ái Quốc có dịp gặp gỡ nhiều nhân vật tên tuổi của nhà nước Xô-viết và của phong trào quốc tế. Theo Biên niên tiểu sử, ngày 6/7/1924, trong một cuộc mít tinh vì hòa bình tại Mátxcơva, Người được mời vào Đoàn Chủ tịch, ngồi cạnh Vôrôsilốp, Kalinin, Dinôviép và Phơrunde. Kalinin khi ấy là Chủ tịch Ban Chấp hành Trung ương các Xô-viết. Phơrunde và Vôrôsilốp là những vị chỉ huy nổi tiếng của Hồng quân từ thời nội chiến.\n\nMột người dân thuộc địa không có quyền biểu quyết ở đại hội lại ngồi ở hàng ghế Đoàn Chủ tịch của một cuộc mít tinh lớn giữa thủ đô Xô-viết. Chi tiết ấy cho thấy sau gần một năm ở Mátxcơva, Nguyễn Ái Quốc đã được bạn bè quốc tế biết đến và tin cậy. Nếu bức ảnh tập thể cho thấy quy mô của đại hội, thì những ghi chép trong Biên niên tiểu sử cho thấy nhịp làm việc dày đặc của Người trong những tuần lễ ấy: họp, phát biểu, viết bài, dự mít tinh, rồi lại họp.","doc":7},{"loai":"anh","src":"textures/bang_w/G08_7_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Các đại biểu Đại hội V Quốc tế Cộng sản, 1924”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Mùa hè của những đại hội","text":"Đại hội V không phải là hội nghị quốc tế duy nhất ở Mátxcơva mùa hè năm 1924. Nối tiếp nhau, thủ đô Xô-viết đón Đại hội IV Quốc tế Thanh niên Cộng sản, Đại hội III Quốc tế Công hội đỏ và Đại hội I Quốc tế Cứu tế đỏ. Theo Biên niên tiểu sử, Nguyễn Ái Quốc có mặt ở cả ba. Tại Đại hội Quốc tế Công hội đỏ, Người dự với tư cách đại biểu Đông Dương. Ngày 21/7/1924, tại phiên họp thứ 15, Người đọc tham luận về tình hình sản xuất công nghiệp ở Đông Dương.\n\nTrong tham luận ấy, Người tố cáo rằng ở Đông Dương, chế độ nô lệ đã được phục hồi, và cho biết giai cấp công nhân Việt Nam khi ấy chưa có một tổ chức nào của mình. Phải năm năm sau, ngày 28/7/1929, Tổng Công hội đỏ Bắc Kỳ mới được thành lập. Trước đó, từ tháng 10/1923, Người đã được bầu vào Đoàn Chủ tịch Quốc tế Nông dân. Như vậy, chỉ trong khoảng một năm, Người đã lên tiếng cho nông dân, công nhân và thanh niên thuộc địa ở hầu hết các tổ chức quốc tế lớn đặt trụ sở tại Mátxcơva.","doc":8},{"loai":"doan","tieu_de":"Từ Đại hội V đến Đại hội VII","text":"Đại hội V là kỳ đại hội Quốc tế Cộng sản đầu tiên mà Nguyễn Ái Quốc trực tiếp tham dự. Đại hội VI họp tại Mátxcơva từ tháng 7 đến tháng 9/1928, khi Người đang hoạt động bí mật giữa bà con Việt kiều ở Xiêm. Đến Đại hội VII, họp mùa hè năm 1935, Đông Dương đã có đoàn đại biểu chính thức của Đảng Cộng sản Đông Dương do Lê Hồng Phong dẫn đầu. Nguyễn Ái Quốc lại dự với tư cách đại biểu tư vấn (xem chuyên đề Đồng chí Lin ở Mátxcơva, 1934 – 1938).\n\nMười một năm giữa hai kỳ đại hội ấy là quãng đường Người đi từ một đại biểu tư vấn chưa có đảng ở quê hương đứng sau, đến người sáng lập một đảng có đoàn đại biểu chính thức trên diễn đàn quốc tế. Đại hội VII cũng là đại hội cuối cùng: năm 1943, Quốc tế Cộng sản tuyên bố tự giải tán (xem chuyên đề Quốc tế Cộng sản). Nhìn lại, bức ảnh các đại biểu Đại hội V ghi lại điểm khởi đầu của quãng đường ấy, khi người thanh niên Việt Nam lần đầu bước vào nghị trường lớn nhất của phong trào cộng sản thế giới.","doc":9},{"loai":"anh","src":"textures/bang_w/G08_7_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Các đại biểu Đại hội V Quốc tế Cộng sản, 1924”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Phòng Thánh Anđrây, nơi Đại hội V họp năm 1924, đã trải qua nhiều thay đổi. Đầu thập niên 1930, phòng này và phòng Alếchxanđrơ bên cạnh được nhập làm một, thành hội trường lớn về sau dùng cho các kỳ họp của Xô-viết Tối cao Liên Xô. Cuối thập niên 1990, hai phòng được khôi phục lại dáng vẻ ban đầu. Ngày nay, phòng Thánh Anđrây là nơi diễn ra lễ nhậm chức của Tổng thống Nga.\n\nHồ sơ của Quốc tế Cộng sản hiện được lưu giữ tại Lưu trữ Nhà nước Nga về lịch sử chính trị – xã hội ở Mátxcơva. Kho hồ sơ ấy gồm biên bản các kỳ đại hội cùng rất nhiều thư từ, báo cáo của cán bộ các nước. Đó là nguồn tư liệu quan trọng giúp các nhà nghiên cứu Việt Nam và nước ngoài dựng lại những năm Nguyễn Ái Quốc ở Liên Xô. Còn bức ảnh các đại biểu Đại hội V, nay thuộc phạm vi công cộng, được đặt trong gian Liên Xô của Bảo tàng Hành trình 3D, cùng với tấm thẻ đại biểu tư vấn của Người và bài báo trên Pravda.","doc":10}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 1 (1890 – 1929), NXB Chính trị quốc gia – các mục tháng 6 và tháng 7/1924","Hồ Chí Minh Toàn tập, tập 1, NXB Chính trị quốc gia – Sự thật, 2011 – các bài phát biểu tại Đại hội V Quốc tế Cộng sản","Hồ Chí Minh – Biên niên tiểu sử, tập 2, NXB Chính trị quốc gia – mục Đại hội VII Quốc tế Cộng sản (1935)","V.I. Lênin, Toàn tập, tập 45, NXB Tiến bộ, Mátxcơva – báo cáo tại Đại hội IV Quốc tế Cộng sản","Bách khoa toàn thư Britannica – các mục Comintern, Kremlin, Moscow"],"doc":[{"t":"Mùa hè 1924 ở Điện Kremli: đại hội đầu tiên vắng bóng Lênin. Bức ảnh tập thể ghi lại các đại biểu dự Đại hội V Quốc tế Cộng sản tại Điện Kremli, mùa hè năm 1924. Đó là đại hội đầu tiên của Quốc tế Cộng sản vắng bóng Lênin, người đã ra đi chưa đầy năm tháng trước. Giữa hơn năm trăm đại biểu về Mátxcơva năm ấy có một thanh niên Việt Nam ba mươi tư tuổi, mang tấm thẻ đại biểu tư vấn và một câu hỏi lớn về các dân tộc thuộc địa."},{"t":"Mátxcơva, tháng 6/1924. Tối 17/6/1924, Đại hội lần thứ V Quốc tế Cộng sản khai mạc trong Điện Kremli. Theo Biên niên tiểu sử, đại hội có 504 đại biểu của 49 đảng, đến từ nhiều châu lục. Các phiên họp diễn ra ở cung Anđrâyépxki, tức phòng Thánh Anđrây trong Cung điện Kremli Lớn, kéo dài ba tuần, đến ngày 8/7 mới bế mạc. Bức ảnh tư liệu này ghi lại các đại biểu tại Điện Kremli trong những ngày ấy, khi Mátxcơva đã vào hè, sau một mùa đông tang tóc. Chưa đầy năm tháng trước, ngày 21/1/1924, Lênin từ trần. Bên ngoài tường thành Kremli, trên Quảng trường Đỏ, là lăng gỗ nơi đặt thi hài Người. Những người về dự đại hội năm ấy mang theo một câu hỏi chung: phong trào sẽ đi tiếp ra sao khi người sáng lập Quốc tế Cộng sản không còn nữa? Trong số họ có một thanh niên Việt Nam ba mươi tư tuổi, cầm tấm thẻ đại biểu tư vấn. Người mang theo một câu hỏi khác: phong trào ấy có thật sự nhìn thấy các dân tộc thuộc địa hay không?"},{"t":"Phòng ngai vàng cũ của Sa hoàng. Cung điện Kremli Lớn được xây trong những năm 1838 – 1849 theo thiết kế của kiến trúc sư Konstantin Thon, làm nơi ở và nơi cử hành nghi lễ của hoàng gia Nga mỗi khi về Mátxcơva. Phòng Thánh Anđrây là phòng ngai vàng của cung điện. Tên phòng lấy từ huân chương Thánh Anđrây, huân chương cao quý nhất của đế quốc Nga, do Pie Đại đế lập ra cuối thế kỷ XVII. Đây là một trong những gian phòng lộng lẫy nhất của cả quần thể Kremli. Sau Cách mạng Tháng Mười, chính quyền Xô-viết chuyển về Mátxcơva. Những gian phòng từng dành cho nghi lễ hoàng gia trở thành nơi hội họp của nhà nước mới và của các đại hội quốc tế. Có thể hình dung sự tương phản của mùa hè năm 1924: người thanh niên từng làm phụ bếp trên tàu biển, từng sống giữa những người lao động nghèo ở London và Paris, nay có mặt trong phòng ngai vàng cũ của Sa hoàng để nói về số phận người nông dân An Nam. Sự tương phản ấy là hình ảnh của một thời đại mà những người cùng khổ bắt đầu bước lên diễn đàn thế giới."},{"t":"Bạn có biết? Tháng 3/1918, chính phủ Xô-viết chuyển thủ đô từ Petrograd về Mátxcơva, và Điện Kremli trở thành nơi làm việc của Lênin cùng các cơ quan lãnh đạo cao nhất. Từ đó, Kremli gắn với hầu hết các sự kiện lớn của nhà nước Xô-viết, kể cả các đại hội của Quốc tế Cộng sản."},{"t":"Đại hội đầu tiên vắng bóng Lênin. Bốn đại hội trước của Quốc tế Cộng sản, họp các năm 1919, 1920, 1921 và 1922, đều có Lênin tham dự. Chính tại Đại hội II năm 1920, bản luận cương về vấn đề dân tộc và thuộc địa của Lênin được thảo luận và thông qua. Bản sơ thảo luận cương ấy đã đến với Nguyễn Ái Quốc qua báo L'Humanité ở Paris tháng 7/1920. Từ cơn bệnh tháng 5/1922, sức khỏe Lênin suy sụp dần. Cơn bệnh tháng 3/1923 khiến Người mất khả năng nói, và đầu năm 1924 thì Người qua đời. Đại hội V vì thế diễn ra trong một không khí khác hẳn. Chủ tịch Ban Chấp hành Quốc tế Cộng sản khi ấy là Dinôviép. Đại hội bàn về tình hình thế giới, về việc củng cố các đảng cộng sản, về vấn đề ruộng đất và vấn đề dân tộc, thuộc địa. Kế tục di sản của Lênin là câu hỏi lớn của cả đại hội. Nguyễn Ái Quốc, người tìm thấy con đường cứu nước từ chính bản luận cương năm 1920, đến đại hội với mong muốn những tư tưởng của Lênin về thuộc địa được biến thành việc làm cụ thể."},{"t":"Bạn có biết? Lần cuối Lênin phát biểu trước một đại hội Quốc tế Cộng sản là ngày 13/11/1922, tại Đại hội IV. Dù sức khỏe đã suy yếu, Người vẫn tự trình bày bản báo cáo “Năm năm cách mạng Nga và những triển vọng của cách mạng thế giới” bằng tiếng Đức."},{"t":"Người thanh niên thuộc địa giữa hội trường. Đến đại hội, Nguyễn Ái Quốc mang theo vốn sống của mười ba năm bôn ba kể từ ngày rời bến Nhà Rồng. Người từng làm thuê trên tàu biển, sống giữa những người lao động ở London và Paris. Năm 1921, Người cùng những người bạn từ các thuộc địa Pháp lập Hội Liên hiệp thuộc địa. Năm 1922, Người sáng lập báo Le Paria. Người hiểu rằng tiếng nói của người dân thuộc địa ít khi được lắng nghe, ngay cả trong phong trào công nhân châu Âu. Bởi thế, Người tận dụng mọi dịp để lên tiếng: nêu đề nghị ngay trong phiên khai mạc, rồi phát biểu tại các phiên họp thứ 8, 22 và 25 (xem chuyên đề Thẻ đại biểu tư vấn Đại hội V, 1924). Bức ảnh tập thể không ghi lại được những lời nói ấy. Nhưng nó giúp ta hình dung khung cảnh trong đó chúng được cất lên: một hội trường đông đảo đại biểu các nước, phần lớn đến từ châu Âu, nơi phong trào công nhân đã có lịch sử hàng chục năm. Giữa khung cảnh ấy, một người Việt Nam đứng lên nhắc tới những người nông dân mất ruộng, những xứ thuộc địa bị nạn đói hoành hành. Đó là phần câu chuyện mà bức ảnh lặng lẽ gợi ra."},{"t":"Những gương mặt của một mùa hè. Mùa hè năm ấy, Nguyễn Ái Quốc có dịp gặp gỡ nhiều nhân vật tên tuổi của nhà nước Xô-viết và của phong trào quốc tế. Theo Biên niên tiểu sử, ngày 6/7/1924, trong một cuộc mít tinh vì hòa bình tại Mátxcơva, Người được mời vào Đoàn Chủ tịch, ngồi cạnh Vôrôsilốp, Kalinin, Dinôviép và Phơrunde. Kalinin khi ấy là Chủ tịch Ban Chấp hành Trung ương các Xô-viết. Phơrunde và Vôrôsilốp là những vị chỉ huy nổi tiếng của Hồng quân từ thời nội chiến. Một người dân thuộc địa không có quyền biểu quyết ở đại hội lại ngồi ở hàng ghế Đoàn Chủ tịch của một cuộc mít tinh lớn giữa thủ đô Xô-viết. Chi tiết ấy cho thấy sau gần một năm ở Mátxcơva, Nguyễn Ái Quốc đã được bạn bè quốc tế biết đến và tin cậy. Nếu bức ảnh tập thể cho thấy quy mô của đại hội, thì những ghi chép trong Biên niên tiểu sử cho thấy nhịp làm việc dày đặc của Người trong những tuần lễ ấy: họp, phát biểu, viết bài, dự mít tinh, rồi lại họp."},{"t":"Mùa hè của những đại hội. Đại hội V không phải là hội nghị quốc tế duy nhất ở Mátxcơva mùa hè năm 1924. Nối tiếp nhau, thủ đô Xô-viết đón Đại hội IV Quốc tế Thanh niên Cộng sản, Đại hội III Quốc tế Công hội đỏ và Đại hội I Quốc tế Cứu tế đỏ. Theo Biên niên tiểu sử, Nguyễn Ái Quốc có mặt ở cả ba. Tại Đại hội Quốc tế Công hội đỏ, Người dự với tư cách đại biểu Đông Dương. Ngày 21/7/1924, tại phiên họp thứ 15, Người đọc tham luận về tình hình sản xuất công nghiệp ở Đông Dương. Trong tham luận ấy, Người tố cáo rằng ở Đông Dương, chế độ nô lệ đã được phục hồi, và cho biết giai cấp công nhân Việt Nam khi ấy chưa có một tổ chức nào của mình. Phải năm năm sau, ngày 28/7/1929, Tổng Công hội đỏ Bắc Kỳ mới được thành lập. Trước đó, từ tháng 10/1923, Người đã được bầu vào Đoàn Chủ tịch Quốc tế Nông dân. Như vậy, chỉ trong khoảng một năm, Người đã lên tiếng cho nông dân, công nhân và thanh niên thuộc địa ở hầu hết các tổ chức quốc tế lớn đặt trụ sở tại Mátxcơva."},{"t":"Từ Đại hội V đến Đại hội VII. Đại hội V là kỳ đại hội Quốc tế Cộng sản đầu tiên mà Nguyễn Ái Quốc trực tiếp tham dự. Đại hội VI họp tại Mátxcơva từ tháng 7 đến tháng 9/1928, khi Người đang hoạt động bí mật giữa bà con Việt kiều ở Xiêm. Đến Đại hội VII, họp mùa hè năm 1935, Đông Dương đã có đoàn đại biểu chính thức của Đảng Cộng sản Đông Dương do Lê Hồng Phong dẫn đầu. Nguyễn Ái Quốc lại dự với tư cách đại biểu tư vấn (xem chuyên đề Đồng chí Lin ở Mátxcơva, 1934 – 1938). Mười một năm giữa hai kỳ đại hội ấy là quãng đường Người đi từ một đại biểu tư vấn chưa có đảng ở quê hương đứng sau, đến người sáng lập một đảng có đoàn đại biểu chính thức trên diễn đàn quốc tế. Đại hội VII cũng là đại hội cuối cùng: năm 1943, Quốc tế Cộng sản tuyên bố tự giải tán (xem chuyên đề Quốc tế Cộng sản). Nhìn lại, bức ảnh các đại biểu Đại hội V ghi lại điểm khởi đầu của quãng đường ấy, khi người thanh niên Việt Nam lần đầu bước vào nghị trường lớn nhất của phong trào cộng sản thế giới."},{"t":"Dấu tích hôm nay. Phòng Thánh Anđrây, nơi Đại hội V họp năm 1924, đã trải qua nhiều thay đổi. Đầu thập niên 1930, phòng này và phòng Alếchxanđrơ bên cạnh được nhập làm một, thành hội trường lớn về sau dùng cho các kỳ họp của Xô-viết Tối cao Liên Xô. Cuối thập niên 1990, hai phòng được khôi phục lại dáng vẻ ban đầu. Ngày nay, phòng Thánh Anđrây là nơi diễn ra lễ nhậm chức của Tổng thống Nga. Hồ sơ của Quốc tế Cộng sản hiện được lưu giữ tại Lưu trữ Nhà nước Nga về lịch sử chính trị – xã hội ở Mátxcơva. Kho hồ sơ ấy gồm biên bản các kỳ đại hội cùng rất nhiều thư từ, báo cáo của cán bộ các nước. Đó là nguồn tư liệu quan trọng giúp các nhà nghiên cứu Việt Nam và nước ngoài dựng lại những năm Nguyễn Ái Quốc ở Liên Xô. Còn bức ảnh các đại biểu Đại hội V, nay thuộc phạm vi công cộng, được đặt trong gian Liên Xô của Bảo tàng Hành trình 3D, cùng với tấm thẻ đại biểu tư vấn của Người và bài báo trên Pravda."}],"so_chu":1820},{"i":8,"tieu_de_bang":"Bài báo \"Lênin và các dân tộc thuộc địa\", 1924","tieu_de":"Trên trang báo Pravda ngày tang lễ: lời tiễn biệt Lênin của một người dân thuộc địa","sapo":"Ngày 27/1/1924, ngày Mátxcơva đưa linh cữu Lênin ra Quảng trường Đỏ, báo Pravda in bài viết của một người Việt Nam mới đến nước Nga chưa đầy bảy tháng. Người ấy chưa một lần được gặp Lênin. Vậy mà bài báo ngắn của Người lại nói thay cho hàng triệu người ở các thuộc địa, những người cũng chưa từng biết mặt vị lãnh tụ.","bia":{"src":"textures/ht/ht_anh_article_lenin_and_the_colonial_peoples_by_nguyen.jpg","credit":"Ảnh: Nguyen Ai Quoc (Ho Chi Minh) · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Buổi sáng ở quán ăn tầng dưới","text":"Một buổi sáng cuối tháng 1/1924 ở Mátxcơva. Về sau, Nguyễn Ái Quốc kể lại: khi ấy mọi người đang ăn bữa sáng tại quán cơm ở tầng dưới khách sạn thì được tin Lênin mất. Ngoảnh lại, họ thấy lá cờ của Xô-viết Mátxcơva đã rủ xuống. Bữa ăn bị bỏ dở, vì không ai còn thấy đói. Lênin từ trần lúc chiều tối ngày 21/1/1924 tại Goócki, ngoại ô Mátxcơva, khi mới 53 tuổi.\n\nVới Nguyễn Ái Quốc, tin ấy đến như một mất mát riêng. Người đã mong được gặp tác giả của bản luận cương về vấn đề dân tộc và thuộc địa, văn kiện Người đọc được ở Paris năm 1920 và coi là con đường giải phóng cho dân tộc mình. Nhưng khi Người tới nước Nga mùa hè năm 1923, Lênin đã lâm bệnh nặng. Cuộc gặp ấy mãi mãi không thể diễn ra. Người gọi việc chưa được gặp Lênin là một điều ân hận lớn trong đời mình.","doc":1},{"loai":"doan","tieu_de":"Những tháng cuối của Lênin","text":"Khi Nguyễn Ái Quốc đặt chân tới nước Nga, Lênin đã không còn làm việc được. Từ cơn bệnh đầu tiên tháng 5/1922, sức khỏe của Người suy sụp dần. Tháng 3/1923, một cơn bệnh nặng hơn khiến Người mất khả năng nói. Những tháng cuối đời, Lênin sống ở Goócki, một trang viên cách trung tâm Mátxcơva hơn ba mươi ki-lô-mét, dưới sự chăm sóc của vợ là Crúpxcaia và các bác sĩ.\n\nTin Lênin mất được công bố ngày 22/1. Thi hài Người được đưa về Mátxcơva, quàn tại Hội trường Cột để nhân dân vào viếng. Theo Biên niên tiểu sử, ngày 23/1/1924, Nguyễn Ái Quốc cùng sinh viên Trường Đại học Phương Đông tham dự lễ tang. Những ngày đứng giữa giá rét của mùa đông năm ấy được kể ở một chuyên đề khác (xem chuyên đề Lăng gỗ tạm của Lênin). Ở đây, ta dõi theo trang viết mà Người gửi tới bạn đọc Liên Xô trong chính những ngày đó, thay cho những người dân thuộc địa chưa từng biết mặt Lênin.","doc":2},{"loai":"anh","src":"textures/bang_w/G08_8_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bài báo \"Lênin và các dân tộc thuộc địa\", 1924”, nhìn từ xa."},{"loai":"doan","tieu_de":"Pravda, tờ báo của những ngày tang","text":"Pravda, nghĩa là Sự thật, ra số đầu tiên ngày 5/5/1912 tại Xanh Pêtécbua, với Lênin là một trong những người sáng lập. Sau Cách mạng Tháng Mười, tờ báo chuyển về Mátxcơva cùng chính phủ Xô-viết và trở thành cơ quan ngôn luận trung ương của Đảng Cộng sản (bônsêvích) Nga. Những ngày cuối tháng 1/1924, các trang Pravda tràn ngập tin tức, lời điếu và hồi ức về Lênin.\n\nGiữa những trang ấy, ngày 27/1/1924, đúng ngày an táng, xuất hiện bài “Lênin và các dân tộc thuộc địa” ký tên Nguyễn Ái Quốc. Người viết mới đến nước Nga chưa đầy bảy tháng, và là một cái tên còn xa lạ với phần lớn bạn đọc Liên Xô. Việc cơ quan ngôn luận của Đảng đăng bài của Người đúng ngày ấy cho thấy tiếng nói của các dân tộc thuộc địa được coi là một phần trong lời tiễn biệt Lênin. Bài báo in bằng tiếng Nga. Bản tiếng Việt về sau được đưa vào Hồ Chí Minh Toàn tập, tập 1.","doc":3},{"loai":"anh","src":"textures/ht/ht_anh_article_lenin_and_the_colonial_peoples_by_nguyen.jpg","chu_thich":"Bài báo “Lênin và các dân tộc thuộc địa” của Nguyễn Ái Quốc, đăng trên báo Pravda ngày 27/1/1924.","credit":"Ảnh: Nguyen Ai Quoc (Ho Chi Minh) · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Từ An Nam đến Đahômây","text":"Bài báo mở ra bằng một hình ảnh trải rộng khắp địa cầu. Người viết rằng từ những người nông dân An Nam đến người dân săn bắn trong các rừng Đahômây, họ đều đã thầm nghe nói rằng ở một góc trời xa xăm có một dân tộc đã đánh đuổi được bọn chủ bóc lột, đang tự quản lý lấy đất nước mình. Và trong những người dũng cảm của dân tộc ấy, người dũng cảm nhất là Lênin.\n\nĐahômây là thuộc địa của Pháp ở Tây Phi. Đặt An Nam và Đahômây cạnh nhau, người viết nhắc bạn đọc Nga rằng đế quốc thực dân Pháp trải dài từ châu Á sang châu Phi, và những người bị áp bức ở hai đầu thế giới ấy có chung một cảnh ngộ. Hai chữ “thầm nghe” rất đắt: nó gợi cảnh tin tức về nước Nga được truyền đi khẽ khàng, như một điều bí mật, ở những nơi chính quyền thực dân không muốn người dân biết. Nối những người cùng khổ ở nhiều châu lục lại với nhau cũng là điều Nguyễn Ái Quốc đã làm ở Paris, khi cùng những người bạn từ các thuộc địa Pháp ở châu Phi và vùng biển Caribê lập Hội Liên hiệp thuộc địa năm 1921.","doc":4},{"loai":"ban_co_biet","text":"Đahômây, vùng đất được nhắc tới trong bài báo, giành độc lập từ Pháp năm 1960 và từ năm 1975 đổi tên thành Bênanh.","nguon_ten":"Bách khoa toàn thư Britannica, mục Benin","doc":5},{"loai":"doan","tieu_de":"Người muốn giải phóng các dân tộc khác","text":"Bài báo viết tiếp: những người dân ấy còn biết rằng vị lãnh tụ kia, sau khi giải phóng nhân dân mình, còn muốn giải phóng các dân tộc khác. Lênin đã kêu gọi các dân tộc da trắng giúp đỡ các dân tộc da vàng và da đen thoát khỏi ách thực dân, và đã vạch ra một cương lĩnh cụ thể cho cuộc đấu tranh ấy.\n\nÝ tưởng ấy không phải điều Nguyễn Ái Quốc mới biết ở Mátxcơva. Tháng 7/1920, tại Paris, Người đọc bản Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của Lênin trên báo L'Humanité. Bản luận cương đòi hỏi các đảng cộng sản phải trực tiếp ủng hộ phong trào giải phóng ở các nước thuộc địa, gắn cách mạng ở chính quốc với cuộc đấu tranh của các dân tộc bị áp bức. Với người thanh niên yêu nước khi ấy, đó là lời khẳng định rõ ràng rằng các dân tộc thuộc địa không đứng ngoài cuộc. Bài báo năm 1924 vì thế là lời tri ân của một người đã tìm thấy con đường từ chính những trang luận cương ấy.","doc":6},{"loai":"trich","text":"Khi còn sống, Người là người cha, thầy học, đồng chí và cố vấn của chúng ta. Ngày nay, Người là ngôi sao sáng chỉ đường cho chúng ta đi tới cách mạng xã hội.","nguoi":"Nguyễn Ái Quốc (viết về Lênin)","nguon_ten":"“Lênin và các dân tộc thuộc địa”, báo Pravda, 27/1/1924 – Hồ Chí Minh Toàn tập, tập 1, NXB Chính trị quốc gia – Sự thật, 2011, tr. 256 – 257","doc":7},{"loai":"doan","tieu_de":"Bốn danh xưng trong một câu văn","text":"Câu văn ấy xếp bốn danh xưng theo một trật tự rất gần với cách cảm của người phương Đông: người cha, thầy học, đồng chí, cố vấn. Trong văn hóa Việt Nam, cha và thầy là hai bậc được kính trọng hàng đầu. Đặt Lênin vào vị trí ấy là cách người viết bày tỏ lòng biết ơn sâu sắc nhất. Ngay sau đó là chữ đồng chí, chữ của những người cùng chiến đấu, và chữ cố vấn, người chỉ ra con đường. Tình cảm và lý trí đi liền nhau trong một câu văn ngắn.\n\nHình ảnh ngôi sao sáng chỉ đường cũng mang một ý nghĩa đặc biệt. Người đã mất, nhưng con đường Người vạch ra vẫn còn đó cho những ai muốn đi. Bài báo khẳng định: Lênin bất diệt sẽ sống mãi trong sự nghiệp của những người bị áp bức. Với người viết, đó không phải là một lời điếu văn theo khuôn mẫu. Đó là lời hứa của một người đã chọn con đường ấy cho mình, và hơn hai mươi năm sau sẽ cùng dân tộc mình đi tới ngày độc lập 2/9/1945.","doc":8},{"loai":"anh","src":"textures/bang_w/G08_8_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bài báo \"Lênin và các dân tộc thuộc địa\", 1924”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Một ngòi bút không nghỉ","text":"Bài báo trên Pravda chỉ là một trong rất nhiều trang viết của Nguyễn Ái Quốc ở Mátxcơva. Ngay tháng 1/1924, báo L'Humanité ở Paris đăng bài “Phong trào công nhân ở Thổ Nhĩ Kỳ” của Người. Báo La Vie Ouvrière đăng “Tình cảnh nông dân Trung Quốc” và “Phong trào công nhân ở Viễn Đông”. Tháng 5, La Vie Ouvrière đăng tiếp bài “Cách mạng Nga và các dân tộc thuộc địa”, còn tờ Le Paria mà Người từng gây dựng ở Paris in bài “Đoàn kết giai cấp”. Người còn có bài “Phụ nữ phương Đông” trên tạp chí tiếng Nga Rabốtnhitxa, tức Người nữ công nhân.\n\nNhư vậy, từ Mátxcơva, Người vẫn giữ sợi dây liên lạc với bạn đọc Pháp, đồng thời bắt đầu có tiếng nói trên báo chí Xô-viết. Đề tài xuyên suốt vẫn là một: tình cảnh của những người lao động ở phương Đông và ở các thuộc địa. Bài “Lênin và các dân tộc thuộc địa” nằm giữa dòng chảy ấy. Nó giải thích, bằng những lời giản dị, vì sao một người con của xứ An Nam xa xôi lại có mặt ở nước Nga trong mùa đông lịch sử năm ấy.","doc":9},{"loai":"ban_co_biet","text":"Ngày Pravda ra số đầu tiên, 5/5/1912, về sau được chọn làm Ngày Báo chí ở Liên Xô.","nguon_ten":"Bách khoa toàn thư Britannica, mục Pravda","doc":10},{"loai":"doan","tieu_de":"Tiếng vọng qua ba mươi sáu năm","text":"Bài báo năm 1924 mở đầu cho một mạch viết về Lênin kéo dài suốt cuộc đời Hồ Chí Minh. Tháng 4/1960, nhân kỷ niệm 90 năm ngày sinh Lênin, Chủ tịch Hồ Chí Minh viết bài “Con đường dẫn tôi đến chủ nghĩa Lênin” cho tạp chí Liên Xô Các vấn đề phương Đông. Ở đó, Người kể lại lần đầu đọc bản luận cương của Lênin ở Paris năm 1920, với những xúc động chưa bao giờ phai.\n\nĐặt hai bài viết cạnh nhau, ta thấy một sợi chỉ xuyên suốt ba mươi sáu năm. Năm 1924, người thanh niên Nguyễn Ái Quốc viết về Lênin nhân danh những người dân thuộc địa chưa từng biết mặt Lênin. Năm 1960, Chủ tịch nước Việt Nam Dân chủ Cộng hòa viết về Lênin nhân danh một dân tộc đã giành được độc lập ở miền Bắc và đang đấu tranh để thống nhất đất nước. Lời tri ân năm nào đã trở thành sự nghiệp của cả một dân tộc.","doc":11},{"loai":"trich","text":"Luận cương của Lênin làm cho tôi rất cảm động, phấn khởi, sáng tỏ, tin tưởng biết bao! Tôi vui mừng đến phát khóc lên. Ngồi một mình trong buồng mà tôi nói to lên như đang nói trước quần chúng đông đảo: “Hỡi đồng bào bị đọa đày đau khổ! Đây là cái cần thiết cho chúng ta, đây là con đường giải phóng chúng ta!”","nguoi":"Hồ Chí Minh","nguon_ten":"“Con đường dẫn tôi đến chủ nghĩa Lênin”, 4/1960 – Hồ Chí Minh Toàn tập, tập 12, NXB Chính trị quốc gia – Sự thật, 2011","doc":12},{"loai":"anh","src":"textures/bang_w/G08_8_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bài báo \"Lênin và các dân tộc thuộc địa\", 1924”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngày nay, bản tiếng Việt của bài “Lênin và các dân tộc thuộc địa” được in trong Hồ Chí Minh Toàn tập, tập 1, Nhà xuất bản Chính trị quốc gia – Sự thật, năm 2011, trang 256 – 257. Bảo tàng Hồ Chí Minh giới thiệu bài báo như một tư liệu thể hiện sâu sắc tình cảm của nhân dân các nước thuộc địa đối với Lênin, và đường lối của Lênin về vấn đề dân tộc, thuộc địa. Hình chụp trang báo, thuộc phạm vi công cộng, là tấm ảnh khách tham quan thấy ở bảng này.\n\nĐứng trước bảng trong không gian phục dựng Quảng trường Đỏ, khách tham quan có thể hình dung ngày 27/1/1924 từ hai phía. Bên ngoài là dòng người đội tuyết tiễn đưa Lênin tới lăng gỗ bên tường Kremli. Còn trên trang báo là tiếng nói của những dân tộc ở rất xa, được một người Việt Nam cất lên giữa lòng nước Nga. Hai hình ảnh ấy bổ sung cho nhau, làm nên một ngày không thể nào quên trong cuộc đời Nguyễn Ái Quốc.","doc":13}],"nguon":["Bảo tàng Hồ Chí Minh – Bài viết của Nguyễn Ái Quốc, nhan đề Lênin và các dân tộc thuộc địa, đăng trên báo Pravđa của Liên Xô: https://baotanghochiminh.vn/bai-viet-cua-nguyen-ai-quoc-nhan-de-lenin-va-cac-dan-toc-thuoc-dia-dang-tren-bao-pravda-cua-lien-xo.htm","Hồ Chí Minh Toàn tập, tập 1 và tập 12, NXB Chính trị quốc gia – Sự thật, 2011","Hồ Chí Minh – Biên niên tiểu sử, tập 1 (1890 – 1929), NXB Chính trị quốc gia – các mục tháng 1 đến tháng 5/1924","Bách khoa toàn thư Britannica – các mục Vladimir Lenin, Pravda, Benin"],"doc":[{"t":"Trên trang báo Pravda ngày tang lễ: lời tiễn biệt Lênin của một người dân thuộc địa. Ngày 27/1/1924, ngày Mátxcơva đưa linh cữu Lênin ra Quảng trường Đỏ, báo Pravda in bài viết của một người Việt Nam mới đến nước Nga chưa đầy bảy tháng. Người ấy chưa một lần được gặp Lênin. Vậy mà bài báo ngắn của Người lại nói thay cho hàng triệu người ở các thuộc địa, những người cũng chưa từng biết mặt vị lãnh tụ."},{"t":"Buổi sáng ở quán ăn tầng dưới. Một buổi sáng cuối tháng 1/1924 ở Mátxcơva. Về sau, Nguyễn Ái Quốc kể lại: khi ấy mọi người đang ăn bữa sáng tại quán cơm ở tầng dưới khách sạn thì được tin Lênin mất. Ngoảnh lại, họ thấy lá cờ của Xô-viết Mátxcơva đã rủ xuống. Bữa ăn bị bỏ dở, vì không ai còn thấy đói. Lênin từ trần lúc chiều tối ngày 21/1/1924 tại Goócki, ngoại ô Mátxcơva, khi mới 53 tuổi. Với Nguyễn Ái Quốc, tin ấy đến như một mất mát riêng. Người đã mong được gặp tác giả của bản luận cương về vấn đề dân tộc và thuộc địa, văn kiện Người đọc được ở Paris năm 1920 và coi là con đường giải phóng cho dân tộc mình. Nhưng khi Người tới nước Nga mùa hè năm 1923, Lênin đã lâm bệnh nặng. Cuộc gặp ấy mãi mãi không thể diễn ra. Người gọi việc chưa được gặp Lênin là một điều ân hận lớn trong đời mình."},{"t":"Những tháng cuối của Lênin. Khi Nguyễn Ái Quốc đặt chân tới nước Nga, Lênin đã không còn làm việc được. Từ cơn bệnh đầu tiên tháng 5/1922, sức khỏe của Người suy sụp dần. Tháng 3/1923, một cơn bệnh nặng hơn khiến Người mất khả năng nói. Những tháng cuối đời, Lênin sống ở Goócki, một trang viên cách trung tâm Mátxcơva hơn ba mươi ki-lô-mét, dưới sự chăm sóc của vợ là Crúpxcaia và các bác sĩ. Tin Lênin mất được công bố ngày 22/1. Thi hài Người được đưa về Mátxcơva, quàn tại Hội trường Cột để nhân dân vào viếng. Theo Biên niên tiểu sử, ngày 23/1/1924, Nguyễn Ái Quốc cùng sinh viên Trường Đại học Phương Đông tham dự lễ tang. Những ngày đứng giữa giá rét của mùa đông năm ấy được kể ở một chuyên đề khác (xem chuyên đề Lăng gỗ tạm của Lênin). Ở đây, ta dõi theo trang viết mà Người gửi tới bạn đọc Liên Xô trong chính những ngày đó, thay cho những người dân thuộc địa chưa từng biết mặt Lênin."},{"t":"Pravda, tờ báo của những ngày tang. Pravda, nghĩa là Sự thật, ra số đầu tiên ngày 5/5/1912 tại Xanh Pêtécbua, với Lênin là một trong những người sáng lập. Sau Cách mạng Tháng Mười, tờ báo chuyển về Mátxcơva cùng chính phủ Xô-viết và trở thành cơ quan ngôn luận trung ương của Đảng Cộng sản (bônsêvích) Nga. Những ngày cuối tháng 1/1924, các trang Pravda tràn ngập tin tức, lời điếu và hồi ức về Lênin. Giữa những trang ấy, ngày 27/1/1924, đúng ngày an táng, xuất hiện bài “Lênin và các dân tộc thuộc địa” ký tên Nguyễn Ái Quốc. Người viết mới đến nước Nga chưa đầy bảy tháng, và là một cái tên còn xa lạ với phần lớn bạn đọc Liên Xô. Việc cơ quan ngôn luận của Đảng đăng bài của Người đúng ngày ấy cho thấy tiếng nói của các dân tộc thuộc địa được coi là một phần trong lời tiễn biệt Lênin. Bài báo in bằng tiếng Nga. Bản tiếng Việt về sau được đưa vào Hồ Chí Minh Toàn tập, tập 1."},{"t":"Từ An Nam đến Đahômây. Bài báo mở ra bằng một hình ảnh trải rộng khắp địa cầu. Người viết rằng từ những người nông dân An Nam đến người dân săn bắn trong các rừng Đahômây, họ đều đã thầm nghe nói rằng ở một góc trời xa xăm có một dân tộc đã đánh đuổi được bọn chủ bóc lột, đang tự quản lý lấy đất nước mình. Và trong những người dũng cảm của dân tộc ấy, người dũng cảm nhất là Lênin. Đahômây là thuộc địa của Pháp ở Tây Phi. Đặt An Nam và Đahômây cạnh nhau, người viết nhắc bạn đọc Nga rằng đế quốc thực dân Pháp trải dài từ châu Á sang châu Phi, và những người bị áp bức ở hai đầu thế giới ấy có chung một cảnh ngộ. Hai chữ “thầm nghe” rất đắt: nó gợi cảnh tin tức về nước Nga được truyền đi khẽ khàng, như một điều bí mật, ở những nơi chính quyền thực dân không muốn người dân biết. Nối những người cùng khổ ở nhiều châu lục lại với nhau cũng là điều Nguyễn Ái Quốc đã làm ở Paris, khi cùng những người bạn từ các thuộc địa Pháp ở châu Phi và vùng biển Caribê lập Hội Liên hiệp thuộc địa năm 1921."},{"t":"Bạn có biết? Đahômây, vùng đất được nhắc tới trong bài báo, giành độc lập từ Pháp năm 1960 và từ năm 1975 đổi tên thành Bênanh."},{"t":"Người muốn giải phóng các dân tộc khác. Bài báo viết tiếp: những người dân ấy còn biết rằng vị lãnh tụ kia, sau khi giải phóng nhân dân mình, còn muốn giải phóng các dân tộc khác. Lênin đã kêu gọi các dân tộc da trắng giúp đỡ các dân tộc da vàng và da đen thoát khỏi ách thực dân, và đã vạch ra một cương lĩnh cụ thể cho cuộc đấu tranh ấy. Ý tưởng ấy không phải điều Nguyễn Ái Quốc mới biết ở Mátxcơva. Tháng 7/1920, tại Paris, Người đọc bản Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của Lênin trên báo L'Humanité. Bản luận cương đòi hỏi các đảng cộng sản phải trực tiếp ủng hộ phong trào giải phóng ở các nước thuộc địa, gắn cách mạng ở chính quốc với cuộc đấu tranh của các dân tộc bị áp bức. Với người thanh niên yêu nước khi ấy, đó là lời khẳng định rõ ràng rằng các dân tộc thuộc địa không đứng ngoài cuộc. Bài báo năm 1924 vì thế là lời tri ân của một người đã tìm thấy con đường từ chính những trang luận cương ấy."},{"t":"Khi còn sống, Người là người cha, thầy học, đồng chí và cố vấn của chúng ta. Ngày nay, Người là ngôi sao sáng chỉ đường cho chúng ta đi tới cách mạng xã hội. — Nguyễn Ái Quốc (viết về Lênin)"},{"t":"Bốn danh xưng trong một câu văn. Câu văn ấy xếp bốn danh xưng theo một trật tự rất gần với cách cảm của người phương Đông: người cha, thầy học, đồng chí, cố vấn. Trong văn hóa Việt Nam, cha và thầy là hai bậc được kính trọng hàng đầu. Đặt Lênin vào vị trí ấy là cách người viết bày tỏ lòng biết ơn sâu sắc nhất. Ngay sau đó là chữ đồng chí, chữ của những người cùng chiến đấu, và chữ cố vấn, người chỉ ra con đường. Tình cảm và lý trí đi liền nhau trong một câu văn ngắn. Hình ảnh ngôi sao sáng chỉ đường cũng mang một ý nghĩa đặc biệt. Người đã mất, nhưng con đường Người vạch ra vẫn còn đó cho những ai muốn đi. Bài báo khẳng định: Lênin bất diệt sẽ sống mãi trong sự nghiệp của những người bị áp bức. Với người viết, đó không phải là một lời điếu văn theo khuôn mẫu. Đó là lời hứa của một người đã chọn con đường ấy cho mình, và hơn hai mươi năm sau sẽ cùng dân tộc mình đi tới ngày độc lập 2/9/1945."},{"t":"Một ngòi bút không nghỉ. Bài báo trên Pravda chỉ là một trong rất nhiều trang viết của Nguyễn Ái Quốc ở Mátxcơva. Ngay tháng 1/1924, báo L'Humanité ở Paris đăng bài “Phong trào công nhân ở Thổ Nhĩ Kỳ” của Người. Báo La Vie Ouvrière đăng “Tình cảnh nông dân Trung Quốc” và “Phong trào công nhân ở Viễn Đông”. Tháng 5, La Vie Ouvrière đăng tiếp bài “Cách mạng Nga và các dân tộc thuộc địa”, còn tờ Le Paria mà Người từng gây dựng ở Paris in bài “Đoàn kết giai cấp”. Người còn có bài “Phụ nữ phương Đông” trên tạp chí tiếng Nga Rabốtnhitxa, tức Người nữ công nhân. Như vậy, từ Mátxcơva, Người vẫn giữ sợi dây liên lạc với bạn đọc Pháp, đồng thời bắt đầu có tiếng nói trên báo chí Xô-viết. Đề tài xuyên suốt vẫn là một: tình cảnh của những người lao động ở phương Đông và ở các thuộc địa. Bài “Lênin và các dân tộc thuộc địa” nằm giữa dòng chảy ấy. Nó giải thích, bằng những lời giản dị, vì sao một người con của xứ An Nam xa xôi lại có mặt ở nước Nga trong mùa đông lịch sử năm ấy."},{"t":"Bạn có biết? Ngày Pravda ra số đầu tiên, 5/5/1912, về sau được chọn làm Ngày Báo chí ở Liên Xô."},{"t":"Tiếng vọng qua ba mươi sáu năm. Bài báo năm 1924 mở đầu cho một mạch viết về Lênin kéo dài suốt cuộc đời Hồ Chí Minh. Tháng 4/1960, nhân kỷ niệm 90 năm ngày sinh Lênin, Chủ tịch Hồ Chí Minh viết bài “Con đường dẫn tôi đến chủ nghĩa Lênin” cho tạp chí Liên Xô Các vấn đề phương Đông. Ở đó, Người kể lại lần đầu đọc bản luận cương của Lênin ở Paris năm 1920, với những xúc động chưa bao giờ phai. Đặt hai bài viết cạnh nhau, ta thấy một sợi chỉ xuyên suốt ba mươi sáu năm. Năm 1924, người thanh niên Nguyễn Ái Quốc viết về Lênin nhân danh những người dân thuộc địa chưa từng biết mặt Lênin. Năm 1960, Chủ tịch nước Việt Nam Dân chủ Cộng hòa viết về Lênin nhân danh một dân tộc đã giành được độc lập ở miền Bắc và đang đấu tranh để thống nhất đất nước. Lời tri ân năm nào đã trở thành sự nghiệp của cả một dân tộc."},{"t":"Luận cương của Lênin làm cho tôi rất cảm động, phấn khởi, sáng tỏ, tin tưởng biết bao! Tôi vui mừng đến phát khóc lên. Ngồi một mình trong buồng mà tôi nói to lên như đang nói trước quần chúng đông đảo: “Hỡi đồng bào bị đọa đày đau khổ! Đây là cái cần thiết cho chúng ta, đây là con đường giải phóng chúng ta!” — Hồ Chí Minh"},{"t":"Dấu tích hôm nay. Ngày nay, bản tiếng Việt của bài “Lênin và các dân tộc thuộc địa” được in trong Hồ Chí Minh Toàn tập, tập 1, Nhà xuất bản Chính trị quốc gia – Sự thật, năm 2011, trang 256 – 257. Bảo tàng Hồ Chí Minh giới thiệu bài báo như một tư liệu thể hiện sâu sắc tình cảm của nhân dân các nước thuộc địa đối với Lênin, và đường lối của Lênin về vấn đề dân tộc, thuộc địa. Hình chụp trang báo, thuộc phạm vi công cộng, là tấm ảnh khách tham quan thấy ở bảng này. Đứng trước bảng trong không gian phục dựng Quảng trường Đỏ, khách tham quan có thể hình dung ngày 27/1/1924 từ hai phía. Bên ngoài là dòng người đội tuyết tiễn đưa Lênin tới lăng gỗ bên tường Kremli. Còn trên trang báo là tiếng nói của những dân tộc ở rất xa, được một người Việt Nam cất lên giữa lòng nước Nga. Hai hình ảnh ấy bổ sung cho nhau, làm nên một ngày không thể nào quên trong cuộc đời Nguyễn Ái Quốc."}],"so_chu":1902},{"i":9,"tieu_de_bang":"Lăng gỗ tạm của Lênin (1/1924)","tieu_de":"Lăng gỗ dựng trên đất băng: Quảng trường Đỏ tháng Giêng năm 1924","sapo":"Tháng Giêng năm 1924, mặt đất Mátxcơva đóng băng cứng như đá, vậy mà chỉ trong vài ngày, một công trình bằng gỗ đã kịp dựng lên sát tường thành Kremli. Đó là nơi an nghỉ đầu tiên của Lênin, tiền thân của tòa lăng đá mà ngày nay ai đến Quảng trường Đỏ cũng nhìn thấy. Trong dòng người đội rét đến viếng những ngày ấy có một thanh niên châu Á mặc không đủ ấm: Nguyễn Ái Quốc.","bia":{"src":"textures/bai/G08_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Bốn giờ chiều, cả một đất nước lặng đi","text":"Chiều 27/1/1924, Quảng trường Đỏ chìm trong giá rét dưới 30 độ âm. Dọc quảng trường và các phố dẫn tới, người ta đốt những đống lửa lớn để dòng người đứng chờ có chỗ hơ tay. Đúng bốn giờ chiều, linh cữu Lênin được đưa vào một công trình bằng gỗ vừa dựng xong sát tường thành Kremli, ngay trước tháp Thượng viện. Cùng lúc ấy, còi nhà máy, còi tàu hỏa trên khắp nước Nga Xô-viết đồng loạt rú lên. Máy móc ngừng chạy, tàu xe dừng bánh, và cả đất nước đứng lặng trong năm phút.\n\nCông trình bằng gỗ đón linh cữu hôm ấy là lăng tạm đầu tiên của Lênin. Nó chỉ tồn tại vài tháng, nhưng hình khối vuông vức với phần mái xếp bậc của nó đã trở thành khuôn mẫu cho tòa lăng đá mà khách tham quan ngày nay vẫn thấy trên Quảng trường Đỏ. Góc gian trưng bày này dựng lại chính chiếc lăng gỗ ấy, giữa khung cảnh tuyết phủ và những lá cờ viền tang của mùa đông năm 1924, khi người thanh niên Nguyễn Ái Quốc có mặt ở Mátxcơva.","doc":1},{"loai":"doan","tieu_de":"Từ Goócki về Hội trường Cột","text":"Lênin từ trần lúc 18 giờ 50 phút ngày 21/1/1924 tại Goócki, một trang viên ở ngoại ô phía nam Mátxcơva. Người về đây chữa bệnh sau nhiều cơn đột quỵ kể từ năm 1922. Ngày 23/1, một đoàn tàu đặc biệt đưa linh cữu về ga Paveletsky. Từ nhà ga, quan tài được khiêng trên vai, đi bộ qua các phố phủ tuyết tới Nhà Công đoàn ở trung tâm thành phố.\n\nTại Hội trường Cột, gian đại sảnh với hàng cột trắng xây từ cuối thế kỷ XVIII, linh cữu được quàn suốt bốn ngày đêm. Hàng trăm nghìn người từ Mátxcơva và các tỉnh đổ về, xếp thành những hàng dài dằng dặc trên các đường phố, nhiều người đứng chờ suốt đêm trong giá lạnh. Theo Hồ Chí Minh – Biên niên tiểu sử, ngay ngày 23/1, Nguyễn Ái Quốc cùng một số sinh viên Trường Đại học Phương Đông đã tham dự lễ tang. Khi ấy, Người mới đặt chân tới nước Nga Xô-viết được gần bảy tháng và chưa có dịp gặp mặt vị lãnh tụ mà Người hằng kính phục.","doc":2},{"loai":"anh","src":"textures/bang_w/G08_9_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lăng gỗ tạm của Lênin (1/1924)”, nhìn từ xa."},{"loai":"doan","tieu_de":"Một công trình dựng trong chưa đầy bốn ngày","text":"Ngày 23/1, hai ngày sau khi Lênin mất, kiến trúc sư Alếchxây Sơxuxép (Alexey Shchusev) nhận nhiệm vụ thiết kế nơi đặt linh cữu trên Quảng trường Đỏ. Thời gian gấp gáp chưa từng có: lễ an táng đã định vào ngày 27/1. Trong khi đó, mặt đất Mátxcơva giữa mùa đông đóng băng sâu, việc đào hầm đặt linh cữu vô cùng vất vả. Những người thợ phải làm việc cả ngày lẫn đêm giữa trời rét buốt.\n\nPhương án Sơxuxép chọn giản dị mà trang nghiêm: một khối gỗ vuông vức, bên trên là phần mái xếp thành nhiều bậc thu nhỏ dần, như một kim tự tháp bậc thang bị cắt ngọn. Không cột trụ, không tượng, không hoa văn cầu kỳ; chính hình khối nói lên sự tưởng niệm. Công trình kịp hoàn thành đúng ngày 27/1, cùng ngày linh cữu được đưa vào. Giữa nền tuyết trắng, khối gỗ nằm sát chân bức tường gạch đỏ có răng cưa hình đuôi én của Kremli, trước tháp Thượng viện, nơi phía sau bức tường là tòa nhà Lênin từng làm việc những năm cuối đời.","doc":3},{"loai":"ban_co_biet","text":"Sơxuxép là kiến trúc sư duy nhất thiết kế cả ba phiên bản lăng Lênin: lăng gỗ tạm tháng 1/1924, lăng gỗ thứ hai mở cửa ngày 1/8/1924 và lăng đá hoàn thành tháng 10/1930. Ông cũng là tác giả nhà ga Kazansky nổi tiếng ở Mátxcơva.","nguon_ten":"Lenin's Mausoleum – Wikipedia tiếng Anh; Kazansky railway terminal – Wikipedia tiếng Anh","doc":4},{"loai":"doan","tieu_de":"Người thanh niên đội rét","text":"Trong những ngày tang lễ, Nguyễn Ái Quốc có mặt giữa dòng người đến viếng. Cuốn sách Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch của Trần Dân Tiên kể rằng Người mặc không đủ ấm cho mùa đông nước Nga. Vậy mà Người vẫn đội cái rét dưới 30 độ âm đi viếng Lênin. Khi trở về, các ngón tay và tai Người đã bị cóng.\n\nNgười con xứ Nghệ đã qua những mùa đông ở London và Paris, nhưng cái rét của Mátxcơva tháng Giêng năm ấy là thử thách hoàn toàn khác. Chi tiết nhỏ trong sách của Trần Dân Tiên không nhằm kể về sự khổ sở. Nó cho thấy tình cảm của Người đối với Lênin, người mà bản Luận cương về vấn đề dân tộc và thuộc địa đã chỉ cho Người con đường cứu nước từ mùa hè năm 1920 ở Paris. Cũng trong ngày 27/1, báo Pravda đăng bài viết của Người tiễn biệt Lênin (xem chuyên đề Bài báo “Lênin và các dân tộc thuộc địa”, 1924). Người thanh niên ba mươi ba tuổi vừa đứng trong giá rét trước linh cữu, vừa góp tiếng nói của các dân tộc thuộc địa vào lời tiễn biệt của cả thế giới.","doc":5},{"loai":"anh","src":"textures/ht/ht_anh_article_lenin_and_the_colonial_peoples_by_nguyen.jpg","chu_thich":"Bài báo “Lênin và các dân tộc thuộc địa” của Nguyễn Ái Quốc trên báo Pravda ngày 27/1/1924, đúng ngày linh cữu Lênin được đưa vào lăng gỗ tạm trên Quảng trường Đỏ.","credit":"Ảnh: Nguyen Ai Quoc (Ho Chi Minh) · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Hơn một trăm nghìn người trong sáu tuần","text":"Tang lễ kết thúc, nhưng dòng người không dừng lại. Lăng gỗ tạm tiếp tục mở cửa, và trong sáu tuần sau đó đã có hơn một trăm nghìn người đến viếng. Lúc này, một câu hỏi lớn được đặt ra: giữ gìn thi hài Lênin lâu dài hay an táng vĩnh viễn. Ngay sau khi Lênin mất, nhà giải phẫu bệnh học Alếchxây Abơrikôxốp (Alexei Abrikosov) đã ướp thi hài, nhưng chỉ đủ cho những ngày quàn và lễ tang.\n\nTừ mùa xuân năm 1924, hai nhà khoa học Vlađimia Vôrôbiốp (Vladimir Vorobiov) và Bôrit Dơbácxki (Boris Zbarsky) được giao tìm một phương pháp bảo quản lâu dài chưa từng có tiền lệ. Chiếc lăng gỗ đầu tiên, vốn chỉ được dựng để kịp một lễ tang, không còn phù hợp. Đến cuối tháng 5/1924, Sơxuxép đã thay nó bằng một lăng gỗ thứ hai lớn hơn, công phu hơn. Ngày 1/8/1924, lăng mới mở cửa đón khách. Khi ấy, Nguyễn Ái Quốc vẫn còn ở Mátxcơva và đang kiên trì đề nghị Quốc tế Cộng sản cho sang phương Đông hoạt động.","doc":6},{"loai":"anh","src":"textures/bang_w/G08_9_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lăng gỗ tạm của Lênin (1/1924)”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Từ gỗ đến đá","text":"Lăng gỗ thứ hai đứng trên Quảng trường Đỏ khoảng năm năm. Năm 1929, chính quyền Xô-viết quyết định xây một lăng vĩnh cửu bằng đá, vẫn giao cho Sơxuxép thiết kế. Sau mười sáu tháng thi công, tháng 10/1930, tòa lăng mới hoàn thành. Vật liệu gồm đá cẩm thạch, đá pocfia, đá granit và đá labrađorit. Lăng đá cao hơn lăng gỗ ba mét; thể tích bên ngoài tăng khoảng 4,5 lần, thể tích bên trong tăng khoảng 12 lần, tổng trọng lượng khoảng 10.000 tấn.\n\nĐiều đáng chú ý là Sơxuxép vẫn giữ ý tưởng của chiếc lăng gỗ đầu tiên: một khối vuông vững chãi, bên trên là những bậc thu nhỏ dần. Hình khối giản dị nghĩ ra trong mấy ngày giá rét tháng Giêng năm 1924 vì thế được tạc vào đá. Phía trên lăng có khán đài, nơi các nhà lãnh đạo Liên Xô đứng duyệt những cuộc diễu binh, diễu hành trên Quảng trường Đỏ suốt nhiều thập kỷ. Từ năm 1953 đến năm 1961, thi hài Stalin cũng được đặt tại đây, trước khi được chuyển ra an táng bên chân tường Kremli.","doc":7},{"loai":"doan","tieu_de":"Trạm gác số 1 và những năm chiến tranh","text":"Ngay từ những ngày đầu, trước lăng Lênin đã có lính gác danh dự. Trạm gác ấy về sau được gọi là Trạm số 1, vị trí trang trọng bậc nhất trong các trạm gác nghi lễ của Liên Xô. Nghi thức đổi gác với những bước chân đều tăm tắp trên mặt đá lát từng là cảnh tượng mà khách đến Quảng trường Đỏ chờ xem.\n\nTrong Chiến tranh thế giới thứ hai, khi quân đội phát xít Đức tiến về phía Mátxcơva, thi hài Lênin được bí mật sơ tán về thành phố Tyumen ở Xibia, đến năm 1945 mới được đưa trở lại. Tòa lăng vẫn đứng đó, được ngụy trang để tránh bom. Sáng 7/11/1941, từ khán đài trên lăng, các nhà lãnh đạo Liên Xô duyệt cuộc diễu binh kỷ niệm Cách mạng Tháng Mười; nhiều đơn vị đi qua Quảng trường Đỏ rồi tiến thẳng ra mặt trận. Năm 1993, trạm gác trước lăng Lênin thôi hoạt động; bốn năm sau, Trạm số 1 được lập lại tại Mộ Chiến sĩ vô danh bên vườn Alếchxanđơ. Từ một khối gỗ dựng vội giữa mùa đông, công trình đã trở thành chứng nhân của gần trọn thế kỷ XX nước Nga.","doc":8},{"loai":"ban_co_biet","text":"Gần nửa thế kỷ sau mùa đông năm 1924, Lăng Chủ tịch Hồ Chí Minh trên Quảng trường Ba Đình, nơi Người đọc Tuyên ngôn Độc lập ngày 2/9/1945, được xây dựng với sự giúp đỡ của các chuyên gia Liên Xô: khởi công ngày 2/9/1973 và khánh thành ngày 29/8/1975.","nguon_ten":"Ban Quản lý Lăng Chủ tịch Hồ Chí Minh","doc":9},{"loai":"anh","src":"textures/bang_w/G08_9_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lăng gỗ tạm của Lênin (1/1924)”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Chiếc lăng gỗ đầu tiên không còn; hậu thế chỉ biết đến nó qua ảnh chụp và bản vẽ của thời ấy. Nhưng những gì gắn với tháng Giêng năm 1924 vẫn có thể lần theo. Tòa lăng đá của Sơxuxép vẫn đứng trước tháp Thượng viện, thuộc quần thể Điện Kremli và Quảng trường Đỏ, được UNESCO ghi vào Danh mục Di sản thế giới năm 1990. Lăng mở cửa đón khách vào một số buổi sáng trong tuần. Khách lặng lẽ đi thành hàng qua gian đặt thi hài, rồi men theo dãy mộ các nhà hoạt động Xô-viết bên chân tường Kremli.\n\nHội trường Cột trong Nhà Công đoàn vẫn là nơi diễn ra nhiều sự kiện lớn của Mátxcơva. Ở ga Paveletsky, đầu máy và toa tàu từng chở linh cữu Lênin về thủ đô được trưng bày trong một nhà bảo tàng riêng. Trang viên Goócki nay là khu bảo tàng mang tên Lênin. Trong gian trưng bày này, chiếc lăng gỗ được phục dựng theo tư liệu lịch sử, đặt sát tường thành, để khách tham quan hình dung khoảnh khắc người thanh niên Nguyễn Ái Quốc đứng giữa tuyết lạnh tiễn biệt Lênin.","doc":10}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia (các mục tháng 1/1924)","Trần Dân Tiên, Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch","Lenin's Mausoleum – Wikipedia tiếng Anh, https://en.wikipedia.org/wiki/Lenin%27s_Mausoleum","Death and funeral of Vladimir Lenin – Wikipedia tiếng Anh","UNESCO – Trung tâm Di sản thế giới: Kremlin and Red Square, Moscow","Ban Quản lý Lăng Chủ tịch Hồ Chí Minh"],"doc":[{"t":"Lăng gỗ dựng trên đất băng: Quảng trường Đỏ tháng Giêng năm 1924. Tháng Giêng năm 1924, mặt đất Mátxcơva đóng băng cứng như đá, vậy mà chỉ trong vài ngày, một công trình bằng gỗ đã kịp dựng lên sát tường thành Kremli. Đó là nơi an nghỉ đầu tiên của Lênin, tiền thân của tòa lăng đá mà ngày nay ai đến Quảng trường Đỏ cũng nhìn thấy. Trong dòng người đội rét đến viếng những ngày ấy có một thanh niên châu Á mặc không đủ ấm: Nguyễn Ái Quốc."},{"t":"Bốn giờ chiều, cả một đất nước lặng đi. Chiều 27/1/1924, Quảng trường Đỏ chìm trong giá rét dưới 30 độ âm. Dọc quảng trường và các phố dẫn tới, người ta đốt những đống lửa lớn để dòng người đứng chờ có chỗ hơ tay. Đúng bốn giờ chiều, linh cữu Lênin được đưa vào một công trình bằng gỗ vừa dựng xong sát tường thành Kremli, ngay trước tháp Thượng viện. Cùng lúc ấy, còi nhà máy, còi tàu hỏa trên khắp nước Nga Xô-viết đồng loạt rú lên. Máy móc ngừng chạy, tàu xe dừng bánh, và cả đất nước đứng lặng trong năm phút. Công trình bằng gỗ đón linh cữu hôm ấy là lăng tạm đầu tiên của Lênin. Nó chỉ tồn tại vài tháng, nhưng hình khối vuông vức với phần mái xếp bậc của nó đã trở thành khuôn mẫu cho tòa lăng đá mà khách tham quan ngày nay vẫn thấy trên Quảng trường Đỏ. Góc gian trưng bày này dựng lại chính chiếc lăng gỗ ấy, giữa khung cảnh tuyết phủ và những lá cờ viền tang của mùa đông năm 1924, khi người thanh niên Nguyễn Ái Quốc có mặt ở Mátxcơva."},{"t":"Từ Goócki về Hội trường Cột. Lênin từ trần lúc 18 giờ 50 phút ngày 21/1/1924 tại Goócki, một trang viên ở ngoại ô phía nam Mátxcơva. Người về đây chữa bệnh sau nhiều cơn đột quỵ kể từ năm 1922. Ngày 23/1, một đoàn tàu đặc biệt đưa linh cữu về ga Paveletsky. Từ nhà ga, quan tài được khiêng trên vai, đi bộ qua các phố phủ tuyết tới Nhà Công đoàn ở trung tâm thành phố. Tại Hội trường Cột, gian đại sảnh với hàng cột trắng xây từ cuối thế kỷ XVIII, linh cữu được quàn suốt bốn ngày đêm. Hàng trăm nghìn người từ Mátxcơva và các tỉnh đổ về, xếp thành những hàng dài dằng dặc trên các đường phố, nhiều người đứng chờ suốt đêm trong giá lạnh. Theo Hồ Chí Minh – Biên niên tiểu sử, ngay ngày 23/1, Nguyễn Ái Quốc cùng một số sinh viên Trường Đại học Phương Đông đã tham dự lễ tang. Khi ấy, Người mới đặt chân tới nước Nga Xô-viết được gần bảy tháng và chưa có dịp gặp mặt vị lãnh tụ mà Người hằng kính phục."},{"t":"Một công trình dựng trong chưa đầy bốn ngày. Ngày 23/1, hai ngày sau khi Lênin mất, kiến trúc sư Alếchxây Sơxuxép (Alexey Shchusev) nhận nhiệm vụ thiết kế nơi đặt linh cữu trên Quảng trường Đỏ. Thời gian gấp gáp chưa từng có: lễ an táng đã định vào ngày 27/1. Trong khi đó, mặt đất Mátxcơva giữa mùa đông đóng băng sâu, việc đào hầm đặt linh cữu vô cùng vất vả. Những người thợ phải làm việc cả ngày lẫn đêm giữa trời rét buốt. Phương án Sơxuxép chọn giản dị mà trang nghiêm: một khối gỗ vuông vức, bên trên là phần mái xếp thành nhiều bậc thu nhỏ dần, như một kim tự tháp bậc thang bị cắt ngọn. Không cột trụ, không tượng, không hoa văn cầu kỳ; chính hình khối nói lên sự tưởng niệm. Công trình kịp hoàn thành đúng ngày 27/1, cùng ngày linh cữu được đưa vào. Giữa nền tuyết trắng, khối gỗ nằm sát chân bức tường gạch đỏ có răng cưa hình đuôi én của Kremli, trước tháp Thượng viện, nơi phía sau bức tường là tòa nhà Lênin từng làm việc những năm cuối đời."},{"t":"Bạn có biết? Sơxuxép là kiến trúc sư duy nhất thiết kế cả ba phiên bản lăng Lênin: lăng gỗ tạm tháng 1/1924, lăng gỗ thứ hai mở cửa ngày 1/8/1924 và lăng đá hoàn thành tháng 10/1930. Ông cũng là tác giả nhà ga Kazansky nổi tiếng ở Mátxcơva."},{"t":"Người thanh niên đội rét. Trong những ngày tang lễ, Nguyễn Ái Quốc có mặt giữa dòng người đến viếng. Cuốn sách Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch của Trần Dân Tiên kể rằng Người mặc không đủ ấm cho mùa đông nước Nga. Vậy mà Người vẫn đội cái rét dưới 30 độ âm đi viếng Lênin. Khi trở về, các ngón tay và tai Người đã bị cóng. Người con xứ Nghệ đã qua những mùa đông ở London và Paris, nhưng cái rét của Mátxcơva tháng Giêng năm ấy là thử thách hoàn toàn khác. Chi tiết nhỏ trong sách của Trần Dân Tiên không nhằm kể về sự khổ sở. Nó cho thấy tình cảm của Người đối với Lênin, người mà bản Luận cương về vấn đề dân tộc và thuộc địa đã chỉ cho Người con đường cứu nước từ mùa hè năm 1920 ở Paris. Cũng trong ngày 27/1, báo Pravda đăng bài viết của Người tiễn biệt Lênin (xem chuyên đề Bài báo “Lênin và các dân tộc thuộc địa”, 1924). Người thanh niên ba mươi ba tuổi vừa đứng trong giá rét trước linh cữu, vừa góp tiếng nói của các dân tộc thuộc địa vào lời tiễn biệt của cả thế giới."},{"t":"Hơn một trăm nghìn người trong sáu tuần. Tang lễ kết thúc, nhưng dòng người không dừng lại. Lăng gỗ tạm tiếp tục mở cửa, và trong sáu tuần sau đó đã có hơn một trăm nghìn người đến viếng. Lúc này, một câu hỏi lớn được đặt ra: giữ gìn thi hài Lênin lâu dài hay an táng vĩnh viễn. Ngay sau khi Lênin mất, nhà giải phẫu bệnh học Alếchxây Abơrikôxốp (Alexei Abrikosov) đã ướp thi hài, nhưng chỉ đủ cho những ngày quàn và lễ tang. Từ mùa xuân năm 1924, hai nhà khoa học Vlađimia Vôrôbiốp (Vladimir Vorobiov) và Bôrit Dơbácxki (Boris Zbarsky) được giao tìm một phương pháp bảo quản lâu dài chưa từng có tiền lệ. Chiếc lăng gỗ đầu tiên, vốn chỉ được dựng để kịp một lễ tang, không còn phù hợp. Đến cuối tháng 5/1924, Sơxuxép đã thay nó bằng một lăng gỗ thứ hai lớn hơn, công phu hơn. Ngày 1/8/1924, lăng mới mở cửa đón khách. Khi ấy, Nguyễn Ái Quốc vẫn còn ở Mátxcơva và đang kiên trì đề nghị Quốc tế Cộng sản cho sang phương Đông hoạt động."},{"t":"Từ gỗ đến đá. Lăng gỗ thứ hai đứng trên Quảng trường Đỏ khoảng năm năm. Năm 1929, chính quyền Xô-viết quyết định xây một lăng vĩnh cửu bằng đá, vẫn giao cho Sơxuxép thiết kế. Sau mười sáu tháng thi công, tháng 10/1930, tòa lăng mới hoàn thành. Vật liệu gồm đá cẩm thạch, đá pocfia, đá granit và đá labrađorit. Lăng đá cao hơn lăng gỗ ba mét; thể tích bên ngoài tăng khoảng 4,5 lần, thể tích bên trong tăng khoảng 12 lần, tổng trọng lượng khoảng 10.000 tấn. Điều đáng chú ý là Sơxuxép vẫn giữ ý tưởng của chiếc lăng gỗ đầu tiên: một khối vuông vững chãi, bên trên là những bậc thu nhỏ dần. Hình khối giản dị nghĩ ra trong mấy ngày giá rét tháng Giêng năm 1924 vì thế được tạc vào đá. Phía trên lăng có khán đài, nơi các nhà lãnh đạo Liên Xô đứng duyệt những cuộc diễu binh, diễu hành trên Quảng trường Đỏ suốt nhiều thập kỷ. Từ năm 1953 đến năm 1961, thi hài Stalin cũng được đặt tại đây, trước khi được chuyển ra an táng bên chân tường Kremli."},{"t":"Trạm gác số 1 và những năm chiến tranh. Ngay từ những ngày đầu, trước lăng Lênin đã có lính gác danh dự. Trạm gác ấy về sau được gọi là Trạm số 1, vị trí trang trọng bậc nhất trong các trạm gác nghi lễ của Liên Xô. Nghi thức đổi gác với những bước chân đều tăm tắp trên mặt đá lát từng là cảnh tượng mà khách đến Quảng trường Đỏ chờ xem. Trong Chiến tranh thế giới thứ hai, khi quân đội phát xít Đức tiến về phía Mátxcơva, thi hài Lênin được bí mật sơ tán về thành phố Tyumen ở Xibia, đến năm 1945 mới được đưa trở lại. Tòa lăng vẫn đứng đó, được ngụy trang để tránh bom. Sáng 7/11/1941, từ khán đài trên lăng, các nhà lãnh đạo Liên Xô duyệt cuộc diễu binh kỷ niệm Cách mạng Tháng Mười; nhiều đơn vị đi qua Quảng trường Đỏ rồi tiến thẳng ra mặt trận. Năm 1993, trạm gác trước lăng Lênin thôi hoạt động; bốn năm sau, Trạm số 1 được lập lại tại Mộ Chiến sĩ vô danh bên vườn Alếchxanđơ. Từ một khối gỗ dựng vội giữa mùa đông, công trình đã trở thành chứng nhân của gần trọn thế kỷ XX nước Nga."},{"t":"Bạn có biết? Gần nửa thế kỷ sau mùa đông năm 1924, Lăng Chủ tịch Hồ Chí Minh trên Quảng trường Ba Đình, nơi Người đọc Tuyên ngôn Độc lập ngày 2/9/1945, được xây dựng với sự giúp đỡ của các chuyên gia Liên Xô: khởi công ngày 2/9/1973 và khánh thành ngày 29/8/1975."},{"t":"Dấu tích hôm nay. Chiếc lăng gỗ đầu tiên không còn; hậu thế chỉ biết đến nó qua ảnh chụp và bản vẽ của thời ấy. Nhưng những gì gắn với tháng Giêng năm 1924 vẫn có thể lần theo. Tòa lăng đá của Sơxuxép vẫn đứng trước tháp Thượng viện, thuộc quần thể Điện Kremli và Quảng trường Đỏ, được UNESCO ghi vào Danh mục Di sản thế giới năm 1990. Lăng mở cửa đón khách vào một số buổi sáng trong tuần. Khách lặng lẽ đi thành hàng qua gian đặt thi hài, rồi men theo dãy mộ các nhà hoạt động Xô-viết bên chân tường Kremli. Hội trường Cột trong Nhà Công đoàn vẫn là nơi diễn ra nhiều sự kiện lớn của Mátxcơva. Ở ga Paveletsky, đầu máy và toa tàu từng chở linh cữu Lênin về thủ đô được trưng bày trong một nhà bảo tàng riêng. Trang viên Goócki nay là khu bảo tàng mang tên Lênin. Trong gian trưng bày này, chiếc lăng gỗ được phục dựng theo tư liệu lịch sử, đặt sát tường thành, để khách tham quan hình dung khoảnh khắc người thanh niên Nguyễn Ái Quốc đứng giữa tuyết lạnh tiễn biệt Lênin."}],"so_chu":1741},{"i":10,"tieu_de_bang":"Tháp Spasskaya","tieu_de":"Tháp Spasskaya: chiếc đồng hồ của Quảng trường Đỏ và con đại bàng chưa kịp thay","sapo":"Hơn năm thế kỷ nay, tháp Spasskaya là cổng chính của Điện Kremli và là chiếc đồng hồ của cả nước Nga. Mùa đông năm 1924, khi Nguyễn Ái Quốc đứng giữa Quảng trường Đỏ, đỉnh tháp vẫn còn con đại bàng hai đầu của các Sa hoàng, còn tầng chuông thì ngân giai điệu Quốc tế ca. Câu chuyện của ngọn tháp là câu chuyện của những lớp thời gian chồng lên nhau.","bia":{"src":"textures/bai/G08_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Cánh cổng phải bỏ mũ khi đi qua","text":"Đứng giữa Quảng trường Đỏ nhìn về phía Kremli, ánh mắt ai cũng dừng lại ở ngọn tháp gạch đỏ vút cao với chiếc đồng hồ lớn trên thân. Đó là tháp Spasskaya, cổng chính và trang trọng nhất trong hai mươi ngọn tháp của tường thành Kremli. Suốt nhiều thế kỷ, qua vòm cổng này, các Sa hoàng ra vào trong những dịp đại lễ, các đoàn rước tôn giáo đi ra quảng trường, sứ thần nước ngoài được đưa vào yết kiến.\n\nTương truyền, từ thế kỷ XVII đã có lệ ai đi qua cổng Spasskaya cũng phải bỏ mũ, người cưỡi ngựa phải xuống dắt bộ, để tỏ lòng tôn kính bức thánh tượng đặt phía trên cổng. Thời Xô-viết, đây vẫn là lối ra vào chính của những đoàn xe chính phủ. Với người Mátxcơva, ngọn tháp là biểu tượng của nhà nước; với khách phương xa, nó là hình ảnh đầu tiên gợi đến nước Nga. Trong gian trưng bày này, tháp Spasskaya hiện lên phía xa, bên bức tường thành đỏ, như trong khung cảnh Quảng trường Đỏ mùa đông năm 1924.","doc":1},{"loai":"doan","tieu_de":"Dấu tay của người thợ Italia","text":"Tháp được dựng năm 1491, dưới thời Đại công tước Ivan III, người thống nhất các vùng đất Nga quanh Mátxcơva. Để xây lại tường thành Kremli bằng gạch thay cho bức tường đá trắng cũ đã xuống cấp, Ivan III mời nhiều kiến trúc sư từ Italia, trung tâm nghệ thuật xây dựng của châu Âu thời Phục hưng. Người thiết kế tháp là Pietro Antonio Solari, một kiến trúc sư đến từ vùng Milan.\n\nPhía trên cổng, những tấm bia đá trắng khắc chữ Latinh và chữ Nga cổ còn ghi lại năm xây dựng và tên người thợ Italia ấy. Ban đầu, tháp chỉ là một khối vuông vững chãi, bên ngoài có cầu bắc qua con hào chạy dọc chân tường. Nó mang tên Frolovskaya, theo tên nhà thờ thánh Frol và Lavr ở gần đó. Solari còn chỉ huy xây nhiều ngọn tháp khác của Kremli. Những bức tường có răng cưa hình đuôi én mà ngày nay trở thành dấu hiệu nhận biết Kremli cũng mang dấu ấn của các thợ Italia thời ấy, gợi nhớ những tòa thành ở miền Bắc Italia.","doc":2},{"loai":"anh","src":"textures/bang_w/G08_10_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Tháp Spasskaya”, nhìn từ xa."},{"loai":"doan","tieu_de":"Mái chóp của thế kỷ XVII và một cái tên mới","text":"Hơn một thế kỷ sau, ngọn tháp mới có dáng vẻ ta thấy hôm nay. Trong những năm 1624 – 1625, kiến trúc sư Nga Bazhen Ogurtsov cùng người thợ đồng hồ người Anh Christopher Galloway xây thêm phần mái chóp nhiều tầng. Những tháp nhọn nhỏ, lan can đá trắng và các chi tiết trang trí công phu mang dáng dấp kiến trúc Gôtích châu Âu. Từ một tháp phòng thủ, Spasskaya trở thành một công trình lộng lẫy, cao vượt hẳn lên trên tường thành.\n\nNăm 1658, Sa hoàng Alếchxây Mikhailôvích ra sắc lệnh đổi tên tháp thành Spasskaya, nghĩa là tháp Đấng Cứu thế. Cái tên gắn với bức thánh tượng Đấng Cứu thế thành Xmôlenxcơ đặt phía trên cổng, nhìn ra Quảng trường Đỏ. Ngày nay, tính cả ngôi sao trên đỉnh, tháp cao khoảng 71 mét, tương đương một tòa nhà hai mươi tầng. Cũng từ thế kỷ XVII, trên đỉnh mái chóp được đặt biểu tượng đại bàng hai đầu của nhà nước Nga. Chính con đại bàng ấy vẫn ngự trên đỉnh tháp trong những tháng Nguyễn Ái Quốc sống ở Mátxcơva, năm 1923 – 1924.","doc":3},{"loai":"doan","tieu_de":"Chiếc đồng hồ của cả nước Nga","text":"Đồng hồ xuất hiện trên tháp từ rất sớm. Christopher Galloway đã lắp một chiếc đồng hồ lớn ngay khi dựng phần mái chóp. Đầu thế kỷ XVIII, Pie Đại đế cho thay bằng một chiếc đồng hồ mua từ Hà Lan. Bộ máy đang chạy hôm nay do hai anh em thợ Butenop chế tạo và lắp đặt trong những năm 1851 – 1852.\n\nBốn mặt số, mỗi mặt có đường kính 6,12 mét, nhìn ra bốn phía; kim phút dài hơn ba mét. Cỗ máy nặng khoảng 25 tấn, chiếm trọn ba tầng bên trong tháp, và suốt nhiều thập kỷ được lên dây bằng tay. Phía trên là tầng chuông, nơi những quả chuông đồng điểm giờ và ngân nhạc, vang khắp Quảng trường Đỏ. Người Nga gọi chiếc đồng hồ bằng một cái tên riêng: kuranty, tức đồng hồ chuông. Hàng chục năm nay, tiếng chuông của nó trên sóng phát thanh và truyền hình báo hiệu thời khắc giao thừa cho cả nước. Với nhiều thế hệ người Nga, tiếng chuông Spasskaya không chỉ là tiếng báo giờ mà là nhịp đập của đất nước.","doc":4},{"loai":"ban_co_biet","text":"Theo các tư liệu về lịch sử Kremli, chiếc đồng hồ Galloway lắp năm 1625 có cách chỉ giờ rất lạ: mặt số tự quay, còn kim thì đứng yên. Mặt số chia theo lối tính giờ cổ của người Nga, đếm riêng giờ ban ngày và giờ ban đêm, nên có tới 17 vạch giờ.","nguon_ten":"Bảo tàng Điện Kremli Mátxcơva","doc":5},{"loai":"doan","tieu_de":"Viên đạn pháo năm 1917 và giai điệu Quốc tế ca","text":"Tháng 11/1917, trong những ngày giao tranh ác liệt ở Mátxcơva giữa lực lượng cách mạng và quân ủng hộ Chính phủ lâm thời, một quả đạn pháo trúng mặt đồng hồ tháp Spasskaya. Kim đồng hồ gãy hỏng, bộ máy ngừng chạy. Năm 1918, sau khi chính phủ Xô-viết dời đô về Mátxcơva và Lênin chuyển vào làm việc trong Kremli, đồng hồ được sửa chữa. Người thợ khóa Nikolai Behrens phục hồi bộ máy. Họa sĩ kiêm nhạc sĩ Mikhail Cheremnykh chỉnh lại hệ thống chuông để ngân giai điệu bài Quốc tế ca và bài hát tang lễ cách mạng “Các anh đã ngã xuống”.\n\nTừ đó, giai điệu Quốc tế ca vang lên từ ngọn tháp vào những giờ nhất định trong ngày. Như vậy, trong những tháng Nguyễn Ái Quốc sống ở Mátxcơva, trên đỉnh tháp là con đại bàng của các Sa hoàng, còn trong tầng chuông là bài ca của những người cộng sản. Năm 1938, chuông thôi chơi nhạc, chỉ còn điểm giờ. Phải đến năm 1996, chuông mới lại ngân nhạc, và từ năm 2000 chơi giai điệu Quốc ca Liên bang Nga.","doc":6},{"loai":"anh","src":"textures/bang_w/G08_10_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Tháp Spasskaya”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Hồng trường trưa ngày 1/5/1924","text":"Với Nguyễn Ái Quốc, Quảng trường Đỏ dưới chân tháp Spasskaya gắn với những ngày đáng nhớ của năm 1924. Tháng Giêng, Người đội rét tiễn đưa Lênin, khi chiếc lăng gỗ tạm được dựng bên tường thành cách ngọn tháp không xa (xem chuyên đề Lăng gỗ tạm của Lênin). Hơn ba tháng sau, quảng trường lại rực cờ đỏ trong ngày Quốc tế Lao động. Hồ Chí Minh – Biên niên tiểu sử còn ghi lại một giấy mời của Ban Bí thư Quốc tế Cộng sản. Giấy mời Người “ngày mai, 1 tháng 5, từ 12 giờ đến 2 giờ chiều có mặt tại Hồng trường để nói chuyện với những người biểu tình”.\n\nHồng trường là tên gọi Quảng trường Đỏ trong nhiều tài liệu tiếng Việt thời trước. Theo Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch, trong ngày hội ấy Người đã có mặt và phát biểu trước quần chúng. Người thanh niên đến từ một xứ thuộc địa đứng giữa biển người Mátxcơva, dưới bóng ngọn tháp có chiếc đồng hồ đang ngân Quốc tế ca. Mùa hè năm ấy, từ ngày 17/6 đến 8/7/1924, Người lại vào Điện Kremli cùng các đại biểu Đại hội V Quốc tế Cộng sản, với tư cách đại biểu tư vấn.","doc":7},{"loai":"anh","src":"textures/ht/ht_anh_participants_in_the_5th_congress_of_the_communis.jpg","chu_thich":"Các đại biểu Đại hội V Quốc tế Cộng sản tại Điện Kremli, mùa hè năm 1924.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Từ con đại bàng đến ngôi sao hồng ngọc","text":"Con đại bàng hai đầu mạ vàng trên đỉnh tháp còn tồn tại gần hai mươi năm sau khi chế độ Sa hoàng sụp đổ. Tháng 10/1935, đại bàng trên bốn ngọn tháp Spasskaya, Nikolskaya, Troitskaya và Borovitskaya được hạ xuống. Thay vào đó là những ngôi sao năm cánh bằng thép và đồng lá mạ vàng, giữa có hình búa liềm gắn đá quý vùng Uran. Chỉ sau hai năm, những ngôi sao ấy đã mờ xỉn vì mưa gió và khói bụi thành phố.\n\nNăm 1937, nhân kỷ niệm 20 năm Cách mạng Tháng Mười, chúng được thay bằng những ngôi sao kính màu hồng ngọc, bên trong có đèn chiếu sáng cả ngày lẫn đêm. Một ngôi sao thứ năm được đặt thêm trên tháp Vodovzvodnaya. Ngôi sao trên tháp Spasskaya có sải cánh khoảng 3,75 mét, được đặt trên ổ bi để có thể xoay theo chiều gió, giảm sức cản khi gió mạnh. Từ đó, ánh sao đỏ trên nền trời đêm Mátxcơva trở thành một biểu tượng quen thuộc của Liên Xô trong mắt bạn bè khắp thế giới.","doc":8},{"loai":"doan","tieu_de":"Chủ tịch Hồ Chí Minh trở lại Mátxcơva","text":"Nhiều năm sau, người thanh niên từng đứng giữa Hồng trường năm 1924 trở lại Mátxcơva trên cương vị Chủ tịch nước Việt Nam Dân chủ Cộng hòa. Ngày 30/1/1950, Liên Xô công nhận và đặt quan hệ ngoại giao với Việt Nam Dân chủ Cộng hòa; đầu năm ấy, Người bí mật sang Mátxcơva. Tháng 7/1955, Người dẫn đầu đoàn đại biểu Chính phủ sang thăm chính thức Liên Xô. Tháng 11/1957, Người sang dự lễ kỷ niệm 40 năm Cách mạng Tháng Mười.\n\nKhi ấy, đỉnh tháp Spasskaya đã mang ngôi sao hồng ngọc; tầng chuông không còn ngân Quốc tế ca, nhưng vẫn điểm giờ như suốt mấy thế kỷ trước. Hơn ba mươi năm đã trôi qua kể từ mùa đông Người đội rét bên chiếc lăng gỗ tạm. Nước Việt Nam mà năm 1924 Người phải giới thiệu với bạn bè quốc tế như một xứ thuộc địa xa xôi, nay đã là một quốc gia độc lập, vừa làm nên chiến thắng Điện Biên Phủ năm 1954. Ngọn tháp cổ của Kremli vì thế đã chứng kiến cả hai chặng đường rất khác nhau trong cuộc đời Người.","doc":9},{"loai":"ban_co_biet","text":"Bức thánh tượng Đấng Cứu thế phía trên cổng Spasskaya, nơi ngọn tháp lấy tên, từng bị trát kín trong thời Xô-viết. Năm 2010, các nhà trùng tu tìm lại được bức tượng dưới lớp vữa và phục hồi nó ở vị trí cũ, nhìn ra Quảng trường Đỏ.","nguon_ten":"Bảo tàng Điện Kremli Mátxcơva","doc":10},{"loai":"anh","src":"textures/bang_w/G08_10_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Tháp Spasskaya”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Hôm nay, tháp Spasskaya vẫn là cổng chính của Điện Kremli, nơi những đoàn xe nghi lễ ra vào. Chiếc đồng hồ Butenop vẫn chạy, được những người thợ đồng hồ của Kremli bảo dưỡng định kỳ. Mỗi đêm giao thừa, hàng triệu gia đình Nga vẫn chờ tiếng chuông Spasskaya trên truyền hình để đón năm mới. Mỗi mùa hè, quảng trường trước tháp còn là nơi diễn ra lễ hội âm nhạc quân đội quốc tế mang chính tên ngọn tháp. Cùng với toàn bộ Điện Kremli và Quảng trường Đỏ, tháp Spasskaya nằm trong khu Di sản thế giới được UNESCO công nhận.\n\nKhách Việt Nam đến Mátxcơva hôm nay có thể đứng trên chính quảng trường nơi Nguyễn Ái Quốc có mặt trong ngày Quốc tế Lao động năm 1924, ngẩng nhìn chiếc đồng hồ bốn mặt và ngôi sao đỏ trên đỉnh. Trong gian trưng bày này, ngọn tháp được dựng lại trong khung cảnh mùa đông năm 1924. Nó nhắc khách tham quan rằng lịch sử luôn có nhiều lớp: khi Nguyễn Ái Quốc đến, nước Nga mới đang được dựng lên ngay giữa những khung cảnh của nước Nga cũ.","doc":11}],"nguon":["Bảo tàng Điện Kremli Mátxcơva – Tháp Spasskaya","Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia (các mục tháng 1 và tháng 5/1924); các tập về những năm 1950 – 1957","Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch – Nguyễn Ái Quốc trên đất nước của Lênin (1923 – 1924), https://nhasanbacho.vn/bai-viet/nguyen-ai-quoc-tren-dat-nuoc-cua-lenin-1923-1924-222/","UNESCO – Trung tâm Di sản thế giới: Kremlin and Red Square, Moscow","Kremlin stars; Spasskaya Tower – Wikipedia tiếng Anh (tham khảo định hướng)"],"doc":[{"t":"Tháp Spasskaya: chiếc đồng hồ của Quảng trường Đỏ và con đại bàng chưa kịp thay. Hơn năm thế kỷ nay, tháp Spasskaya là cổng chính của Điện Kremli và là chiếc đồng hồ của cả nước Nga. Mùa đông năm 1924, khi Nguyễn Ái Quốc đứng giữa Quảng trường Đỏ, đỉnh tháp vẫn còn con đại bàng hai đầu của các Sa hoàng, còn tầng chuông thì ngân giai điệu Quốc tế ca. Câu chuyện của ngọn tháp là câu chuyện của những lớp thời gian chồng lên nhau."},{"t":"Cánh cổng phải bỏ mũ khi đi qua. Đứng giữa Quảng trường Đỏ nhìn về phía Kremli, ánh mắt ai cũng dừng lại ở ngọn tháp gạch đỏ vút cao với chiếc đồng hồ lớn trên thân. Đó là tháp Spasskaya, cổng chính và trang trọng nhất trong hai mươi ngọn tháp của tường thành Kremli. Suốt nhiều thế kỷ, qua vòm cổng này, các Sa hoàng ra vào trong những dịp đại lễ, các đoàn rước tôn giáo đi ra quảng trường, sứ thần nước ngoài được đưa vào yết kiến. Tương truyền, từ thế kỷ XVII đã có lệ ai đi qua cổng Spasskaya cũng phải bỏ mũ, người cưỡi ngựa phải xuống dắt bộ, để tỏ lòng tôn kính bức thánh tượng đặt phía trên cổng. Thời Xô-viết, đây vẫn là lối ra vào chính của những đoàn xe chính phủ. Với người Mátxcơva, ngọn tháp là biểu tượng của nhà nước; với khách phương xa, nó là hình ảnh đầu tiên gợi đến nước Nga. Trong gian trưng bày này, tháp Spasskaya hiện lên phía xa, bên bức tường thành đỏ, như trong khung cảnh Quảng trường Đỏ mùa đông năm 1924."},{"t":"Dấu tay của người thợ Italia. Tháp được dựng năm 1491, dưới thời Đại công tước Ivan III, người thống nhất các vùng đất Nga quanh Mátxcơva. Để xây lại tường thành Kremli bằng gạch thay cho bức tường đá trắng cũ đã xuống cấp, Ivan III mời nhiều kiến trúc sư từ Italia, trung tâm nghệ thuật xây dựng của châu Âu thời Phục hưng. Người thiết kế tháp là Pietro Antonio Solari, một kiến trúc sư đến từ vùng Milan. Phía trên cổng, những tấm bia đá trắng khắc chữ Latinh và chữ Nga cổ còn ghi lại năm xây dựng và tên người thợ Italia ấy. Ban đầu, tháp chỉ là một khối vuông vững chãi, bên ngoài có cầu bắc qua con hào chạy dọc chân tường. Nó mang tên Frolovskaya, theo tên nhà thờ thánh Frol và Lavr ở gần đó. Solari còn chỉ huy xây nhiều ngọn tháp khác của Kremli. Những bức tường có răng cưa hình đuôi én mà ngày nay trở thành dấu hiệu nhận biết Kremli cũng mang dấu ấn của các thợ Italia thời ấy, gợi nhớ những tòa thành ở miền Bắc Italia."},{"t":"Mái chóp của thế kỷ XVII và một cái tên mới. Hơn một thế kỷ sau, ngọn tháp mới có dáng vẻ ta thấy hôm nay. Trong những năm 1624 – 1625, kiến trúc sư Nga Bazhen Ogurtsov cùng người thợ đồng hồ người Anh Christopher Galloway xây thêm phần mái chóp nhiều tầng. Những tháp nhọn nhỏ, lan can đá trắng và các chi tiết trang trí công phu mang dáng dấp kiến trúc Gôtích châu Âu. Từ một tháp phòng thủ, Spasskaya trở thành một công trình lộng lẫy, cao vượt hẳn lên trên tường thành. Năm 1658, Sa hoàng Alếchxây Mikhailôvích ra sắc lệnh đổi tên tháp thành Spasskaya, nghĩa là tháp Đấng Cứu thế. Cái tên gắn với bức thánh tượng Đấng Cứu thế thành Xmôlenxcơ đặt phía trên cổng, nhìn ra Quảng trường Đỏ. Ngày nay, tính cả ngôi sao trên đỉnh, tháp cao khoảng 71 mét, tương đương một tòa nhà hai mươi tầng. Cũng từ thế kỷ XVII, trên đỉnh mái chóp được đặt biểu tượng đại bàng hai đầu của nhà nước Nga. Chính con đại bàng ấy vẫn ngự trên đỉnh tháp trong những tháng Nguyễn Ái Quốc sống ở Mátxcơva, năm 1923 – 1924."},{"t":"Chiếc đồng hồ của cả nước Nga. Đồng hồ xuất hiện trên tháp từ rất sớm. Christopher Galloway đã lắp một chiếc đồng hồ lớn ngay khi dựng phần mái chóp. Đầu thế kỷ XVIII, Pie Đại đế cho thay bằng một chiếc đồng hồ mua từ Hà Lan. Bộ máy đang chạy hôm nay do hai anh em thợ Butenop chế tạo và lắp đặt trong những năm 1851 – 1852. Bốn mặt số, mỗi mặt có đường kính 6,12 mét, nhìn ra bốn phía; kim phút dài hơn ba mét. Cỗ máy nặng khoảng 25 tấn, chiếm trọn ba tầng bên trong tháp, và suốt nhiều thập kỷ được lên dây bằng tay. Phía trên là tầng chuông, nơi những quả chuông đồng điểm giờ và ngân nhạc, vang khắp Quảng trường Đỏ. Người Nga gọi chiếc đồng hồ bằng một cái tên riêng: kuranty, tức đồng hồ chuông. Hàng chục năm nay, tiếng chuông của nó trên sóng phát thanh và truyền hình báo hiệu thời khắc giao thừa cho cả nước. Với nhiều thế hệ người Nga, tiếng chuông Spasskaya không chỉ là tiếng báo giờ mà là nhịp đập của đất nước."},{"t":"Bạn có biết? Theo các tư liệu về lịch sử Kremli, chiếc đồng hồ Galloway lắp năm 1625 có cách chỉ giờ rất lạ: mặt số tự quay, còn kim thì đứng yên. Mặt số chia theo lối tính giờ cổ của người Nga, đếm riêng giờ ban ngày và giờ ban đêm, nên có tới 17 vạch giờ."},{"t":"Viên đạn pháo năm 1917 và giai điệu Quốc tế ca. Tháng 11/1917, trong những ngày giao tranh ác liệt ở Mátxcơva giữa lực lượng cách mạng và quân ủng hộ Chính phủ lâm thời, một quả đạn pháo trúng mặt đồng hồ tháp Spasskaya. Kim đồng hồ gãy hỏng, bộ máy ngừng chạy. Năm 1918, sau khi chính phủ Xô-viết dời đô về Mátxcơva và Lênin chuyển vào làm việc trong Kremli, đồng hồ được sửa chữa. Người thợ khóa Nikolai Behrens phục hồi bộ máy. Họa sĩ kiêm nhạc sĩ Mikhail Cheremnykh chỉnh lại hệ thống chuông để ngân giai điệu bài Quốc tế ca và bài hát tang lễ cách mạng “Các anh đã ngã xuống”. Từ đó, giai điệu Quốc tế ca vang lên từ ngọn tháp vào những giờ nhất định trong ngày. Như vậy, trong những tháng Nguyễn Ái Quốc sống ở Mátxcơva, trên đỉnh tháp là con đại bàng của các Sa hoàng, còn trong tầng chuông là bài ca của những người cộng sản. Năm 1938, chuông thôi chơi nhạc, chỉ còn điểm giờ. Phải đến năm 1996, chuông mới lại ngân nhạc, và từ năm 2000 chơi giai điệu Quốc ca Liên bang Nga."},{"t":"Hồng trường trưa ngày 1/5/1924. Với Nguyễn Ái Quốc, Quảng trường Đỏ dưới chân tháp Spasskaya gắn với những ngày đáng nhớ của năm 1924. Tháng Giêng, Người đội rét tiễn đưa Lênin, khi chiếc lăng gỗ tạm được dựng bên tường thành cách ngọn tháp không xa (xem chuyên đề Lăng gỗ tạm của Lênin). Hơn ba tháng sau, quảng trường lại rực cờ đỏ trong ngày Quốc tế Lao động. Hồ Chí Minh – Biên niên tiểu sử còn ghi lại một giấy mời của Ban Bí thư Quốc tế Cộng sản. Giấy mời Người “ngày mai, 1 tháng 5, từ 12 giờ đến 2 giờ chiều có mặt tại Hồng trường để nói chuyện với những người biểu tình”. Hồng trường là tên gọi Quảng trường Đỏ trong nhiều tài liệu tiếng Việt thời trước. Theo Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch, trong ngày hội ấy Người đã có mặt và phát biểu trước quần chúng. Người thanh niên đến từ một xứ thuộc địa đứng giữa biển người Mátxcơva, dưới bóng ngọn tháp có chiếc đồng hồ đang ngân Quốc tế ca. Mùa hè năm ấy, từ ngày 17/6 đến 8/7/1924, Người lại vào Điện Kremli cùng các đại biểu Đại hội V Quốc tế Cộng sản, với tư cách đại biểu tư vấn."},{"t":"Từ con đại bàng đến ngôi sao hồng ngọc. Con đại bàng hai đầu mạ vàng trên đỉnh tháp còn tồn tại gần hai mươi năm sau khi chế độ Sa hoàng sụp đổ. Tháng 10/1935, đại bàng trên bốn ngọn tháp Spasskaya, Nikolskaya, Troitskaya và Borovitskaya được hạ xuống. Thay vào đó là những ngôi sao năm cánh bằng thép và đồng lá mạ vàng, giữa có hình búa liềm gắn đá quý vùng Uran. Chỉ sau hai năm, những ngôi sao ấy đã mờ xỉn vì mưa gió và khói bụi thành phố. Năm 1937, nhân kỷ niệm 20 năm Cách mạng Tháng Mười, chúng được thay bằng những ngôi sao kính màu hồng ngọc, bên trong có đèn chiếu sáng cả ngày lẫn đêm. Một ngôi sao thứ năm được đặt thêm trên tháp Vodovzvodnaya. Ngôi sao trên tháp Spasskaya có sải cánh khoảng 3,75 mét, được đặt trên ổ bi để có thể xoay theo chiều gió, giảm sức cản khi gió mạnh. Từ đó, ánh sao đỏ trên nền trời đêm Mátxcơva trở thành một biểu tượng quen thuộc của Liên Xô trong mắt bạn bè khắp thế giới."},{"t":"Chủ tịch Hồ Chí Minh trở lại Mátxcơva. Nhiều năm sau, người thanh niên từng đứng giữa Hồng trường năm 1924 trở lại Mátxcơva trên cương vị Chủ tịch nước Việt Nam Dân chủ Cộng hòa. Ngày 30/1/1950, Liên Xô công nhận và đặt quan hệ ngoại giao với Việt Nam Dân chủ Cộng hòa; đầu năm ấy, Người bí mật sang Mátxcơva. Tháng 7/1955, Người dẫn đầu đoàn đại biểu Chính phủ sang thăm chính thức Liên Xô. Tháng 11/1957, Người sang dự lễ kỷ niệm 40 năm Cách mạng Tháng Mười. Khi ấy, đỉnh tháp Spasskaya đã mang ngôi sao hồng ngọc; tầng chuông không còn ngân Quốc tế ca, nhưng vẫn điểm giờ như suốt mấy thế kỷ trước. Hơn ba mươi năm đã trôi qua kể từ mùa đông Người đội rét bên chiếc lăng gỗ tạm. Nước Việt Nam mà năm 1924 Người phải giới thiệu với bạn bè quốc tế như một xứ thuộc địa xa xôi, nay đã là một quốc gia độc lập, vừa làm nên chiến thắng Điện Biên Phủ năm 1954. Ngọn tháp cổ của Kremli vì thế đã chứng kiến cả hai chặng đường rất khác nhau trong cuộc đời Người."},{"t":"Bạn có biết? Bức thánh tượng Đấng Cứu thế phía trên cổng Spasskaya, nơi ngọn tháp lấy tên, từng bị trát kín trong thời Xô-viết. Năm 2010, các nhà trùng tu tìm lại được bức tượng dưới lớp vữa và phục hồi nó ở vị trí cũ, nhìn ra Quảng trường Đỏ."},{"t":"Dấu tích hôm nay. Hôm nay, tháp Spasskaya vẫn là cổng chính của Điện Kremli, nơi những đoàn xe nghi lễ ra vào. Chiếc đồng hồ Butenop vẫn chạy, được những người thợ đồng hồ của Kremli bảo dưỡng định kỳ. Mỗi đêm giao thừa, hàng triệu gia đình Nga vẫn chờ tiếng chuông Spasskaya trên truyền hình để đón năm mới. Mỗi mùa hè, quảng trường trước tháp còn là nơi diễn ra lễ hội âm nhạc quân đội quốc tế mang chính tên ngọn tháp. Cùng với toàn bộ Điện Kremli và Quảng trường Đỏ, tháp Spasskaya nằm trong khu Di sản thế giới được UNESCO công nhận. Khách Việt Nam đến Mátxcơva hôm nay có thể đứng trên chính quảng trường nơi Nguyễn Ái Quốc có mặt trong ngày Quốc tế Lao động năm 1924, ngẩng nhìn chiếc đồng hồ bốn mặt và ngôi sao đỏ trên đỉnh. Trong gian trưng bày này, ngọn tháp được dựng lại trong khung cảnh mùa đông năm 1924. Nó nhắc khách tham quan rằng lịch sử luôn có nhiều lớp: khi Nguyễn Ái Quốc đến, nước Nga mới đang được dựng lên ngay giữa những khung cảnh của nước Nga cũ."}],"so_chu":1926},{"i":11,"tieu_de_bang":"Nhà thờ Thánh Basil","tieu_de":"Nhà thờ Thánh Basil: chín nhà nguyện trên một nền chung và số phận một kiệt tác","sapo":"Ở đầu phía nam Quảng trường Đỏ, những mái vòm củ hành xoắn vặn, mỗi mái một màu, trông như bước ra từ truyện cổ tích. Công trình ấy ra đời để tạ ơn một chiến thắng thế kỷ XVI, mang tên một người tu hành đi chân đất, và đã vượt qua bao cơn biến động của lịch sử. Năm 1923, đúng năm Nguyễn Ái Quốc đặt chân tới nước Nga Xô-viết, nhà thờ bắt đầu một cuộc đời mới: trở thành bảo tàng.","bia":{"src":"textures/bai/G08_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Cảnh tượng ở đầu quảng trường","text":"Đi dọc Quảng trường Đỏ về phía nam, qua tường thành Kremli và tháp Spasskaya, người ta gặp một công trình khác hẳn mọi kiến trúc xung quanh. Trên một nền gạch cao, chín khối nhà nguyện vươn lên. Ở giữa là khối cao nhất với mái chóp nhọn hình lều, xung quanh là tám mái vòm hình củ hành. Mỗi mái vòm mang một màu sắc, một hoa văn riêng: mái xoắn sọc, mái kẻ ô, mái nổi gờ như vảy. Sau lưng nhà thờ, mặt đất dốc thoai thoải xuống bờ sông Mátxcơva.\n\nĐó là nhà thờ Thánh Basil, tên chính thức là Nhà thờ Đức Mẹ Chở che bên hào, công trình mà nhiều người coi là biểu tượng của cả nước Nga. Trong những năm 1923 – 1924, khi Nguyễn Ái Quốc sống ở Mátxcơva, những mái vòm sặc sỡ ấy là một phần quen thuộc của Quảng trường Đỏ. Gian trưng bày dựng lại công trình ở đầu phía nam quảng trường, như một mốc định hướng giúp khách tham quan hình dung không gian Mátxcơva mùa đông năm 1924.","doc":1},{"loai":"doan","tieu_de":"Lời tạ ơn sau trận Kazan","text":"Công trình ra đời từ một cuộc chiến. Giữa thế kỷ XVI, hãn quốc Kazan bên sông Volga là mối đe dọa thường trực ở phía đông nước Nga. Năm 1552, Sa hoàng Ivan IV, người đời sau gọi là Ivan Hung Đế, đích thân dẫn quân vây hãm và chiếm được thành Kazan. Trận đánh quyết định rơi đúng vào dịp lễ Đức Mẹ Chở che, vì thế nhà thờ được dâng kính Đức Mẹ Chở che.\n\nĐể tạ ơn, Ivan IV cho xây một nhà thờ bằng đá ngay trên khu chợ trước Kremli, nơi trước đó đã có những nhà thờ gỗ nhỏ. Công trình được xây trong những năm 1555 – 1561. Vị trí được chọn nằm bên con hào sâu chạy dọc tường thành Kremli, nên có tên là nhà thờ bên hào. Con hào ấy đã bị lấp từ đầu thế kỷ XIX, nhưng cái tên vẫn còn. Nhiều nhà nguyện phụ trong công trình được dâng kính những vị thánh có ngày lễ trùng với các trận đánh của chiến dịch Kazan. Nhà thờ vì thế như một cuốn biên niên bằng gạch đá về cuộc chiến ấy.","doc":2},{"loai":"anh","src":"textures/bang_w/G08_11_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nhà thờ Thánh Basil”, nhìn từ xa."},{"loai":"doan","tieu_de":"Barma, Postnik và một giai thoại tàn nhẫn","text":"Người đời sau biết rất ít về những người đã dựng nên kiệt tác này. Sử liệu cổ nhắc tới hai cái tên Barma và Postnik; một số nhà nghiên cứu còn cho rằng đó có thể chỉ là một người mang hai tên gọi. Quanh họ có một giai thoại được kể đi kể lại: khi công trình hoàn thành, Ivan Hung Đế cho làm mù mắt những người thợ để họ không thể xây một nhà thờ nào đẹp hơn. Câu chuyện hợp với hình ảnh vị Sa hoàng nổi tiếng tàn bạo nên lan truyền rộng rãi. Nhưng các nhà sử học cho rằng giai thoại ấy không có căn cứ.\n\nĐiều chắc chắn hơn là kiến trúc của nhà thờ không giống bất kỳ công trình nào trước đó. Những mái chóp hình lều gợi lại truyền thống nhà thờ gỗ của người Nga, nay được chuyển sang gạch đá. Kỹ thuật xây gạch và nhiều chi tiết trang trí lại mang dấu ấn những gì thợ Nga học được từ các kiến trúc sư Italia đến Mátxcơva hơn nửa thế kỷ trước đó, những người đã dựng tường thành và các ngọn tháp Kremli.","doc":3},{"loai":"doan","tieu_de":"Chín nhà nguyện, một mê cung","text":"Bí mật của kiến trúc nằm ở mặt bằng. Nhà nguyện trung tâm, dâng kính Đức Mẹ Chở che, vươn cao với mái chóp hình lều. Xung quanh là tám nhà nguyện: bốn nhà lớn đặt theo bốn hướng chính, xen giữa là bốn nhà nhỏ hơn. Tất cả đứng trên một nền chung và nối với nhau bằng những hành lang hẹp. Bên trong không có gian đại sảnh rộng như các nhà thờ lớn phương Tây. Mỗi nhà nguyện là một không gian nhỏ, cao vút, ánh sáng lọt xuống từ những ô cửa trên cao.\n\nKhách tham quan hôm nay đi qua những lối cầu thang hẹp xây trong thân tường, những hành lang vẽ kín hoa lá, có cảm giác như lạc vào một mê cung. Những mảng màu rực rỡ trên các mái vòm không có ngay từ thế kỷ XVI. Ban đầu, nhà thờ mang màu gạch đỏ xen đá trắng; các mái vòm và lớp sơn sặc sỡ được hoàn thiện dần trong thế kỷ XVII và những thế kỷ sau. Mỗi lần trùng tu lại góp thêm một lớp thời gian lên diện mạo công trình.","doc":4},{"loai":"ban_co_biet","text":"Từ khi hoàn thành năm 1561 cho tới năm 1600, khi tháp chuông Ivan Đại đế trong Kremli được nâng cao, nhà thờ Thánh Basil là công trình cao nhất Mátxcơva.","nguon_ten":"Saint Basil's Cathedral – Wikipedia tiếng Anh; Bảo tàng Lịch sử Quốc gia Nga","doc":5},{"loai":"doan","tieu_de":"Người tu hành chân đất cho nhà thờ mượn tên","text":"Năm 1588, người ta xây thêm một nhà nguyện nhỏ ở góc đông bắc, trên mộ của Vasily Blazhenny, tức Basil Thánh thiện. Ông là một thánh ngốc, cách gọi những người tu khổ hạnh sống lang thang, giả dại, mà người Nga xưa đặc biệt kính trọng. Tương truyền, Vasily đi chân đất quanh năm, kể cả giữa mùa đông Mátxcơva, và dám nói thẳng cả với Ivan Hung Đế về những điều bất công.\n\nSau khi ông mất, dân Mátxcơva tôn kính ông như một vị thánh, và mộ ông ở chân nhà thờ trở thành nơi hành hương. Từ đó, dù tên chính thức vẫn là Nhà thờ Đức Mẹ Chở che bên hào, người dân quen gọi cả công trình là nhà thờ Thánh Vasily. Tên gọi Basil trong các thứ tiếng phương Tây bắt nguồn từ đó. Cuối thế kỷ XVII, một tháp chuông được xây thêm ở góc đông nam. Cách nhà thờ không xa là bục đá tròn Lobnoye Mesto, nơi xưa kia các sắc lệnh của Sa hoàng được đọc cho dân chúng, cũng là một phần khung cảnh được dựng lại trong gian trưng bày.","doc":6},{"loai":"anh","src":"textures/bang_w/G08_11_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nhà thờ Thánh Basil”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Năm 1923: nhà thờ thành bảo tàng","text":"Sau Cách mạng Tháng Mười, số phận nhà thờ bước sang một khúc quanh mới. Năm 1923, đúng năm Nguyễn Ái Quốc tới nước Nga Xô-viết, công trình được mở cửa như một bảo tàng lịch sử và kiến trúc. Năm 1928, bảo tàng trở thành một chi nhánh của Bảo tàng Lịch sử Quốc gia, đơn vị quản lý nhà thờ cho đến nay. Năm 1929, các buổi lễ tôn giáo chấm dứt, chuông trên tháp chuông được hạ xuống.\n\nNhững năm 1930, Quảng trường Đỏ được chỉnh trang để phục vụ các cuộc diễu binh, diễu hành lớn. Cổng Phục Sinh ở đầu phía bắc quảng trường bị phá năm 1931; nhà thờ Đức Mẹ Kazan ở góc quảng trường bị phá năm 1936. Nhà thờ Thánh Basil đứng vững. Quanh chuyện này có nhiều lời kể: tương truyền nhà trùng tu Pyotr Baranovsky đã kiên quyết từ chối chuẩn bị cho việc phá dỡ, nhưng tư liệu chưa cho phép khẳng định chắc chắn. Điều rõ ràng là công trình đã vượt qua thời kỳ mà nhiều kiến trúc cổ của Mátxcơva không qua được. Cả hai công trình bị phá ở phía bắc quảng trường đều được xây dựng lại trong những năm 1990.","doc":7},{"loai":"doan","tieu_de":"Bức phông nền của mùa đông năm 1924","text":"Tháng 1/1924, dòng người tiễn đưa Lênin tràn qua Quảng trường Đỏ trong tuyết lạnh, dưới những lá cờ viền tang. Nguyễn Ái Quốc có mặt trong dòng người ấy (xem chuyên đề Lăng gỗ tạm của Lênin). Từ chỗ chiếc lăng gỗ tạm được dựng bên tường Kremli nhìn về phía nam, những mái vòm của nhà thờ Thánh Basil khép lại khung cảnh quảng trường.\n\nQuảng trường khi ấy cũng khác bây giờ. Tượng đài Minin và Pozharsky, hai người đã lãnh đạo nhân dân đánh đuổi quân chiếm đóng khỏi Mátxcơva năm 1612, còn đứng giữa quảng trường, đối diện tường thành. Bên kia quảng trường là dãy nhà Thương mại Thượng với mái vòm kính, nay là cửa hàng bách hóa GUM. Chưa có lăng đá, chưa có những ngôi sao đỏ trên các ngọn tháp Kremli. Trong không gian ấy, người thanh niên Việt Nam ba mươi ba tuổi đứng giữa những người lao động Nga và những sinh viên đến từ nhiều nước phương Đông. Gian trưng bày tái hiện nhà thờ Thánh Basil như một phần của chính khung cảnh ấy, để khách tham quan hình dung thêm nơi chốn từng in dấu chân Người.","doc":8},{"loai":"anh","src":"textures/ht/ht_anh_nguyen_ai_quoc_in_the_soviet_union_in_1923.jpg","chu_thich":"Nguyễn Ái Quốc ở Liên Xô năm 1923, ít tháng trước mùa đông Người có mặt trên Quảng trường Đỏ trong những ngày tang lễ Lênin.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"ban_co_biet","text":"Năm 1924, tượng đài Minin và Pozharsky dựng năm 1818 vẫn đứng giữa Quảng trường Đỏ. Đến năm 1931, tượng mới được chuyển tới vị trí hiện nay, ngay trước nhà thờ Thánh Basil.","nguon_ten":"Bảo tàng Lịch sử Quốc gia Nga (đơn vị quản lý nhà thờ Thánh Basil)","doc":9},{"loai":"anh","src":"textures/bang_w/G08_11_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nhà thờ Thánh Basil”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Hôm nay, nhà thờ Thánh Basil vẫn là một chi nhánh của Bảo tàng Lịch sử Quốc gia Nga và là một trong những điểm tham quan đông khách nhất Mátxcơva. Từ năm 1991, lễ tôn giáo được cử hành trở lại vào một số ngày lễ lớn, còn phần lớn thời gian công trình mở cửa như một bảo tàng. Năm 1990, cùng với Điện Kremli và Quảng trường Đỏ, nhà thờ được UNESCO ghi vào Danh mục Di sản thế giới. Nhiều đợt trùng tu trong thế kỷ XX và XXI đã giúp phục hồi màu sắc các mái vòm và những bức vẽ bên trong.\n\nKhách đến đây có thể đi vòng qua các nhà nguyện, ngắm những bức vẽ hoa lá trên hành lang và các thánh tượng cổ. Ngay trước cửa là tượng Minin và Pozharsky. Với người Việt Nam đến Mátxcơva, nhà thờ Thánh Basil thường nằm trong một hành trình cùng với lăng Lênin, tường thành Kremli và tháp Spasskaya, những địa danh gắn với năm tháng Nguyễn Ái Quốc sống ở thành phố này. Đứng ở đây, khách có thể hình dung lại Quảng trường Đỏ của gần một thế kỷ trước.","doc":10}],"nguon":["UNESCO – Trung tâm Di sản thế giới: Kremlin and Red Square, Moscow","Bảo tàng Lịch sử Quốc gia Nga – Nhà thờ Đức Mẹ Chở che bên hào (nhà thờ Thánh Basil)","Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia (các mục năm 1923 – 1924)","Saint Basil's Cathedral – Wikipedia tiếng Anh (tham khảo định hướng)"],"doc":[{"t":"Nhà thờ Thánh Basil: chín nhà nguyện trên một nền chung và số phận một kiệt tác. Ở đầu phía nam Quảng trường Đỏ, những mái vòm củ hành xoắn vặn, mỗi mái một màu, trông như bước ra từ truyện cổ tích. Công trình ấy ra đời để tạ ơn một chiến thắng thế kỷ XVI, mang tên một người tu hành đi chân đất, và đã vượt qua bao cơn biến động của lịch sử. Năm 1923, đúng năm Nguyễn Ái Quốc đặt chân tới nước Nga Xô-viết, nhà thờ bắt đầu một cuộc đời mới: trở thành bảo tàng."},{"t":"Cảnh tượng ở đầu quảng trường. Đi dọc Quảng trường Đỏ về phía nam, qua tường thành Kremli và tháp Spasskaya, người ta gặp một công trình khác hẳn mọi kiến trúc xung quanh. Trên một nền gạch cao, chín khối nhà nguyện vươn lên. Ở giữa là khối cao nhất với mái chóp nhọn hình lều, xung quanh là tám mái vòm hình củ hành. Mỗi mái vòm mang một màu sắc, một hoa văn riêng: mái xoắn sọc, mái kẻ ô, mái nổi gờ như vảy. Sau lưng nhà thờ, mặt đất dốc thoai thoải xuống bờ sông Mátxcơva. Đó là nhà thờ Thánh Basil, tên chính thức là Nhà thờ Đức Mẹ Chở che bên hào, công trình mà nhiều người coi là biểu tượng của cả nước Nga. Trong những năm 1923 – 1924, khi Nguyễn Ái Quốc sống ở Mátxcơva, những mái vòm sặc sỡ ấy là một phần quen thuộc của Quảng trường Đỏ. Gian trưng bày dựng lại công trình ở đầu phía nam quảng trường, như một mốc định hướng giúp khách tham quan hình dung không gian Mátxcơva mùa đông năm 1924."},{"t":"Lời tạ ơn sau trận Kazan. Công trình ra đời từ một cuộc chiến. Giữa thế kỷ XVI, hãn quốc Kazan bên sông Volga là mối đe dọa thường trực ở phía đông nước Nga. Năm 1552, Sa hoàng Ivan IV, người đời sau gọi là Ivan Hung Đế, đích thân dẫn quân vây hãm và chiếm được thành Kazan. Trận đánh quyết định rơi đúng vào dịp lễ Đức Mẹ Chở che, vì thế nhà thờ được dâng kính Đức Mẹ Chở che. Để tạ ơn, Ivan IV cho xây một nhà thờ bằng đá ngay trên khu chợ trước Kremli, nơi trước đó đã có những nhà thờ gỗ nhỏ. Công trình được xây trong những năm 1555 – 1561. Vị trí được chọn nằm bên con hào sâu chạy dọc tường thành Kremli, nên có tên là nhà thờ bên hào. Con hào ấy đã bị lấp từ đầu thế kỷ XIX, nhưng cái tên vẫn còn. Nhiều nhà nguyện phụ trong công trình được dâng kính những vị thánh có ngày lễ trùng với các trận đánh của chiến dịch Kazan. Nhà thờ vì thế như một cuốn biên niên bằng gạch đá về cuộc chiến ấy."},{"t":"Barma, Postnik và một giai thoại tàn nhẫn. Người đời sau biết rất ít về những người đã dựng nên kiệt tác này. Sử liệu cổ nhắc tới hai cái tên Barma và Postnik; một số nhà nghiên cứu còn cho rằng đó có thể chỉ là một người mang hai tên gọi. Quanh họ có một giai thoại được kể đi kể lại: khi công trình hoàn thành, Ivan Hung Đế cho làm mù mắt những người thợ để họ không thể xây một nhà thờ nào đẹp hơn. Câu chuyện hợp với hình ảnh vị Sa hoàng nổi tiếng tàn bạo nên lan truyền rộng rãi. Nhưng các nhà sử học cho rằng giai thoại ấy không có căn cứ. Điều chắc chắn hơn là kiến trúc của nhà thờ không giống bất kỳ công trình nào trước đó. Những mái chóp hình lều gợi lại truyền thống nhà thờ gỗ của người Nga, nay được chuyển sang gạch đá. Kỹ thuật xây gạch và nhiều chi tiết trang trí lại mang dấu ấn những gì thợ Nga học được từ các kiến trúc sư Italia đến Mátxcơva hơn nửa thế kỷ trước đó, những người đã dựng tường thành và các ngọn tháp Kremli."},{"t":"Chín nhà nguyện, một mê cung. Bí mật của kiến trúc nằm ở mặt bằng. Nhà nguyện trung tâm, dâng kính Đức Mẹ Chở che, vươn cao với mái chóp hình lều. Xung quanh là tám nhà nguyện: bốn nhà lớn đặt theo bốn hướng chính, xen giữa là bốn nhà nhỏ hơn. Tất cả đứng trên một nền chung và nối với nhau bằng những hành lang hẹp. Bên trong không có gian đại sảnh rộng như các nhà thờ lớn phương Tây. Mỗi nhà nguyện là một không gian nhỏ, cao vút, ánh sáng lọt xuống từ những ô cửa trên cao. Khách tham quan hôm nay đi qua những lối cầu thang hẹp xây trong thân tường, những hành lang vẽ kín hoa lá, có cảm giác như lạc vào một mê cung. Những mảng màu rực rỡ trên các mái vòm không có ngay từ thế kỷ XVI. Ban đầu, nhà thờ mang màu gạch đỏ xen đá trắng; các mái vòm và lớp sơn sặc sỡ được hoàn thiện dần trong thế kỷ XVII và những thế kỷ sau. Mỗi lần trùng tu lại góp thêm một lớp thời gian lên diện mạo công trình."},{"t":"Bạn có biết? Từ khi hoàn thành năm 1561 cho tới năm 1600, khi tháp chuông Ivan Đại đế trong Kremli được nâng cao, nhà thờ Thánh Basil là công trình cao nhất Mátxcơva."},{"t":"Người tu hành chân đất cho nhà thờ mượn tên. Năm 1588, người ta xây thêm một nhà nguyện nhỏ ở góc đông bắc, trên mộ của Vasily Blazhenny, tức Basil Thánh thiện. Ông là một thánh ngốc, cách gọi những người tu khổ hạnh sống lang thang, giả dại, mà người Nga xưa đặc biệt kính trọng. Tương truyền, Vasily đi chân đất quanh năm, kể cả giữa mùa đông Mátxcơva, và dám nói thẳng cả với Ivan Hung Đế về những điều bất công. Sau khi ông mất, dân Mátxcơva tôn kính ông như một vị thánh, và mộ ông ở chân nhà thờ trở thành nơi hành hương. Từ đó, dù tên chính thức vẫn là Nhà thờ Đức Mẹ Chở che bên hào, người dân quen gọi cả công trình là nhà thờ Thánh Vasily. Tên gọi Basil trong các thứ tiếng phương Tây bắt nguồn từ đó. Cuối thế kỷ XVII, một tháp chuông được xây thêm ở góc đông nam. Cách nhà thờ không xa là bục đá tròn Lobnoye Mesto, nơi xưa kia các sắc lệnh của Sa hoàng được đọc cho dân chúng, cũng là một phần khung cảnh được dựng lại trong gian trưng bày."},{"t":"Năm 1923: nhà thờ thành bảo tàng. Sau Cách mạng Tháng Mười, số phận nhà thờ bước sang một khúc quanh mới. Năm 1923, đúng năm Nguyễn Ái Quốc tới nước Nga Xô-viết, công trình được mở cửa như một bảo tàng lịch sử và kiến trúc. Năm 1928, bảo tàng trở thành một chi nhánh của Bảo tàng Lịch sử Quốc gia, đơn vị quản lý nhà thờ cho đến nay. Năm 1929, các buổi lễ tôn giáo chấm dứt, chuông trên tháp chuông được hạ xuống. Những năm 1930, Quảng trường Đỏ được chỉnh trang để phục vụ các cuộc diễu binh, diễu hành lớn. Cổng Phục Sinh ở đầu phía bắc quảng trường bị phá năm 1931; nhà thờ Đức Mẹ Kazan ở góc quảng trường bị phá năm 1936. Nhà thờ Thánh Basil đứng vững. Quanh chuyện này có nhiều lời kể: tương truyền nhà trùng tu Pyotr Baranovsky đã kiên quyết từ chối chuẩn bị cho việc phá dỡ, nhưng tư liệu chưa cho phép khẳng định chắc chắn. Điều rõ ràng là công trình đã vượt qua thời kỳ mà nhiều kiến trúc cổ của Mátxcơva không qua được. Cả hai công trình bị phá ở phía bắc quảng trường đều được xây dựng lại trong những năm 1990."},{"t":"Bức phông nền của mùa đông năm 1924. Tháng 1/1924, dòng người tiễn đưa Lênin tràn qua Quảng trường Đỏ trong tuyết lạnh, dưới những lá cờ viền tang. Nguyễn Ái Quốc có mặt trong dòng người ấy (xem chuyên đề Lăng gỗ tạm của Lênin). Từ chỗ chiếc lăng gỗ tạm được dựng bên tường Kremli nhìn về phía nam, những mái vòm của nhà thờ Thánh Basil khép lại khung cảnh quảng trường. Quảng trường khi ấy cũng khác bây giờ. Tượng đài Minin và Pozharsky, hai người đã lãnh đạo nhân dân đánh đuổi quân chiếm đóng khỏi Mátxcơva năm 1612, còn đứng giữa quảng trường, đối diện tường thành. Bên kia quảng trường là dãy nhà Thương mại Thượng với mái vòm kính, nay là cửa hàng bách hóa GUM. Chưa có lăng đá, chưa có những ngôi sao đỏ trên các ngọn tháp Kremli. Trong không gian ấy, người thanh niên Việt Nam ba mươi ba tuổi đứng giữa những người lao động Nga và những sinh viên đến từ nhiều nước phương Đông. Gian trưng bày tái hiện nhà thờ Thánh Basil như một phần của chính khung cảnh ấy, để khách tham quan hình dung thêm nơi chốn từng in dấu chân Người."},{"t":"Bạn có biết? Năm 1924, tượng đài Minin và Pozharsky dựng năm 1818 vẫn đứng giữa Quảng trường Đỏ. Đến năm 1931, tượng mới được chuyển tới vị trí hiện nay, ngay trước nhà thờ Thánh Basil."},{"t":"Dấu tích hôm nay. Hôm nay, nhà thờ Thánh Basil vẫn là một chi nhánh của Bảo tàng Lịch sử Quốc gia Nga và là một trong những điểm tham quan đông khách nhất Mátxcơva. Từ năm 1991, lễ tôn giáo được cử hành trở lại vào một số ngày lễ lớn, còn phần lớn thời gian công trình mở cửa như một bảo tàng. Năm 1990, cùng với Điện Kremli và Quảng trường Đỏ, nhà thờ được UNESCO ghi vào Danh mục Di sản thế giới. Nhiều đợt trùng tu trong thế kỷ XX và XXI đã giúp phục hồi màu sắc các mái vòm và những bức vẽ bên trong. Khách đến đây có thể đi vòng qua các nhà nguyện, ngắm những bức vẽ hoa lá trên hành lang và các thánh tượng cổ. Ngay trước cửa là tượng Minin và Pozharsky. Với người Việt Nam đến Mátxcơva, nhà thờ Thánh Basil thường nằm trong một hành trình cùng với lăng Lênin, tường thành Kremli và tháp Spasskaya, những địa danh gắn với năm tháng Nguyễn Ái Quốc sống ở thành phố này. Đứng ở đây, khách có thể hình dung lại Quảng trường Đỏ của gần một thế kỷ trước."}],"so_chu":1727},{"i":12,"tieu_de_bang":"Quốc tế Cộng sản","tieu_de":"Quốc tế Cộng sản và Nguyễn Ái Quốc: hai mươi ba năm gắn bó (1920 – 1943)","sapo":"Hồ Chí Minh – Biên niên tiểu sử ghi lại một quyết định ngày 14/4/1924 của Quốc tế Cộng sản: nhận Nguyễn Ái Quốc làm cán bộ Ban Phương Đông, lương mỗi tháng 6 trécnôvéc. Tờ giấy hành chính ấy là một mắt xích trong mối gắn bó kéo dài gần một phần tư thế kỷ. Quốc tế Cộng sản là tổ chức thế nào, và vì sao người thanh niên yêu nước Việt Nam lại chọn đi cùng nó?","bia":{"src":"textures/ht/ht_anh_participants_in_the_5th_congress_of_the_communis.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Sáu trécnôvéc mỗi tháng","text":"Ngày 14/4/1924, Ban Phương Đông của Quốc tế Cộng sản quyết định nhận Nguyễn Ái Quốc làm cán bộ, với mức lương hằng tháng 6 trécnôvéc, tương đương 60 rúp. Trécnôvéc là loại tiền có bảo đảm bằng vàng mà nước Nga Xô-viết phát hành từ cuối năm 1922 để ổn định tài chính sau những năm nội chiến. Ba ngày trước đó, ngày 11/4/1924, Người đã gửi thư đề nghị được sang Trung Quốc để từ đó tìm đường về Đông Dương. Người muốn xây dựng quan hệ giữa phong trào ở Đông Dương với Quốc tế Cộng sản và tổ chức công tác tuyên truyền ngay gần quê hương.\n\nNhững tờ giấy khô khan ấy cho thấy một điều quan trọng. Chưa đầy một năm sau khi lặng lẽ rời Paris, người thanh niên thuộc địa đã trở thành cán bộ chính thức trong bộ máy của phong trào cộng sản quốc tế, với một mục tiêu rất rõ: trở về phương Đông. Để hiểu vì sao Người tìm đến tổ chức này, cần trở lại mùa xuân năm 1919, khi Quốc tế Cộng sản ra đời.","doc":1},{"loai":"doan","tieu_de":"Mùa xuân năm 1919 ở Mátxcơva","text":"Từ ngày 2 đến 6/3/1919, giữa lúc nước Nga Xô-viết đang bị nội chiến và can thiệp nước ngoài bao vây, một hội nghị quốc tế họp tại Mátxcơva theo sáng kiến của Lênin. Hội nghị tuyên bố thành lập Quốc tế Cộng sản, còn gọi là Quốc tế thứ ba, viết tắt theo tiếng Nga là Comintern. Gọi là Quốc tế thứ ba vì trước đó đã có Quốc tế thứ nhất do Các Mác tham gia sáng lập năm 1864 và Quốc tế thứ hai thành lập năm 1889. Quốc tế thứ hai về thực chất đã tan rã khi phần lớn các đảng thành viên ủng hộ chính phủ nước mình trong Chiến tranh thế giới thứ nhất.\n\nQuốc tế Cộng sản được tổ chức như một chính đảng thế giới. Mỗi đảng cộng sản ở từng nước là một phân bộ, phải tuân theo nghị quyết của đại hội và của Ban Chấp hành đặt trụ sở ở Mátxcơva. Từ năm 1919 đến năm 1935, tổ chức này họp bảy kỳ đại hội. Bên cạnh đó là cả một bộ máy: các ban phụ trách từng khu vực, các trường đào tạo cán bộ, các tổ chức quốc tế của nông dân, công đoàn, thanh niên, và một hệ thống báo chí xuất bản bằng nhiều thứ tiếng.","doc":2},{"loai":"anh","src":"textures/bang_w/G08_12_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Quốc tế Cộng sản”, nhìn từ xa."},{"loai":"doan","tieu_de":"Câu hỏi của người dân thuộc địa","text":"Điều khiến Nguyễn Ái Quốc tìm đến Quốc tế thứ ba không phải là những tranh luận lý thuyết, mà là thái độ của tổ chức này đối với các dân tộc thuộc địa. Đại hội II Quốc tế Cộng sản, họp mùa hè năm 1920, thảo luận bản Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của Lênin. Ngày 16 và 17/7/1920, báo L'Humanité ở Paris đăng văn kiện ấy. Nguyễn Ái Quốc đọc và tìm thấy câu trả lời cho điều Người trăn trở từ ngày rời bến Nhà Rồng năm 1911.\n\nTháng 12/1920, tại Đại hội Tua của Đảng Xã hội Pháp, Người bỏ phiếu tán thành gia nhập Quốc tế thứ ba và trở thành một trong những người tham gia sáng lập Đảng Cộng sản Pháp. Với Người, lá phiếu ấy là sự lựa chọn một con đường: đứng về phía tổ chức quốc tế coi sự nghiệp giải phóng các dân tộc thuộc địa là một phần của cách mạng thế giới. Bốn mươi năm sau, trong bài viết “Con đường dẫn tôi đến chủ nghĩa Lênin”, Người kể lại cảm xúc khi lần đầu đọc bản luận cương trong căn phòng nhỏ ở Paris.","doc":3},{"loai":"trich","text":"Luận cương của Lênin làm cho tôi rất cảm động, phấn khởi, sáng tỏ, tin tưởng biết bao! Tôi vui mừng đến phát khóc lên. Ngồi một mình trong buồng mà tôi nói to lên như đang nói trước quần chúng đông đảo: “Hỡi đồng bào bị đọa đày đau khổ! Đây là cái cần thiết cho chúng ta, đây là con đường giải phóng chúng ta!”. Từ đó tôi hoàn toàn tin theo Lênin, tin theo Quốc tế thứ ba.","nguoi":"Hồ Chí Minh","nguon_ten":"“Con đường dẫn tôi đến chủ nghĩa Lênin”, bài viết tháng 4/1960 — Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia","doc":4},{"loai":"doan","tieu_de":"Bộ máy ở Mátxcơva","text":"Khi Nguyễn Ái Quốc đến Mátxcơva mùa hè năm 1923, Quốc tế Cộng sản đã là một bộ máy lớn. Ban Chấp hành với Đoàn Chủ tịch điều hành công việc giữa hai kỳ đại hội. Các ban khu vực theo dõi phong trào ở từng vùng; Ban Phương Đông phụ trách các nước châu Á, nơi Người được nhận làm cán bộ. Gắn với Quốc tế Cộng sản còn có các trường đào tạo cán bộ: Trường Đại học Cộng sản của những người lao động phương Đông mở năm 1921, nơi Người theo học lớp ngắn hạn, và Trường Quốc tế Lê-nin thành lập năm 1926, nơi Người học trong chặng thứ hai ở Liên Xô.\n\nTổ chức này có một tờ thông tấn riêng, thường gọi tắt là Inprekorr, in bằng tiếng Đức, tiếng Anh và tiếng Pháp. Bản tiếng Pháp mang tên La Correspondance internationale. Nguyễn Ái Quốc viết nhiều bài cho tờ báo này. Theo Biên niên tiểu sử, ngày 9/10/1924, bản tiếng Pháp đăng bài của Người lên án nạn hành hình kiểu Linsơ nhắm vào người da đen ở Mỹ. Qua những trang báo ấy, tiếng nói của một người dân thuộc địa đến với bạn đọc cộng sản nhiều nước.","doc":5},{"loai":"anh","src":"textures/ht/ht_anh_advisory_delegate_card_issued_to_nguyen_ai_quoc_.jpg","chu_thich":"Thẻ đại biểu tư vấn cấp cho Nguyễn Ái Quốc tại Đại hội V Quốc tế Cộng sản, Mátxcơva, năm 1924.","credit":"Ảnh: 5th Congress of the Communist Internatio · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Cán bộ Ban Phương Đông","text":"Làm việc ở Ban Phương Đông, Nguyễn Ái Quốc có điều kiện đưa tình hình Đông Dương vào các báo cáo và thảo luận chính thức của phong trào. Người kiên trì nhắc các đảng cộng sản ở chính quốc về trách nhiệm đối với thuộc địa; tiếng nói ấy vang lên trên diễn đàn Đại hội V mùa hè năm 1924 (xem chuyên đề Thẻ đại biểu tư vấn Đại hội V, 1924). Nhưng mong muốn lớn nhất của Người vẫn là được trở về gần Tổ quốc.\n\nNgày 25/9/1924, Ban Chấp hành Quốc tế Cộng sản quyết định: “Đồng chí Nguyễn Ái Quốc cần đi Quảng Châu. Chi phí do Ban Phương Đông chịu.” Cuối tháng 10/1924, Người rời Mátxcơva. Ngày 11/11/1924, Người tới Quảng Châu. Hôm sau, Người viết thư báo tin, ngắn gọn: “Chỉ có một dòng chữ để báo cho đồng chí biết rằng tôi đã đến đây hôm qua, và đang ở nhà đồng chí Bôrôđin.” Bôrôđin là trưởng đoàn cố vấn Liên Xô bên cạnh chính phủ Tôn Trung Sơn. Ở Quảng Châu, với tên gọi Lý Thụy, danh nghĩa công khai của Người là phiên dịch cho đoàn cố vấn, còn nhiệm vụ thật là cán bộ của Quốc tế Cộng sản.","doc":6},{"loai":"ban_co_biet","text":"Trong bức thư đầu tiên gửi từ Quảng Châu ngày 12/11/1924, Nguyễn Ái Quốc ghi địa chỉ liên lạc là “Ô. Lu, Hãng thông tấn Rôxta, Quảng Châu, Trung Quốc”, thêm một cái tên nữa vào danh sách dài những bí danh của Người trong những năm hoạt động bí mật.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử, tập 1, NXB Chính trị quốc gia (mục ngày 12/11/1924)","doc":7},{"loai":"doan","tieu_de":"Phái viên của Quốc tế Cộng sản","text":"Mối liên hệ với Quốc tế Cộng sản theo Người suốt những năm sau đó, qua Quảng Châu, Mátxcơva, châu Âu và Xiêm. Năm 1929, phong trào cộng sản ở Việt Nam đứng trước nguy cơ chia rẽ: ba tổ chức cộng sản lần lượt ra đời, hoạt động riêng rẽ và tranh giành ảnh hưởng. Ngày 27/10/1929, Quốc tế Cộng sản gửi những người cộng sản Đông Dương văn kiện về việc thành lập một đảng cộng sản ở Đông Dương.\n\nVới tư cách phái viên của Quốc tế Cộng sản, Nguyễn Ái Quốc từ Xiêm sang Trung Quốc, triệu tập và chủ trì hội nghị hợp nhất, họp từ ngày 6/1 đến 7/2/1930 tại Cửu Long, Hương Cảng. Hội nghị thành lập Đảng Cộng sản Việt Nam. Tháng 10/1930, Đảng đổi tên thành Đảng Cộng sản Đông Dương. Tháng 4/1931, Quốc tế Cộng sản công nhận Đảng là một phân bộ độc lập, hai tháng trước khi Nguyễn Ái Quốc bị cảnh sát Anh bắt ở Hồng Kông ngày 6/6/1931. Năm 1924, Người dự Đại hội V với tấm thẻ đại biểu tư vấn vì quê hương chưa có đảng cộng sản; bảy năm sau, Đông Dương đã có một phân bộ riêng trong Quốc tế.","doc":8},{"loai":"anh","src":"textures/bang_w/G08_12_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Quốc tế Cộng sản”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Chặng Mátxcơva thứ hai","text":"Ra khỏi nhà tù Hồng Kông, sau nhiều chặng đường bí mật, giữa năm 1934 Người trở lại Mátxcơva (xem chuyên đề Đồng chí Lin ở Mátxcơva, 1934 – 1938). Lần này, Người vừa học tập vừa nghiên cứu trong chính hệ thống trường, viện gắn với Quốc tế Cộng sản. Mùa hè năm 1935, Đại hội VII họp tại Mátxcơva, đề ra chủ trương lập mặt trận nhân dân rộng rãi chống chủ nghĩa phát xít và nguy cơ chiến tranh. Đông Dương có đoàn đại biểu chính thức do Lê Hồng Phong dẫn đầu, và Lê Hồng Phong được bầu làm Ủy viên Ban Chấp hành Quốc tế Cộng sản. Đó cũng là đại hội cuối cùng của tổ chức này.\n\nNhững năm tiếp theo là thời kỳ khó khăn. Các cuộc thanh trừng chính trị ở Liên Xô ảnh hưởng tới nhiều cán bộ Quốc tế Cộng sản đến từ các nước. Nguyễn Ái Quốc vẫn kiên trì học tập và nhiều lần đề nghị được trở về hoạt động. Cuối năm 1938, đề nghị được chấp thuận; Người rời Mátxcơva sang Trung Quốc, bắt đầu hành trình đưa Người về Pác Bó ngày 28/1/1941.","doc":9},{"loai":"doan","tieu_de":"Khi Quốc tế giải tán","text":"Ngày 15/5/1943, giữa lúc Chiến tranh thế giới thứ hai đang ở giai đoạn quyết liệt, Đoàn Chủ tịch Ban Chấp hành Quốc tế Cộng sản thông qua nghị quyết đề nghị giải tán tổ chức. Nghị quyết nêu rằng hình thức một trung tâm lãnh đạo chung cho phong trào cộng sản toàn thế giới không còn phù hợp; mỗi đảng cần tự quyết định đường lối theo hoàn cảnh nước mình. Khi ấy, Hồ Chí Minh đang bị chính quyền Tưởng Giới Thạch giam giữ ở Quảng Tây; Người bị bắt từ cuối tháng 8/1942.\n\nNhưng con đường cách mạng Việt Nam đã được xác định từ trước. Hội nghị Trung ương lần thứ tám do Nguyễn Ái Quốc chủ trì, họp ở Pác Bó tháng 5/1941, đặt nhiệm vụ giải phóng dân tộc lên hàng đầu và quyết định thành lập Mặt trận Việt Minh. Chính sự vận dụng sáng tạo ấy đã đưa tới thắng lợi của Cách mạng Tháng Tám năm 1945. Hai mươi ba năm gắn bó ấy, từ lá phiếu ở Tua đến ngày tổ chức giải tán, là quãng thời gian Nguyễn Ái Quốc vừa học hỏi, vừa đóng góp. Cũng trong quãng ấy, Người trưởng thành thành người lãnh đạo của cách mạng Việt Nam.","doc":10},{"loai":"ban_co_biet","text":"Quốc tế ca, bài ca của phong trào cộng sản quốc tế, từng là quốc ca của Liên Xô. Chỉ vài tháng sau khi Quốc tế Cộng sản giải tán, đầu năm 1944, Liên Xô thay Quốc tế ca bằng một bài quốc ca mới.","nguon_ten":"Bách khoa toàn thư Britannica, mục The Internationale","doc":11},{"loai":"anh","src":"textures/bang_w/G08_12_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Quốc tế Cộng sản”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay: những trang hồ sơ ở Mátxcơva","text":"Quốc tế Cộng sản không còn, nhưng dấu vết của nó vẫn nằm trong một khối hồ sơ đồ sộ. Kho lưu trữ của tổ chức này nay được bảo quản tại Mátxcơva, trong Lưu trữ Quốc gia Nga về lịch sử chính trị – xã hội; tài liệu của Ban Chấp hành mang số phông 495. Trong đó có những bức thư, bản báo cáo, quyết định phân công liên quan tới Nguyễn Ái Quốc qua nhiều giai đoạn. Từ những năm 1990, khi kho lưu trữ mở rộng cho giới nghiên cứu, nhiều văn bản đã được các nhà sử học Việt Nam và nước ngoài khai thác.\n\nTạp chí Xưa và Nay số 259, tháng 5/2006, đăng bài nghiên cứu của nhà sử học Sophie Quinn-Judge về các sử liệu mới tìm thấy trong lưu trữ Quốc tế Cộng sản. Nhiều văn bản khác được dẫn trong Hồ Chí Minh – Biên niên tiểu sử và Hồ Chí Minh Toàn tập. Những chi tiết như mức lương 6 trécnôvéc hay dòng thư ngắn từ Quảng Châu năm 1924 được ghi lại từ các văn bản của Quốc tế Cộng sản. Trong gian trưng bày, tấm bảng này đặt giữa khung cảnh Quảng trường Đỏ, nhắc rằng hành trình của Người ở Mátxcơva không chỉ có tuyết lạnh, mà còn có những trang hồ sơ lặng lẽ.","doc":12}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 1 và tập 2, NXB Chính trị quốc gia","Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia – bài “Con đường dẫn tôi đến chủ nghĩa Lênin” (4/1960)","Lịch sử Đảng Cộng sản Việt Nam, NXB Chính trị quốc gia","Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch – Nguyễn Ái Quốc trên đất nước của Lênin (1923 – 1924), https://nhasanbacho.vn/bai-viet/nguyen-ai-quoc-tren-dat-nuoc-cua-lenin-1923-1924-222/","Sophie Quinn-Judge, “Nguyễn Ái Quốc với Quốc tế cộng sản qua lưu trữ của Quốc tế cộng sản”, Xưa và Nay số 259 (5/2006), https://vusta.vn/nguyen-ai-quoc-voi-quoc-te-cong-san-qua-luu-tru-cua-quoc-te-cong-san-p80621.html","Bảo tàng Hồ Chí Minh"],"doc":[{"t":"Quốc tế Cộng sản và Nguyễn Ái Quốc: hai mươi ba năm gắn bó (1920 – 1943). Hồ Chí Minh – Biên niên tiểu sử ghi lại một quyết định ngày 14/4/1924 của Quốc tế Cộng sản: nhận Nguyễn Ái Quốc làm cán bộ Ban Phương Đông, lương mỗi tháng 6 trécnôvéc. Tờ giấy hành chính ấy là một mắt xích trong mối gắn bó kéo dài gần một phần tư thế kỷ. Quốc tế Cộng sản là tổ chức thế nào, và vì sao người thanh niên yêu nước Việt Nam lại chọn đi cùng nó?"},{"t":"Sáu trécnôvéc mỗi tháng. Ngày 14/4/1924, Ban Phương Đông của Quốc tế Cộng sản quyết định nhận Nguyễn Ái Quốc làm cán bộ, với mức lương hằng tháng 6 trécnôvéc, tương đương 60 rúp. Trécnôvéc là loại tiền có bảo đảm bằng vàng mà nước Nga Xô-viết phát hành từ cuối năm 1922 để ổn định tài chính sau những năm nội chiến. Ba ngày trước đó, ngày 11/4/1924, Người đã gửi thư đề nghị được sang Trung Quốc để từ đó tìm đường về Đông Dương. Người muốn xây dựng quan hệ giữa phong trào ở Đông Dương với Quốc tế Cộng sản và tổ chức công tác tuyên truyền ngay gần quê hương. Những tờ giấy khô khan ấy cho thấy một điều quan trọng. Chưa đầy một năm sau khi lặng lẽ rời Paris, người thanh niên thuộc địa đã trở thành cán bộ chính thức trong bộ máy của phong trào cộng sản quốc tế, với một mục tiêu rất rõ: trở về phương Đông. Để hiểu vì sao Người tìm đến tổ chức này, cần trở lại mùa xuân năm 1919, khi Quốc tế Cộng sản ra đời."},{"t":"Mùa xuân năm 1919 ở Mátxcơva. Từ ngày 2 đến 6/3/1919, giữa lúc nước Nga Xô-viết đang bị nội chiến và can thiệp nước ngoài bao vây, một hội nghị quốc tế họp tại Mátxcơva theo sáng kiến của Lênin. Hội nghị tuyên bố thành lập Quốc tế Cộng sản, còn gọi là Quốc tế thứ ba, viết tắt theo tiếng Nga là Comintern. Gọi là Quốc tế thứ ba vì trước đó đã có Quốc tế thứ nhất do Các Mác tham gia sáng lập năm 1864 và Quốc tế thứ hai thành lập năm 1889. Quốc tế thứ hai về thực chất đã tan rã khi phần lớn các đảng thành viên ủng hộ chính phủ nước mình trong Chiến tranh thế giới thứ nhất. Quốc tế Cộng sản được tổ chức như một chính đảng thế giới. Mỗi đảng cộng sản ở từng nước là một phân bộ, phải tuân theo nghị quyết của đại hội và của Ban Chấp hành đặt trụ sở ở Mátxcơva. Từ năm 1919 đến năm 1935, tổ chức này họp bảy kỳ đại hội. Bên cạnh đó là cả một bộ máy: các ban phụ trách từng khu vực, các trường đào tạo cán bộ, các tổ chức quốc tế của nông dân, công đoàn, thanh niên, và một hệ thống báo chí xuất bản bằng nhiều thứ tiếng."},{"t":"Câu hỏi của người dân thuộc địa. Điều khiến Nguyễn Ái Quốc tìm đến Quốc tế thứ ba không phải là những tranh luận lý thuyết, mà là thái độ của tổ chức này đối với các dân tộc thuộc địa. Đại hội II Quốc tế Cộng sản, họp mùa hè năm 1920, thảo luận bản Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của Lênin. Ngày 16 và 17/7/1920, báo L'Humanité ở Paris đăng văn kiện ấy. Nguyễn Ái Quốc đọc và tìm thấy câu trả lời cho điều Người trăn trở từ ngày rời bến Nhà Rồng năm 1911. Tháng 12/1920, tại Đại hội Tua của Đảng Xã hội Pháp, Người bỏ phiếu tán thành gia nhập Quốc tế thứ ba và trở thành một trong những người tham gia sáng lập Đảng Cộng sản Pháp. Với Người, lá phiếu ấy là sự lựa chọn một con đường: đứng về phía tổ chức quốc tế coi sự nghiệp giải phóng các dân tộc thuộc địa là một phần của cách mạng thế giới. Bốn mươi năm sau, trong bài viết “Con đường dẫn tôi đến chủ nghĩa Lênin”, Người kể lại cảm xúc khi lần đầu đọc bản luận cương trong căn phòng nhỏ ở Paris."},{"t":"Luận cương của Lênin làm cho tôi rất cảm động, phấn khởi, sáng tỏ, tin tưởng biết bao! Tôi vui mừng đến phát khóc lên. Ngồi một mình trong buồng mà tôi nói to lên như đang nói trước quần chúng đông đảo: “Hỡi đồng bào bị đọa đày đau khổ! Đây là cái cần thiết cho chúng ta, đây là con đường giải phóng chúng ta!”. Từ đó tôi hoàn toàn tin theo Lênin, tin theo Quốc tế thứ ba. — Hồ Chí Minh"},{"t":"Bộ máy ở Mátxcơva. Khi Nguyễn Ái Quốc đến Mátxcơva mùa hè năm 1923, Quốc tế Cộng sản đã là một bộ máy lớn. Ban Chấp hành với Đoàn Chủ tịch điều hành công việc giữa hai kỳ đại hội. Các ban khu vực theo dõi phong trào ở từng vùng; Ban Phương Đông phụ trách các nước châu Á, nơi Người được nhận làm cán bộ. Gắn với Quốc tế Cộng sản còn có các trường đào tạo cán bộ: Trường Đại học Cộng sản của những người lao động phương Đông mở năm 1921, nơi Người theo học lớp ngắn hạn, và Trường Quốc tế Lê-nin thành lập năm 1926, nơi Người học trong chặng thứ hai ở Liên Xô. Tổ chức này có một tờ thông tấn riêng, thường gọi tắt là Inprekorr, in bằng tiếng Đức, tiếng Anh và tiếng Pháp. Bản tiếng Pháp mang tên La Correspondance internationale. Nguyễn Ái Quốc viết nhiều bài cho tờ báo này. Theo Biên niên tiểu sử, ngày 9/10/1924, bản tiếng Pháp đăng bài của Người lên án nạn hành hình kiểu Linsơ nhắm vào người da đen ở Mỹ. Qua những trang báo ấy, tiếng nói của một người dân thuộc địa đến với bạn đọc cộng sản nhiều nước."},{"t":"Cán bộ Ban Phương Đông. Làm việc ở Ban Phương Đông, Nguyễn Ái Quốc có điều kiện đưa tình hình Đông Dương vào các báo cáo và thảo luận chính thức của phong trào. Người kiên trì nhắc các đảng cộng sản ở chính quốc về trách nhiệm đối với thuộc địa; tiếng nói ấy vang lên trên diễn đàn Đại hội V mùa hè năm 1924 (xem chuyên đề Thẻ đại biểu tư vấn Đại hội V, 1924). Nhưng mong muốn lớn nhất của Người vẫn là được trở về gần Tổ quốc. Ngày 25/9/1924, Ban Chấp hành Quốc tế Cộng sản quyết định: “Đồng chí Nguyễn Ái Quốc cần đi Quảng Châu. Chi phí do Ban Phương Đông chịu.” Cuối tháng 10/1924, Người rời Mátxcơva. Ngày 11/11/1924, Người tới Quảng Châu. Hôm sau, Người viết thư báo tin, ngắn gọn: “Chỉ có một dòng chữ để báo cho đồng chí biết rằng tôi đã đến đây hôm qua, và đang ở nhà đồng chí Bôrôđin.” Bôrôđin là trưởng đoàn cố vấn Liên Xô bên cạnh chính phủ Tôn Trung Sơn. Ở Quảng Châu, với tên gọi Lý Thụy, danh nghĩa công khai của Người là phiên dịch cho đoàn cố vấn, còn nhiệm vụ thật là cán bộ của Quốc tế Cộng sản."},{"t":"Bạn có biết? Trong bức thư đầu tiên gửi từ Quảng Châu ngày 12/11/1924, Nguyễn Ái Quốc ghi địa chỉ liên lạc là “Ô. Lu, Hãng thông tấn Rôxta, Quảng Châu, Trung Quốc”, thêm một cái tên nữa vào danh sách dài những bí danh của Người trong những năm hoạt động bí mật."},{"t":"Phái viên của Quốc tế Cộng sản. Mối liên hệ với Quốc tế Cộng sản theo Người suốt những năm sau đó, qua Quảng Châu, Mátxcơva, châu Âu và Xiêm. Năm 1929, phong trào cộng sản ở Việt Nam đứng trước nguy cơ chia rẽ: ba tổ chức cộng sản lần lượt ra đời, hoạt động riêng rẽ và tranh giành ảnh hưởng. Ngày 27/10/1929, Quốc tế Cộng sản gửi những người cộng sản Đông Dương văn kiện về việc thành lập một đảng cộng sản ở Đông Dương. Với tư cách phái viên của Quốc tế Cộng sản, Nguyễn Ái Quốc từ Xiêm sang Trung Quốc, triệu tập và chủ trì hội nghị hợp nhất, họp từ ngày 6/1 đến 7/2/1930 tại Cửu Long, Hương Cảng. Hội nghị thành lập Đảng Cộng sản Việt Nam. Tháng 10/1930, Đảng đổi tên thành Đảng Cộng sản Đông Dương. Tháng 4/1931, Quốc tế Cộng sản công nhận Đảng là một phân bộ độc lập, hai tháng trước khi Nguyễn Ái Quốc bị cảnh sát Anh bắt ở Hồng Kông ngày 6/6/1931. Năm 1924, Người dự Đại hội V với tấm thẻ đại biểu tư vấn vì quê hương chưa có đảng cộng sản; bảy năm sau, Đông Dương đã có một phân bộ riêng trong Quốc tế."},{"t":"Chặng Mátxcơva thứ hai. Ra khỏi nhà tù Hồng Kông, sau nhiều chặng đường bí mật, giữa năm 1934 Người trở lại Mátxcơva (xem chuyên đề Đồng chí Lin ở Mátxcơva, 1934 – 1938). Lần này, Người vừa học tập vừa nghiên cứu trong chính hệ thống trường, viện gắn với Quốc tế Cộng sản. Mùa hè năm 1935, Đại hội VII họp tại Mátxcơva, đề ra chủ trương lập mặt trận nhân dân rộng rãi chống chủ nghĩa phát xít và nguy cơ chiến tranh. Đông Dương có đoàn đại biểu chính thức do Lê Hồng Phong dẫn đầu, và Lê Hồng Phong được bầu làm Ủy viên Ban Chấp hành Quốc tế Cộng sản. Đó cũng là đại hội cuối cùng của tổ chức này. Những năm tiếp theo là thời kỳ khó khăn. Các cuộc thanh trừng chính trị ở Liên Xô ảnh hưởng tới nhiều cán bộ Quốc tế Cộng sản đến từ các nước. Nguyễn Ái Quốc vẫn kiên trì học tập và nhiều lần đề nghị được trở về hoạt động. Cuối năm 1938, đề nghị được chấp thuận; Người rời Mátxcơva sang Trung Quốc, bắt đầu hành trình đưa Người về Pác Bó ngày 28/1/1941."},{"t":"Khi Quốc tế giải tán. Ngày 15/5/1943, giữa lúc Chiến tranh thế giới thứ hai đang ở giai đoạn quyết liệt, Đoàn Chủ tịch Ban Chấp hành Quốc tế Cộng sản thông qua nghị quyết đề nghị giải tán tổ chức. Nghị quyết nêu rằng hình thức một trung tâm lãnh đạo chung cho phong trào cộng sản toàn thế giới không còn phù hợp; mỗi đảng cần tự quyết định đường lối theo hoàn cảnh nước mình. Khi ấy, Hồ Chí Minh đang bị chính quyền Tưởng Giới Thạch giam giữ ở Quảng Tây; Người bị bắt từ cuối tháng 8/1942. Nhưng con đường cách mạng Việt Nam đã được xác định từ trước. Hội nghị Trung ương lần thứ tám do Nguyễn Ái Quốc chủ trì, họp ở Pác Bó tháng 5/1941, đặt nhiệm vụ giải phóng dân tộc lên hàng đầu và quyết định thành lập Mặt trận Việt Minh. Chính sự vận dụng sáng tạo ấy đã đưa tới thắng lợi của Cách mạng Tháng Tám năm 1945. Hai mươi ba năm gắn bó ấy, từ lá phiếu ở Tua đến ngày tổ chức giải tán, là quãng thời gian Nguyễn Ái Quốc vừa học hỏi, vừa đóng góp. Cũng trong quãng ấy, Người trưởng thành thành người lãnh đạo của cách mạng Việt Nam."},{"t":"Bạn có biết? Quốc tế ca, bài ca của phong trào cộng sản quốc tế, từng là quốc ca của Liên Xô. Chỉ vài tháng sau khi Quốc tế Cộng sản giải tán, đầu năm 1944, Liên Xô thay Quốc tế ca bằng một bài quốc ca mới."},{"t":"Dấu tích hôm nay: những trang hồ sơ ở Mátxcơva. Quốc tế Cộng sản không còn, nhưng dấu vết của nó vẫn nằm trong một khối hồ sơ đồ sộ. Kho lưu trữ của tổ chức này nay được bảo quản tại Mátxcơva, trong Lưu trữ Quốc gia Nga về lịch sử chính trị – xã hội; tài liệu của Ban Chấp hành mang số phông 495. Trong đó có những bức thư, bản báo cáo, quyết định phân công liên quan tới Nguyễn Ái Quốc qua nhiều giai đoạn. Từ những năm 1990, khi kho lưu trữ mở rộng cho giới nghiên cứu, nhiều văn bản đã được các nhà sử học Việt Nam và nước ngoài khai thác. Tạp chí Xưa và Nay số 259, tháng 5/2006, đăng bài nghiên cứu của nhà sử học Sophie Quinn-Judge về các sử liệu mới tìm thấy trong lưu trữ Quốc tế Cộng sản. Nhiều văn bản khác được dẫn trong Hồ Chí Minh – Biên niên tiểu sử và Hồ Chí Minh Toàn tập. Những chi tiết như mức lương 6 trécnôvéc hay dòng thư ngắn từ Quảng Châu năm 1924 được ghi lại từ các văn bản của Quốc tế Cộng sản. Trong gian trưng bày, tấm bảng này đặt giữa khung cảnh Quảng trường Đỏ, nhắc rằng hành trình của Người ở Mátxcơva không chỉ có tuyết lạnh, mà còn có những trang hồ sơ lặng lẽ."}],"so_chu":2146}],"do_vat":[]};
